// REALJEJU app.js - original JS order preserved / Ver 2.551

const globalBrandLink = document.querySelector('.global-brand');
if (globalBrandLink) {
	globalBrandLink.addEventListener('click', () => {
		window.location.href = "https://realjeju.app";
	});
}

let mapFilterScrollSyncRaf = null;
let mapFilterPreserveRightEdgeOnNextSync = false;
let mapFilterManualScrollUntil = 0;
const MAP_FILTER_SCROLL_EDGE_PADDING = 44;
const mapFilterScrollState = {
	wasAtRightEdge: false,
	maxScrollLeft: 0
};

function getMapFilterLeftPanelSafeLeft()
{
	if (!document.body || document.body.classList.contains("sidebar-list-collapsed")) return 8;
	const rightEdge = getMapFilterVisiblePanelRightEdge();
	return rightEdge > 0 ? Math.min(window.innerWidth - 80, Math.round(rightEdge + 16)) : 8;
}

function getMapFilterVisiblePanelRightEdge()
{
	if (!document.body) return 0;
	const candidates = [];
	if (!document.body.classList.contains("sidebar-list-collapsed")) {
		candidates.push(
			document.querySelector(".sidebar-list-panel"),
			document.getElementById("sidebarDetailPanel")
		);
	}
	candidates.push(document.querySelector(".education-facility-detail-panel.open"));
	let rightEdge = 0;
	candidates.forEach((panel) => {
		if (!panel || !(panel instanceof HTMLElement)) return;
		const style = window.getComputedStyle(panel);
		const rect = panel.getBoundingClientRect();
		if (style.display === "none" || style.visibility === "hidden" || style.opacity === "0") return;
		if (rect.width < 20 || rect.height < 20 || rect.right <= 0 || rect.left >= window.innerWidth) return;
		rightEdge = Math.max(rightEdge, rect.right);
	});
	return rightEdge;
}

function syncMapFilterVisiblePanelEdge()
{
	const rightEdge = getMapFilterVisiblePanelRightEdge();
	document.documentElement.style.setProperty("--map-filter-visible-panel-right", `${Math.max(0, Math.round(rightEdge))}px`);
}

function getMapFilterLeftArrowLeft()
{
	const buttonWidth = 34;
	const gap = 18;
	const fallbackNavWidth = parseFloat(getComputedStyle(document.documentElement).getPropertyValue("--realjeju-side-nav-width")) || 170;
	const edge = Math.max(fallbackNavWidth, getMapFilterVisiblePanelRightEdge());
	return Math.max(8, Math.min(window.innerWidth - buttonWidth - 8, Math.round(edge + gap)));
}

function getMapFilterRightArrowLeft()
{
	const buttonWidth = 34;
	const gap = 18;
	const propertyButton = document.getElementById("mapPropertyToggleBtn");
	if (propertyButton && propertyButton instanceof HTMLElement) {
		const style = window.getComputedStyle(propertyButton);
		const rect = propertyButton.getBoundingClientRect();
		if (style.display !== "none" && style.visibility !== "hidden" && rect.width > 0 && rect.height > 0) {
			return Math.max(8, Math.round(rect.left - gap - buttonWidth));
		}
	}
	const rightGap = getMapFilterRightSafeGap();
	return Math.max(8, Math.round(window.innerWidth - rightGap - gap - buttonWidth));
}

function getMapFilterButtonRowTop()
{
	const selectors = [
		".map-region-filter-trigger",
		".all-filter-trigger",
		".extra-filter-trigger",
		".type-filter-trigger",
		".deal-filter-trigger",
		".deal-method-filter-trigger",
		".price-filter-trigger",
		".area-filter-trigger",
		".room-bath-filter-trigger",
		".floor-direction-filter-trigger",
		".approval-year-filter-trigger",
		".extra-condition-filter-trigger",
		".location-analysis-trigger"
	].map((selector) => `#topbarMenu .map-filter-scroll-track ${selector}`).join(",");
	const trigger = Array.from(document.querySelectorAll(selectors)).find((el) => {
		if (!el || !(el instanceof HTMLElement)) return false;
		const style = window.getComputedStyle(el);
		const rect = el.getBoundingClientRect();
		return style.display !== "none" && style.visibility !== "hidden" && rect.width > 0 && rect.height > 0;
	});
	if (trigger) {
		return Math.round(trigger.getBoundingClientRect().top);
	}
	const track = document.querySelector("#topbarMenu .map-filter-scroll-track");
	if (track) {
		const rect = track.getBoundingClientRect();
		if (rect.height > 0) return Math.round(rect.top + ((rect.height - 34) / 2));
	}
	return 98;
}

function positionMapFilterScrollArrows()
{
	const topbarMenu = document.getElementById("topbarMenu");
	const track = document.querySelector("#topbarMenu .map-filter-scroll-track");
	const controls = document.querySelector("#topbarMenu .map-filter-scroll-controls");
	if (!controls) return;
	syncMapFilterVisiblePanelEdge();
	const top = getMapFilterButtonRowTop();
	const leftArrowLeft = getMapFilterLeftArrowLeft();
	const rightArrowLeft = getMapFilterRightArrowLeft();
	controls.style.setProperty("--map-filter-arrow-top", `${Math.max(8, top)}px`);
	controls.style.setProperty("--map-filter-left-arrow-left", `${leftArrowLeft}px`);
	controls.style.setProperty("--map-filter-right-arrow-left", `${rightArrowLeft}px`);
	if (topbarMenu && track) {
		const trackRect = track.getBoundingClientRect();
		const shell = track.closest(".map-filter-scroll-shell");
		const hasLeftScroll = Boolean(shell && shell.classList.contains("has-left-scroll"));
		const hasRightScroll = Boolean(shell && shell.classList.contains("has-right-scroll"));
		const arrowCenterOffset = 17;
		const leftClip = hasLeftScroll ? Math.max(0, Math.round(leftArrowLeft + arrowCenterOffset - trackRect.left)) : 0;
		const rightClip = hasRightScroll ? Math.max(0, Math.round(trackRect.right - (rightArrowLeft + arrowCenterOffset))) : 0;
		topbarMenu.style.setProperty("--map-filter-track-mask-left", `${leftClip}px`);
		topbarMenu.style.setProperty("--map-filter-track-mask-right", `${rightClip}px`);
		track.style.removeProperty("clip-path");
	}
}

function isRenderableMapFilterElement(el)
{
	if (!el || !(el instanceof HTMLElement)) return false;
	const style = window.getComputedStyle(el);
	const rect = el.getBoundingClientRect();
	return style.display !== "none"
		&& style.visibility !== "hidden"
		&& rect.width > 0
		&& rect.height > 0
		&& el.offsetWidth > 0;
}

function getMapFilterScrollTrack()
{
	return document.querySelector("#topbarMenu .map-filter-scroll-track");
}

function positionOpenMapFilterMenus()
{
	if (typeof syncFloatingMapFilterMenus === "function") {
		syncFloatingMapFilterMenus();
	}
	document.querySelectorAll(".global-topbar-menu.has-map-filters .extra-filter-dropdown.open").forEach((dropdown) => {
		positionMapFilterMenu(dropdown);
	});
}

function getMapFilterRightSafeGap()
{
	const propertyButton = document.getElementById("mapPropertyToggleBtn");
	if (propertyButton && propertyButton instanceof HTMLElement) {
		const style = window.getComputedStyle(propertyButton);
		const rect = propertyButton.getBoundingClientRect();
		if (style.display !== "none" && style.visibility !== "hidden" && rect.width > 0 && rect.height > 0) {
			return Math.max(8, window.innerWidth - rect.left + 18);
		}
	}
	const sideTools = document.getElementById("mapSideTools") || document.querySelector(".map-side-tools");
	if (!sideTools) return 8;
	const rect = sideTools.getBoundingClientRect();
	if (!rect.width || !rect.height) return 8;
	return Math.max(8, window.innerWidth - rect.left + 16);
}

function alignMapFilterTriggerToRightSafeArea(trigger, menuWidth)
{
	const track = getMapFilterScrollTrack();
	if (!trigger || !track || !track.contains(trigger) || !menuWidth) return false;
	const rect = trigger.getBoundingClientRect();
	if (!rect.width && !rect.height) return false;
	const rightSafeGap = getMapFilterRightSafeGap();
	const maxTriggerLeft = window.innerWidth - rightSafeGap - menuWidth;
	const overflow = rect.left - maxTriggerLeft;
	if (overflow <= 1) return false;
	const filterBar = track.querySelector(".map-filter-bar");
	const contentWidth = filterBar ? filterBar.scrollWidth : track.scrollWidth;
	const maxScrollLeft = Math.max(0, contentWidth - track.clientWidth);
	if (track.scrollLeft > maxScrollLeft) track.scrollLeft = maxScrollLeft;
	const nextScrollLeft = Math.max(0, Math.min(maxScrollLeft, track.scrollLeft + overflow));
	if (Math.abs(nextScrollLeft - track.scrollLeft) <= 1) return false;
	track.scrollTo({ left: nextScrollLeft, behavior: "auto" });
	scheduleMapFilterScrollSync();
	return true;
}

function syncMapFilterRightSafeSpacer(filterBar)
{
	if (!filterBar) return;
	const rightSafeGap = getMapFilterRightSafeGap();
	filterBar.style.paddingRight = `${Math.max(0, rightSafeGap)}px`;
	filterBar.style.boxSizing = "content-box";
}

function getMapFilterConstrainedMenuLeft(trigger, menuWidth)
{
	if (!trigger) return 8;
	const rect = trigger.getBoundingClientRect();
	const safeGap = 8;
	const rightSafeGap = getMapFilterRightSafeGap();
	const panelSafeLeft = getMapFilterLeftPanelSafeLeft();
	const maxLeft = Math.max(safeGap, window.innerWidth - menuWidth - rightSafeGap);
	const minLeft = Math.min(Math.max(safeGap, panelSafeLeft), maxLeft);
	return Math.min(Math.max(minLeft, rect.left), maxLeft);
}

function alignMapFilterTriggerToMenuLeft(dropdown)
{
	const trigger = getMapFilterDropdownTrigger(dropdown);
	const track = getMapFilterScrollTrack();
	const menu = getMapFilterDropdownMenu(dropdown);
	if (!trigger || !track || !track.contains(trigger) || !menu) return false;

	const menuRect = menu.getBoundingClientRect();
	const menuWidth = menu.offsetWidth || menuRect.width || 240;
	const targetLeft = getMapFilterConstrainedMenuLeft(trigger, menuWidth);
	const rect = trigger.getBoundingClientRect();
	const delta = rect.left - targetLeft;
	if (Math.abs(delta) <= 2) return false;

	const filterBar = track.querySelector(".map-filter-bar");
	const contentWidth = filterBar ? filterBar.scrollWidth : track.scrollWidth;
	const maxScrollLeft = Math.max(0, contentWidth - track.clientWidth);
	const nextScrollLeft = Math.max(0, Math.min(maxScrollLeft, track.scrollLeft + delta));
	if (Math.abs(nextScrollLeft - track.scrollLeft) <= 1) return false;
	track.scrollTo({ left: nextScrollLeft, behavior: "auto" });
	return true;
}

function positionMapFilterMenu(dropdown)
{
	if (!dropdown) return;
	const trigger = getMapFilterDropdownTrigger(dropdown) || dropdown.querySelector(".extra-filter-trigger");
	const menu = getMapFilterDropdownMenu(dropdown);
	if (!trigger || !menu) return;
	if (dropdown.classList.contains("open")) {
		attachMapFilterMenuToFloatingLayer(dropdown, menu);
	}

	const rect = trigger.getBoundingClientRect();
	if (!rect.width && !rect.height) return;
	const menuRect = menu.getBoundingClientRect();
	const menuWidth = menu.offsetWidth || menuRect.width || 240;
	const left = getMapFilterConstrainedMenuLeft(trigger, menuWidth);
	const top = rect.bottom + 8;
	const safeBottom = parseFloat(getComputedStyle(document.documentElement).getPropertyValue("--rj-detail-panel-edge")) || 16;

	menu.style.position = "fixed";
	menu.style.left = `${Math.round(left)}px`;
	menu.style.top = `${Math.round(top)}px`;
	menu.style.right = "auto";
	menu.style.zIndex = "2147482500";
	if (menu.classList.contains("all-filter-menu")) {
		const availableHeight = Math.max(240, Math.floor(window.innerHeight - top - safeBottom));
		menu.style.maxHeight = `${availableHeight}px`;
	}
	menu.classList.add("is-map-filter-floating-open");
	menu.setAttribute("data-map-filter-owner", dropdown.id || "");
}

function getMapFilterDropdownMenu(dropdown)
{
	if (!dropdown) return null;
	if (dropdown.__mapFilterFloatingMenu && document.body.contains(dropdown.__mapFilterFloatingMenu)) {
		return dropdown.__mapFilterFloatingMenu;
	}
	const localMenu = dropdown.querySelector(".extra-filter-menu");
	if (localMenu) return localMenu;
	const id = dropdown.id || "";
	return id ? document.querySelector(`.map-filter-floating-menu[data-map-filter-owner="${CSS.escape(id)}"]`) : null;
}

function attachMapFilterMenuToFloatingLayer(dropdown, menu)
{
	if (!dropdown || !menu || menu.parentElement === document.body) return;
	const placeholder = document.createComment(`map-filter-menu:${dropdown.id || ""}`);
	menu.parentNode.insertBefore(placeholder, menu);
	dropdown.__mapFilterMenuPlaceholder = placeholder;
	dropdown.__mapFilterFloatingMenu = menu;
	menu.dataset.mapFilterOwner = dropdown.id || "";
	menu.classList.add("map-filter-floating-menu");
	document.body.appendChild(menu);
}

function restoreMapFilterMenuFromFloatingLayer(dropdown)
{
	if (!dropdown) return;
	const menu = getMapFilterDropdownMenu(dropdown);
	const placeholder = dropdown.__mapFilterMenuPlaceholder;
	if (!menu || menu.parentElement !== document.body || !placeholder || !placeholder.parentNode) return;
	menu.classList.remove("map-filter-floating-menu", "is-map-filter-floating-open");
	menu.removeAttribute("data-map-filter-owner");
	["position", "left", "top", "right", "zIndex", "maxHeight"].forEach((prop) => menu.style.removeProperty(prop));
	placeholder.parentNode.insertBefore(menu, placeholder);
	placeholder.parentNode.removeChild(placeholder);
	dropdown.__mapFilterMenuPlaceholder = null;
	dropdown.__mapFilterFloatingMenu = null;
}

function syncFloatingMapFilterMenus()
{
	document.querySelectorAll(".global-topbar-menu.has-map-filters .extra-filter-dropdown").forEach((dropdown) => {
		const menu = getMapFilterDropdownMenu(dropdown);
		if (!menu) return;
		if (dropdown.classList.contains("open")) {
			attachMapFilterMenuToFloatingLayer(dropdown, menu);
			positionMapFilterMenu(dropdown);
		} else {
			restoreMapFilterMenuFromFloatingLayer(dropdown);
		}
	});
}

function isMapFilterEventInsideDropdown(dropdown, target)
{
	if (!dropdown || !target) return false;
	if (dropdown.contains(target)) return true;
	const menu = getMapFilterDropdownMenu(dropdown);
	return !!(menu && menu.contains(target));
}

function getRealjejuPaymentPlanGuard()
{
	if (typeof window !== "undefined" && typeof window.realjejuGuardActivePaymentPlan === "function") {
		return window.realjejuGuardActivePaymentPlan;
	}
	if (typeof guardRealjejuActivePaymentPlan === "function") {
		return guardRealjejuActivePaymentPlan;
	}
	return null;
}

function shouldAlignOpenMapFilterToListEdge()
{
	return !!(
		document.body
		&& Date.now() > mapFilterManualScrollUntil
		&& !document.body.classList.contains("sidebar-list-collapsed")
		&& !document.body.classList.contains("map-detail-panel-active")
		&& !document.body.classList.contains("detail-page-panel-open")
	);
}

function alignMapFilterTriggerToListEdge(trigger)
{
	const track = getMapFilterScrollTrack();
	if (!trigger || !track || !track.contains(trigger)) return false;
	const trackRect = track.getBoundingClientRect();
	if (!trackRect.width) return false;
	const targetLeft = Math.max(
		trackRect.left + MAP_FILTER_SCROLL_EDGE_PADDING,
		getMapFilterLeftPanelSafeLeft()
	);
	const rect = trigger.getBoundingClientRect();
	const delta = rect.left - targetLeft;
	if (Math.abs(delta) <= 2) return false;
	const filterBar = track.querySelector(".map-filter-bar");
	const contentWidth = filterBar ? filterBar.scrollWidth : track.scrollWidth;
	const maxScrollLeft = Math.max(0, contentWidth - track.clientWidth);
	if (track.scrollLeft > maxScrollLeft) track.scrollLeft = maxScrollLeft;
	const nextScrollLeft = Math.max(0, Math.min(maxScrollLeft, track.scrollLeft + delta));
	if (Math.abs(nextScrollLeft - track.scrollLeft) <= 1) return false;
	track.scrollTo({ left: nextScrollLeft, behavior: "auto" });
	return true;
}

function isMapFilterTriggerAwayFromListEdge(trigger)
{
	const track = getMapFilterScrollTrack();
	if (!trigger || !track || !track.contains(trigger)) return false;
	const trackRect = track.getBoundingClientRect();
	if (!trackRect.width) return false;
	const targetLeft = Math.max(
		trackRect.left + MAP_FILTER_SCROLL_EDGE_PADDING,
		getMapFilterLeftPanelSafeLeft()
	);
	const rect = trigger.getBoundingClientRect();
	return Math.abs(rect.left - targetLeft) > 2;
}

function ensureMapFilterTriggerVisible(trigger, options = {})
{
	const track = getMapFilterScrollTrack();
	if (!trigger || !track || !track.contains(trigger)) return;

	if (options.alignToListEdge && shouldAlignOpenMapFilterToListEdge()) {
		alignMapFilterTriggerToListEdge(trigger);
	}

	const edgePadding = MAP_FILTER_SCROLL_EDGE_PADDING;
	const triggerLeft = trigger.offsetLeft;
	const triggerRight = triggerLeft + trigger.offsetWidth;
	const visibleLeft = track.scrollLeft + edgePadding;
	const visibleRight = track.scrollLeft + track.clientWidth - edgePadding;
	let nextScrollLeft = null;

	if (triggerLeft < visibleLeft) {
		nextScrollLeft = Math.max(0, triggerLeft - edgePadding);
	} else if (triggerRight > visibleRight) {
		nextScrollLeft = Math.min(
			track.scrollWidth - track.clientWidth,
			triggerRight - track.clientWidth + edgePadding
		);
	}

	if (nextScrollLeft !== null) {
		track.scrollTo({ left: nextScrollLeft, behavior: "auto" });
	}

	const safeLeft = getMapFilterLeftPanelSafeLeft();
	if (safeLeft > 8) {
		const rect = trigger.getBoundingClientRect();
		if (rect.left < safeLeft) {
			track.scrollLeft = Math.max(0, track.scrollLeft - (safeLeft - rect.left));
			scheduleMapFilterScrollSync();
		}
	}
}

function getMapFilterDropdownTrigger(dropdown)
{
	if (!dropdown) return null;
	return dropdown.querySelector(
		".map-region-filter-trigger, .all-filter-trigger, .extra-filter-trigger, .type-filter-trigger, .deal-filter-trigger, .deal-method-filter-trigger, .price-filter-trigger, .area-filter-trigger, .room-bath-filter-trigger, .floor-direction-filter-trigger, .approval-year-filter-trigger, .extra-condition-filter-trigger, .location-analysis-trigger, .sub-address-search-btn"
	);
}

function syncOpenMapFilterMenuPosition(dropdown)
{
	if (!dropdown || !dropdown.classList.contains("open")) return;
	const trigger = getMapFilterDropdownTrigger(dropdown);
	ensureMapFilterTriggerVisible(trigger, { alignToListEdge: true });
	alignMapFilterTriggerToMenuLeft(dropdown);
	positionMapFilterMenu(dropdown);
	requestAnimationFrame(() => {
		ensureMapFilterTriggerVisible(trigger, { alignToListEdge: true });
		alignMapFilterTriggerToMenuLeft(dropdown);
		positionMapFilterMenu(dropdown);
	});
	setTimeout(() => {
		ensureMapFilterTriggerVisible(trigger, { alignToListEdge: true });
		alignMapFilterTriggerToMenuLeft(dropdown);
		positionMapFilterMenu(dropdown);
	}, 60);
}

function syncMapFilterScrollControls()
{
	const shell = document.querySelector("#topbarMenu .map-filter-scroll-shell");
	if (!shell) return;

	const topbarMenu = document.getElementById("topbarMenu");
	const controls = topbarMenu ? topbarMenu.querySelector(".map-filter-scroll-controls") : null;
	const track = shell.querySelector(".map-filter-scroll-track");
	const filterBar = shell.querySelector(".map-filter-bar");
	const leftBtn = controls ? controls.querySelector(".map-filter-scroll-btn-left") : shell.querySelector(".map-filter-scroll-btn-left");
	const rightBtn = controls ? controls.querySelector(".map-filter-scroll-btn-right") : shell.querySelector(".map-filter-scroll-btn-right");
	if (!track) return;

	if (typeof syncMapFilterRightSafeSpacer === "function") {
		syncMapFilterRightSafeSpacer(filterBar);
	}
	positionMapFilterScrollArrows();

	const metrics = getMapFilterScrollMetrics(track);
	const maxScrollLeft = metrics.maxScrollLeft;
	if (track.scrollLeft > maxScrollLeft) {
		track.scrollLeft = maxScrollLeft;
	}
	if (track.scrollLeft < 0) {
		track.scrollLeft = 0;
	}

	const currentScrollLeft = Math.max(0, Math.min(maxScrollLeft, Number(track.scrollLeft) || 0));
	const overflow = maxScrollLeft > 1 || metrics.visualOverflowLeft || metrics.visualOverflowRight;
	const canScrollLeft = overflow && (currentScrollLeft > 1 || metrics.visualOverflowLeft);
	const canScrollRight = overflow && (currentScrollLeft < maxScrollLeft - 1 || metrics.visualOverflowRight);

	shell.classList.toggle("has-overflow", overflow);
	shell.classList.toggle("has-left-scroll", canScrollLeft);
	shell.classList.toggle("has-right-scroll", canScrollRight);
	if (topbarMenu) {
		topbarMenu.classList.toggle("has-left-scroll", canScrollLeft);
		topbarMenu.classList.toggle("has-right-scroll", canScrollRight);
	}

	if (leftBtn) {
		leftBtn.hidden = !canScrollLeft;
		leftBtn.disabled = false;
		leftBtn.classList.toggle("is-disabled", false);
	}
	if (rightBtn) {
		rightBtn.hidden = !canScrollRight;
		rightBtn.disabled = false;
		rightBtn.classList.toggle("is-disabled", false);
	}
	positionMapFilterScrollArrows();

	if (typeof mapFilterScrollState !== "undefined" && mapFilterScrollState) {
		mapFilterScrollState.canScrollLeft = canScrollLeft;
		mapFilterScrollState.canScrollRight = canScrollRight;
		mapFilterScrollState.maxScrollLeft = maxScrollLeft;
		mapFilterScrollState.wasAtRightEdge = overflow && !canScrollRight;
	}

	if (typeof positionOpenMapFilterMenus === "function") {
		positionOpenMapFilterMenus();
	}
}

function scheduleMapFilterScrollSync(options = {})
{
	if (options && options.preserveRightEdge === true) {
		if (Date.now() >= mapFilterManualScrollUntil) {
			mapFilterPreserveRightEdgeOnNextSync = true;
		} else {
			mapFilterPreserveRightEdgeOnNextSync = false;
		}
	}
	if (mapFilterScrollSyncRaf) cancelAnimationFrame(mapFilterScrollSyncRaf);
	mapFilterScrollSyncRaf = requestAnimationFrame(() => {
		mapFilterScrollSyncRaf = null;
		syncMapFilterScrollControls();
	});
}

function scheduleMapFilterScrollSyncBurst(options = {})
{
	scheduleMapFilterScrollSync(options);
	const sync = () => {
		if (typeof syncMapFilterScrollControls === "function") syncMapFilterScrollControls();
	};
	if (typeof requestAnimationFrame === "function") {
		requestAnimationFrame(() => {
			sync();
			requestAnimationFrame(sync);
		});
	}
	setTimeout(sync, 60);
	setTimeout(sync, 180);
}

function getMapFilterStepButtons(track)
{
	if (!track) return [];
	return Array.from(track.querySelectorAll(".extra-filter-dropdown, .sub-address-search"))
		.filter(isRenderableMapFilterElement)
		.sort((a, b) => a.offsetLeft - b.offsetLeft);
}

function getMapFilterVisibleLeftEdge(track)
{
	const trackRect = track ? track.getBoundingClientRect() : null;
	return trackRect && trackRect.width ? trackRect.left : 0;
}

function getMapFilterVisibleRightEdge(track)
{
	const trackRect = track ? track.getBoundingClientRect() : null;
	let rightEdge = trackRect && trackRect.width ? trackRect.right : window.innerWidth;
	const propertyButton = document.getElementById("mapPropertyToggleBtn");
	if (propertyButton && propertyButton instanceof HTMLElement) {
		const style = window.getComputedStyle(propertyButton);
		const rect = propertyButton.getBoundingClientRect();
		if (style.display !== "none" && style.visibility !== "hidden" && rect.width > 0 && rect.height > 0) {
			rightEdge = Math.min(rightEdge, rect.left - 18);
		}
	}
	return Math.max(trackRect ? trackRect.left : 0, rightEdge);
}

function getMapFilterScrollMetrics(track)
{
	const elements = getMapFilterStepButtons(track);
	const trackRect = track ? track.getBoundingClientRect() : null;
	const currentScrollLeft = Number(track && track.scrollLeft) || 0;
	const visibleLeft = getMapFilterVisibleLeftEdge(track);
	const visibleRight = getMapFilterVisibleRightEdge(track);
	let contentRight = 0;
	let visualOverflowRight = false;
	let visualOverflowLeft = false;
	let rightOverflowPx = 0;
	let leftOverflowPx = 0;
	elements.forEach((el) => {
		if (!isRenderableMapFilterElement(el)) return;
		const rect = el.getBoundingClientRect();
		contentRight = Math.max(
			contentRight,
			el.offsetLeft + el.offsetWidth,
			trackRect ? (rect.right - trackRect.left + currentScrollLeft) : 0
		);
		if (rect.right > visibleRight + 1) {
			visualOverflowRight = true;
			rightOverflowPx = Math.max(rightOverflowPx, rect.right - visibleRight);
		}
		if (rect.left < visibleLeft - 1) {
			visualOverflowLeft = true;
			leftOverflowPx = Math.max(leftOverflowPx, visibleLeft - rect.left);
		}
	});
	const fallbackWidth = track ? track.scrollWidth : 0;
	const scrollContentRight = contentRight || fallbackWidth;
	const visibleWidth = trackRect ? Math.max(0, visibleRight - trackRect.left) : 0;
	const clientWidth = Math.min(track ? track.clientWidth : 0, visibleWidth || (track ? track.clientWidth : 0));
	const elementMaxScrollLeft = Math.max(0, Math.ceil(scrollContentRight - clientWidth));
	const visualMaxScrollLeft = Math.max(
		elementMaxScrollLeft,
		Math.ceil(currentScrollLeft + rightOverflowPx)
	);
	return {
		contentRight: scrollContentRight,
		visibleLeft,
		visibleRight,
		visibleWidth: clientWidth,
		visualOverflowLeft,
		visualOverflowRight,
		rightOverflowPx,
		leftOverflowPx,
		maxScrollLeft: Math.max(0, visualMaxScrollLeft)
	};
}

function scrollMapFilterTrack(direction)
{
	const track = getMapFilterScrollTrack();
	if (!track) return;
	mapFilterManualScrollUntil = Date.now() + 900;
	mapFilterPreserveRightEdgeOnNextSync = false;
	mapFilterScrollState.wasAtRightEdge = false;
	const metrics = getMapFilterScrollMetrics(track);
	const maxScrollLeft = metrics.maxScrollLeft;
	if (maxScrollLeft <= 0) {
		track.scrollLeft = 0;
		scheduleMapFilterScrollSync();
		return;
	}
	const edgePadding = MAP_FILTER_SCROLL_EDGE_PADDING;
	const current = Math.max(0, Math.min(maxScrollLeft, Number(track.scrollLeft) || 0));
	track.scrollLeft = current;
	const stepElements = getMapFilterStepButtons(track);
	const visualSteps = stepElements
		.map((el) => {
			const rect = el.getBoundingClientRect();
			if (direction > 0 && rect.right > metrics.visibleRight + 1) {
				return current + (rect.right - metrics.visibleRight);
			}
			if (direction < 0 && rect.left < metrics.visibleLeft - 1) {
				return current - (metrics.visibleLeft - rect.left);
			}
			return null;
		})
		.filter((value) => Number.isFinite(value))
		.map((value) => Math.max(0, Math.min(maxScrollLeft, Math.ceil(value))));
	const offsetSteps = stepElements
		.map((el) => Math.max(0, Math.min(maxScrollLeft, direction > 0 ? (el.offsetLeft + el.offsetWidth - metrics.visibleWidth) : (el.offsetLeft - edgePadding))));
	const steps = visualSteps
		.concat(offsetSteps, [0, maxScrollLeft])
		.sort((a, b) => a - b)
		.filter((value, index, arr) => index === 0 || Math.abs(value - arr[index - 1]) > 2);
	const fallbackStep = Math.max(
		90,
		Math.min(
			220,
			stepElements.length ? Math.round(stepElements.reduce((sum, el) => sum + el.offsetWidth, 0) / stepElements.length) + 6 : 150
		)
	);
	let target = current;
	if (direction > 0) {
		target = steps.find((value) => value > current + 2);
		if (typeof target !== "number") target = Math.min(maxScrollLeft, current + fallbackStep);
	} else {
		for (let i = steps.length - 1; i >= 0; i -= 1) {
			if (steps[i] < current - 2) {
				target = steps[i];
				break;
			}
		}
		if (Math.abs(target - current) <= 1) target = Math.max(0, current - fallbackStep);
	}
	target = Math.max(0, Math.min(maxScrollLeft, target));
	if (Math.abs(target - current) <= 1) {
		scheduleMapFilterScrollSync();
		return;
	}
	track.scrollLeft = target;
	track.scrollTo({ left: target, behavior: "auto" });
	positionOpenMapFilterMenus();
	scheduleMapFilterScrollSync();
	setTimeout(scheduleMapFilterScrollSync, 80);
	setTimeout(positionOpenMapFilterMenus, 120);
}

function handleMapFilterScrollButtonEvent(event)
{
	const button = event && event.currentTarget;
	if (!button || !button.dataset || !button.dataset.mapFilterScroll) return;
	event.preventDefault();
	event.stopPropagation();
	if (event.type === "click") {
		const lastPointerScrollAt = Number(button.dataset.mapFilterPointerScrollAt || 0);
		if (lastPointerScrollAt && Date.now() - lastPointerScrollAt < 280) return;
	}
	if (event.type === "pointerdown") {
		button.dataset.mapFilterPointerScrollAt = String(Date.now());
	}
	scrollMapFilterTrack(button.dataset.mapFilterScroll === "left" ? -1 : 1);
}


function keepTopbarAddressSearchVisible()
{
	const topbarMenu = document.getElementById("topbarMenu");
	const addressSearch = document.getElementById("subAddressSearch");
	if (!topbarMenu || !addressSearch) return;
	const shell = topbarMenu.querySelector(".map-filter-scroll-shell");
	if (addressSearch.parentElement !== topbarMenu) {
		topbarMenu.insertBefore(addressSearch, shell || topbarMenu.firstChild);
	}
	addressSearch.setAttribute("data-topbar-address-search", "true");
	addressSearch.hidden = false;
	addressSearch.removeAttribute("aria-hidden");
	addressSearch.style.removeProperty("display");
	addressSearch.style.removeProperty("visibility");
	addressSearch.style.removeProperty("opacity");
	addressSearch.style.removeProperty("pointer-events");
}

function moveRealjejuHomeFiltersToTopbar()
{
	const topbarMenu = document.getElementById("topbarMenu");
	if (!topbarMenu) return;
	const filterBar = document.querySelector("#topbarMenu .map-filter-bar")
		|| document.querySelector(".sub-topbar-right .map-filter-bar");
	if (!filterBar) return;
	const addressSearch = document.getElementById("subAddressSearch");

	let shell = topbarMenu.querySelector(".map-filter-scroll-shell");
	if (!shell) {
		shell = document.createElement("div");
		shell.className = "map-filter-scroll-shell";
		shell.innerHTML = `<div class="map-filter-scroll-track"></div>`;
		topbarMenu.replaceChildren(shell);
	} else {
		shell.querySelectorAll(":scope > [data-map-filter-scroll]").forEach((button) => button.remove());
	}

	let controls = topbarMenu.querySelector(".map-filter-scroll-controls");
	if (!controls) {
		controls = document.createElement("div");
		controls.className = "map-filter-scroll-controls";
		controls.innerHTML = `
			<button type="button" class="map-filter-scroll-btn map-filter-scroll-btn-left" data-map-filter-scroll="left" aria-label="필터 왼쪽으로 이동" hidden>
				<i class="fa-solid fa-chevron-left" aria-hidden="true"></i>
			</button>
			<button type="button" class="map-filter-scroll-btn map-filter-scroll-btn-right" data-map-filter-scroll="right" aria-label="필터 오른쪽으로 이동" hidden>
				<i class="fa-solid fa-chevron-right" aria-hidden="true"></i>
			</button>
		`;
		topbarMenu.appendChild(controls);
	} else if (controls.parentElement !== topbarMenu) {
		topbarMenu.appendChild(controls);
	}

	const track = shell.querySelector(".map-filter-scroll-track");
	if (track && filterBar.parentElement !== track) {
		track.appendChild(filterBar);
	}
	if (addressSearch && addressSearch.parentElement !== topbarMenu) {
		topbarMenu.insertBefore(addressSearch, shell);
	}
	if (addressSearch) {
		addressSearch.setAttribute("data-topbar-address-search", "true");
	}
	keepTopbarAddressSearchVisible();

	if (track && track.dataset.mapFilterScrollBound !== "true") {
		track.dataset.mapFilterScrollBound = "true";
		track.addEventListener("scroll", scheduleMapFilterScrollSync, { passive: true });
	}

		topbarMenu.querySelectorAll("[data-map-filter-scroll]").forEach((button) => {
			if (button.dataset.mapFilterScrollBound === "true") return;
			button.dataset.mapFilterScrollBound = "true";
			button.addEventListener("pointerdown", handleMapFilterScrollButtonEvent);
			button.addEventListener("click", handleMapFilterScrollButtonEvent);
		});

	if (filterBar.dataset.mapFilterScrollObserverBound !== "true") {
		filterBar.dataset.mapFilterScrollObserverBound = "true";
		const observer = new MutationObserver(() => {
			scheduleMapFilterScrollSync({ preserveRightEdge: mapFilterScrollState.wasAtRightEdge });
		});
		observer.observe(filterBar, {
			childList: true,
			subtree: true,
			characterData: true,
			attributes: true,
			attributeFilter: ["class", "hidden", "aria-expanded"]
		});
		filterBar.__mapFilterScrollObserver = observer;
	}

	topbarMenu.classList.add("has-map-filters");
	document.body.classList.add("realjeju-filters-in-topbar");
	scheduleMapFilterScrollSync();
}

moveRealjejuHomeFiltersToTopbar();

window.addEventListener("resize", scheduleMapFilterScrollSync);
window.addEventListener("scroll", () => {
	positionOpenMapFilterMenus();
	positionMapFilterScrollArrows();
}, true);

