const UI_FONT_STACK = 'Pretendard, Inter, Noto Sans KR, -apple-system, BlinkMacSystemFont, Segoe UI, Roboto, Apple SD Gothic Neo, Malgun Gothic, sans-serif';
const BRAND_HEX = "#2563EB";
const BADGE_BASE_HEX = BRAND_HEX;
document.documentElement.style.setProperty("--brand", BRAND_HEX);
const BADGE_BASE_ALPHA = 0.80;
const BADGE_SELECTED_BG_ALPHA = 0.78;
const BADGE_TEXT_HEX = "#FFFFFF";
function hexToRgba(hex, alpha = 1)
{
	const value = String(hex || '').replace('#', '').trim();
	const normalized = value.length === 3 ? value.split('').map(ch => ch + ch).join('') : value;
	if (!/^[0-9a-fA-F]{6}$/.test(normalized)) return hex;
	const r = parseInt(normalized.slice(0, 2), 16);
	const g = parseInt(normalized.slice(2, 4), 16);
	const b = parseInt(normalized.slice(4, 6), 16);
	return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}
const APP_NAME = "REALJEJU.APP";
// [ARCHIVE] PATCH 3.918: 상단 및 하단 배포 버전 표기를 현재 버전으로 맞춥니다.
const APP_VERSION = "3.927";
let realjejuTopbarVersionStatsText = "";
let realjejuSiteVisitStatsRequested = false;

function shouldShowRealjejuTopbarVersionStats()
{
	return typeof window !== "undefined" && window.realjejuCurrentIsAdmin === true;
}

function getRealjejuTopbarVersionText()
{
	return shouldShowRealjejuTopbarVersionStats() && realjejuTopbarVersionStatsText
		? realjejuTopbarVersionStatsText
		: APP_VERSION;
}

function updateRealjejuTopbarVersionText()
{
	const text = "Ver " + getRealjejuTopbarVersionText();
	document.querySelectorAll(".topbar-version-text").forEach((el) => {
		el.textContent = text;
	});
}

function applyRealjejuVisitStats(row)
{
	const uniqueIpCount = Number(row && row.unique_ip_count);
	const totalVisitCount = Number(row && row.total_visit_count);
	if (!Number.isFinite(uniqueIpCount) || !Number.isFinite(totalVisitCount)) return;
	realjejuTopbarVersionStatsText = APP_VERSION + "(" + Math.max(0, Math.trunc(uniqueIpCount)).toLocaleString("ko-KR") + ", " + Math.max(0, Math.trunc(totalVisitCount)).toLocaleString("ko-KR") + ")";
	updateRealjejuTopbarVersionText();
}

async function syncRealjejuSiteVisitStats()
{
	if (realjejuSiteVisitStatsRequested) return;
	realjejuSiteVisitStatsRequested = true;
	updateRealjejuTopbarVersionText();
	try {
		if (typeof loadSupabaseScript === "function") await loadSupabaseScript();
		const client = typeof window.getRealjejuSupabaseClient === "function" ? window.getRealjejuSupabaseClient() : null;
		if (!client || typeof client.rpc !== "function") return;
		const { data, error } = await client.rpc("record_site_visit");
		if (error) throw error;
		const row = Array.isArray(data) ? data[0] : data;
		applyRealjejuVisitStats(row);
	} catch (error) {
		console.warn("방문 통계 표시 실패:", error);
	}
}

window.realjejuGetTopbarVersionText = getRealjejuTopbarVersionText;
window.realjejuUpdateTopbarVersionText = updateRealjejuTopbarVersionText;

if (document.readyState === "loading") {
	document.addEventListener("DOMContentLoaded", syncRealjejuSiteVisitStats, { once: true });
} else {
	setTimeout(syncRealjejuSiteVisitStats, 0);
}

function normalizeVersionDownloadLinkForLocalFile()
{
	const link = document.querySelector(".sub-version-fixed[data-version-download]");
	if (!link) return;
	const fileName = link.getAttribute("data-version-download") || "";
	if (!fileName) return;
	if (window.location && window.location.protocol === "file:") {
		link.removeAttribute("download");
		link.setAttribute("href", "#");
		link.addEventListener("click", (event) => {
			event.preventDefault();
			event.stopPropagation();
		}, true);
		return;
	}
	link.setAttribute("href", fileName);
	link.setAttribute("download", fileName);
}

normalizeVersionDownloadLinkForLocalFile();

