// normalizeRecentValueText: 해당 기능을 수행한다.
function normalizeRecentValueText(value)
{
	if (value === null || value === undefined) return "";
	const text = String(value).trim();
	if (!text) return "";
	const compact = text
		.replace(/[·|]/g, " ")
		.replace(/[\u00b7\-\s]+/g, " ")
		.trim()
		.toLowerCase();
	if (!compact) return "";
	if (!/[\uac00-\ud7a3a-z0-9]/i.test(compact)) {
		if (/^(null|undefined|nan|none|없음|정보없음|미제공|미입력|-+)$/i.test(compact)) return "";
		return "";
	}
	const tokens = compact.split(/\s+/)
		.map(token => token.replace(/[()·|,]/g, "").trim())
		.filter(Boolean);
	if (!tokens.length) return "";
	const invalidToken = /^(null|undefined|nan|none|없음|정보없음|미제공|미입력|-+)$/i;
	const filtered = tokens.filter((token) => !invalidToken.test(token));
	if (!filtered.length) return "";
	if (filtered.length === tokens.length) return text;
	return filtered.join(" ");
}


function trimRecentListEllipsisText(value)
{
	const text = normalizeRecentValueText(value);
	if (!text) return "";
	return text.replace(/(?:\.{3,}|…).*$/g, "").trim();
}

const REALJEJU_RECENT_TEXT_FIT_SELECTOR = ".realjeju-side-recent-item-title, .realjeju-side-recent-item-sub";

function getRecentTextFitCanvasContext()
{
	if (!getRecentTextFitCanvasContext.canvas) {
		getRecentTextFitCanvasContext.canvas = document.createElement("canvas");
	}
	return getRecentTextFitCanvasContext.canvas.getContext("2d");
}

function getRecentTextFitFont(element)
{
	const style = window.getComputedStyle(element);
	return `${style.fontStyle || "normal"} ${style.fontVariant || "normal"} ${style.fontWeight || "400"} ${style.fontSize || "12px"} ${style.fontFamily || "sans-serif"}`;
}

function fitRecentListTextToElement(text, element)
{
	const source = String(text || "").replace(/\s+/g, " ").trim();
	const maxWidth = Math.floor(element.clientWidth || element.getBoundingClientRect().width || 0);
	if (!source || maxWidth <= 0) return source;
	const context = getRecentTextFitCanvasContext();
	if (!context) return source;
	context.font = getRecentTextFitFont(element);
	if (context.measureText(source).width <= maxWidth) return source;

	let current = "";
	let best = "";
	for (const chunk of source.split(/(\s+)/).filter(Boolean)) {
		const next = `${current}${chunk}`;
		const candidate = next.trimEnd();
		if (context.measureText(candidate).width > maxWidth) break;
		current = next;
		best = candidate;
	}
	if (best) return best.trim();

	let fitted = "";
	for (const character of Array.from(source)) {
		const next = `${fitted}${character}`;
		if (context.measureText(next).width > maxWidth) break;
		fitted = next;
	}
	return fitted.trim();
}

function fitSideRecentListText()
{
	const listEl = getSideRecentListElement();
	if (!listEl) return;
	listEl.querySelectorAll(REALJEJU_RECENT_TEXT_FIT_SELECTOR).forEach((element) => {
		const fullText = element.dataset.recentFullText || element.textContent || "";
		element.textContent = fitRecentListTextToElement(fullText, element);
	});
}

function scheduleSideRecentListTextFit()
{
	if (typeof requestAnimationFrame === "function") {
		requestAnimationFrame(fitSideRecentListText);
		return;
	}
	setTimeout(fitSideRecentListText, 0);
}

// normalizeRecentViewedListing: 해당 기능을 수행한다.
function normalizeRecentViewedListing(item)
{
	const id = normalizeItemId(item && item.id);
	if (!id) return null;
	const address = normalizeRecentValueText(getPublicListingDisplayAddress(item || {}));
	const type = normalizeRecentValueText(item && (item.type || item.property_type || item.property_type_label || item.propertyType || item.propertyTypeLabel || ""));
	const dealType = normalizeRecentValueText(item && item.dealType);
	const price = normalizeRecentValueText(item && item.price);
	const titleCandidate = normalizeRecentValueText(sanitizePublicListingText(item && item.title, item || {}));
	const displayName = titleCandidate || address || type || "매물";
	const summary = [
		type,
		dealType && price ? `${dealType} ${price}` : (dealType || price)
	].filter(Boolean).join(" · ");
	const listingNo = normalizePropertyListingNoCandidate(String(item && (item.listingNo || item.listing_no || "")).trim());
	const fallbackTitle = listingNo ? `매물 ${listingNo}` : "매물 조회";
	return {
		id,
		listingNo,
		dealType,
		propertyType: type,
		title: displayName || fallbackTitle,
		price,
		summary,
		address: address || "",
		updatedAt: Date.now()
	};
}

// parseRecentViewedListings: 해당 기능을 수행한다.
function parseRecentViewedListings(raw)
{
	try {
		const parsed = JSON.parse(String(raw || ""));
		if (!Array.isArray(parsed)) return [];
		return parsed.map(normalizeRecentViewedListing).filter(Boolean);
	} catch (error) {
		return [];
	}
}

// loadRecentViewedListings: 해당 기능을 수행한다.
function loadRecentViewedListings()
{
	if (!window.localStorage) return [];
	const saved = window.localStorage.getItem(REALJEJU_RECENT_LISTINGS_KEY);
	if (!saved) return [];
	const parsed = parseRecentViewedListings(saved);
	return parsed
		.sort((a, b) => Number(b.updatedAt || 0) - Number(a.updatedAt || 0))
		.slice(0, REALJEJU_RECENT_LISTINGS_LIMIT);
}

// getCurrentMainActionForRecentViewed: 최근 조회 이동 전 현재 메뉴 상태를 판별한다.
function getCurrentMainActionForRecentViewed()
{
	// 최근 조회에서 상세를 열기 전에, 현재 어떤 상단 뷰에 머물러 있는지 확인해
	// home이 아닌 화면에서는 홈으로 복귀 후 목록/상세 오픈 동작을 맞춘다.
	if (document.body.classList.contains("admin-page-open")) return "admin";
	if (document.body.classList.contains("broker-home-page-open")) return "broker-home";
	if (document.body.classList.contains("property-register-page-open")) return "register";
	if (document.body.classList.contains("notice-page-open")) return "notice";
	if (document.body.classList.contains("my-suite-page-open")) {
		const activeMySuiteTab = document.querySelector(".my-suite-tab.active");
		return activeMySuiteTab && activeMySuiteTab.dataset.mySuiteTab === "favorites" ? "favorites" : "";
	}
	if (document.body.classList.contains("presale-page-open")) return "presale";
	return "home";
}

