// saveRecentViewedListings: 해당 기능을 수행한다.
function saveRecentViewedListings(listings)
{
	if (!window.localStorage) return;
	try {
		window.localStorage.setItem(REALJEJU_RECENT_LISTINGS_KEY, JSON.stringify(listings));
	} catch (error) {}
}

// renderSideRecentViewedList: 해당 기능을 수행한다.
function renderSideRecentViewedList()
{
	const listEl = getSideRecentListElement();
	const emptyEl = getSideRecentEmptyElement();
	if (!listEl || !emptyEl) return;
	if (!realjejuRecentViewedListings.length) {
		emptyEl.hidden = false;
		listEl.innerHTML = "";
		return;
	}

	emptyEl.hidden = true;
	listEl.innerHTML = realjejuRecentViewedListings.map((entry) => {
		const id = escapeHtml(entry.id);
		const rawTitleText = trimRecentListEllipsisText(entry.title);
		const titleText = escapeHtml(rawTitleText || "매물 조회");
		const propertyTypeText = trimRecentListEllipsisText(entry.propertyType || entry.type || entry.property_type || entry.property_type_label || entry.propertyTypeLabel || entry.summaryType || "");
		const priceText = trimRecentListEllipsisText(entry.price);
		const normalizedSummary = trimRecentListEllipsisText(entry.summary);
		// 최근 조회 2번째 줄은 "매물유형 + 가격" 우선순위로 노출한다.
		const summaryLine = [
			propertyTypeText && priceText ? `${propertyTypeText} ${priceText}` : "",
			priceText && !propertyTypeText ? priceText : "",
			normalizedSummary
		]
			.map((value) => String(value || "").trim())
			.filter(Boolean)[0] || "";
		const summaryFullText = escapeHtml(summaryLine);
		const summaryText = summaryLine ? `<div class="realjeju-side-recent-item-sub" data-recent-full-text="${summaryFullText}">${summaryFullText}</div>` : "";
		return `
			<button type="button" class="realjeju-side-recent-item" data-recent-listing-id="${id}" title="${titleText}">
				<div class="realjeju-side-recent-item-title" data-recent-full-text="${titleText}">${titleText}</div>
				${summaryText}
			</button>
		`;
	}).join("");
	scheduleSideRecentListTextFit();
}

// upsertRecentViewedListing: 해당 기능을 수행한다.
function upsertRecentViewedListing(item)
{
	const next = normalizeRecentViewedListing(item);
	if (!next) return;
	const byId = normalizeItemId(next.id);
	realjejuRecentViewedListings = [next, ...realjejuRecentViewedListings.filter((row) => normalizeItemId(row && row.id) !== byId)]
		.slice(0, REALJEJU_RECENT_LISTINGS_LIMIT);
	saveRecentViewedListings(realjejuRecentViewedListings);
	renderSideRecentViewedList();
}

// findRealJejuListingById: 해당 기능을 수행한다.
function findRealJejuListingById(id)
{
	const normalizedId = normalizeItemId(id);
	if (!normalizedId) return null;
	if (!state || !state.all) return null;
	const pools = [state.leftListItems, state.filtered, state.all].filter(Array.isArray);
	for (const pool of pools) {
		const found = pool.find((item) => normalizeItemId(item && item.id) === normalizedId);
		if (found) return found;
	}
	return null;
}

// openRecentViewedListingById: 해당 기능을 수행한다.
async function openRecentViewedListingById(listingId)
{
	// 최근 조회 카드에서 받은 id를 화면 처리에 쓰기 전에 항상 정규화한다.
	const normalizedId = normalizeItemId(listingId);
	if (!normalizedId) return;
	let listing = findRealJejuListingById(normalizedId);
	const cachedRecent = realjejuRecentViewedListings.find((row) => normalizeItemId(row && row.id) === normalizedId) || null;
	// 목록에서 id를 찾지 못한 경우 서버/캐시된 최근조회 데이터로 최소 표시 정보를 구성해
	// 뒤늦은 상세 데이터 로딩 실패 시에도 상세 영역을 비정상 종료시키지 않는다.
	if (!listing) {
		const dbItem = await resolveDetailDataFromDatabase({ id: normalizedId });
		if (dbItem && normalizeItemId(dbItem.id) === normalizedId) {
			listing = dbItem;
		}
	}
	if (!listing) {
		listing = {
			id: normalizedId,
			title: cachedRecent && (cachedRecent.title || cachedRecent.address || cachedRecent.summary) ? normalizeRecentValueText(cachedRecent.title || cachedRecent.address || cachedRecent.summary) : "매물 조회",
			listingNo: cachedRecent ? normalizePropertyListingNoCandidate(String(cachedRecent.listingNo || "").trim()) : "",
			type: cachedRecent ? normalizeRecentValueText(cachedRecent.propertyType || cachedRecent.type || cachedRecent.property_type || cachedRecent.property_type_label || cachedRecent.propertyTypeLabel || "") : "",
			dealType: cachedRecent ? cachedRecent.dealType : "",
			price: cachedRecent ? cachedRecent.price : "",
			address: cachedRecent ? cachedRecent.address : "",
			summary: cachedRecent ? cachedRecent.summary : ""
		};
	}
	if (!listing) return;

	const normalizedTargetId = normalizeItemId(listing && listing.id);
	if (normalizedTargetId) {
		const patchListingInPlace = (list) => {
			// 최근 조회로 연 경우에도 좌측 목록/필터 정렬을 건드리지 않도록
			// 기존 순서는 유지하고 항목 데이터만 최신값으로 갱신한다.
			const source = Array.isArray(list) ? [...list] : [];
			const index = source.findIndex(candidate => normalizeItemId(candidate && candidate.id) === normalizedTargetId);
			if (index >= 0) {
				source[index] = { ...source[index], ...listing };
			}
			return source;
		};
		state.all = patchListingInPlace(state.all);
		state.filtered = patchListingInPlace(state.filtered);
	}

	// 홈이 아니면 먼저 홈 이동 후 최근조회 상세 모드로 진입해
	// 사이드 바/필터 상태가 다른 화면 규칙에 의해 꼬이지 않도록 처리한다.
	const sideNavAction = getCurrentMainActionForRecentViewed();
	if (sideNavAction !== "home") {
		if (typeof window.realjejuGoHome === "function") {
			const homeResult = window.realjejuGoHome({ resetDetail: true });
			if (homeResult && typeof homeResult.then === "function") {
				await homeResult.catch(() => {});
			}
		}
		await new Promise((resolve) => setTimeout(resolve, 0));
	}

	// 공유형 최근조회 상세 모드 클래스는 목록-필터바 폭 조정 및 오른쪽 상세 패널 표시 계산의 기준점이다.
		const detailPanel = document.getElementById("sidebarDetailPanel");
		closeEducationFacilityDetailForPropertyInteraction();
		if (typeof closeRoadviewPanelForPropertyInteraction === "function") {
			await closeRoadviewPanelForPropertyInteraction();
		} else if (typeof hideRoadview === "function") {
			await hideRoadview();
		}
	document.body.classList.remove("detail-page-panel-open", "direct-detail-list-mode", "list-shared-detail-mode", "map-panels-collapsed", "map-detail-panel-active");
	document.body.classList.add("shared-detail-mode");
	document.body.classList.add("recent-shared-detail-mode");
	document.body.classList.remove("sidebar-list-collapsed");
	state.isListOpen = true;
	state.selectionMode = "single";
	state.selectedClusterKey = null;
	state.selectedMarkerId = normalizedTargetId;
	state.selectedMarkerIds = new Set([normalizedTargetId]);
	lockListToItems([listing]);
	updateMarkerSelection(normalizedTargetId, [normalizedTargetId]);
	if (detailPanel) {
		detailPanel.style.display = "block";
		detailPanel.style.opacity = "";
		detailPanel.style.visibility = "";
		detailPanel.style.pointerEvents = "";
	}
	// 최근 조회 상세 오픈 직후에도 필터바를 좌측 오프셋 계산 대상으로 잡도록
	// 렌더 타이밍마다 정렬 보정을 강제 호출한다.
	setSharedDetailMode(true);
	if (typeof window.realjejuSyncTopbarFilterSafeLeft === "function") {
		window.realjejuSyncTopbarFilterSafeLeft();
	}

	allowDetailOpenFromListClick = true;
	let detailOpenError;
	try {
		// 최근 조회 메뉴 클릭은 최근조회 패널 정렬에만 영향을 주지 않도록, 조회 이력 업서트는 건너뛴다.
		await openDetailPanel(listing, {
			syncUrl: false,
			forceOpen: true,
			overlayPage: false,
			sharedMode: true,
			skipRecentViewTracking: true
		});
		if (sidebar) sidebar.classList.add("expanded");
		state.isListOpen = true;
		updateSidebarWidth();
		if (typeof syncMapFilterbarDetailHidden === "function") syncMapFilterbarDetailHidden();
		if (typeof scheduleMapFilterScrollSync === "function") scheduleMapFilterScrollSync();
		if (typeof window.realjejuSyncTopbarFilterSafeLeft === "function") {
			window.realjejuSyncTopbarFilterSafeLeft();
		}
		if (typeof refreshMapLayout === "function") {
			refreshMapLayout();
			setTimeout(refreshMapLayout, 120);
		}
	} catch (error) {
		detailOpenError = error;
		console.error("최근 조회 상세 패널 열기 실패:", error);
	} finally {
		allowDetailOpenFromListClick = false;
	}
	if (detailOpenError) {
		throw detailOpenError;
	}
	syncDetailUrl(listing.id);
	await focusProperty(normalizedTargetId || listing.id);
	await focusRecentViewedListingOnMap(currentDetailItem || listing, normalizedTargetId || listing.id);

	setTimeout(() => {
		state.isListOpen = true;
		updateSidebarWidth();
		if (typeof syncMapFilterbarDetailHidden === "function") syncMapFilterbarDetailHidden();
		if (typeof scheduleMapFilterScrollSync === "function") scheduleMapFilterScrollSync();
		if (typeof window.realjejuSyncTopbarFilterSafeLeft === "function") {
			window.realjejuSyncTopbarFilterSafeLeft();
		}
		refreshClusterBadges();
	}, 0);
}

async function focusRecentViewedListingOnMap(listing, listingId)
{
	if (!state.map || !window.kakao || !kakao.maps) return false;
	const normalizedId = normalizeItemId(listingId || (listing && listing.id));
	const candidates = [
		listing,
		currentDetailItem,
		findRealJejuListingById(normalizedId)
	];
	[state.filtered, state.all, state.leftListItems].forEach((list) => {
		if (!Array.isArray(list)) return;
		const found = list.find((item) => normalizeItemId(item && item.id) === normalizedId);
		if (found) candidates.push(found);
	});
	let position = null;
	for (const candidate of candidates) {
		if (!candidate) continue;
		const payload = candidate.payload && typeof candidate.payload === "object" ? candidate.payload : {};
		position = normalizeJejuLatLngPair(
			candidate.lat ?? candidate.latitude ?? payload.lat ?? payload.latitude,
			candidate.lng ?? candidate.longitude ?? payload.lng ?? payload.longitude
		);
		if (position) break;
	}
	if (!position) return false;

	closeEducationFacilityDetailForPropertyInteraction();
	if (typeof closeRoadviewPanelForPropertyInteraction === "function") {
		await closeRoadviewPanelForPropertyInteraction();
	} else if (typeof hideRoadview === "function") {
		await hideRoadview();
	}
	const latLng = new kakao.maps.LatLng(position.lat, position.lng);
	const move = () => {
		if (!state.map) return;
		if (typeof state.map.relayout === "function") state.map.relayout();
		if (typeof state.map.setCenter === "function") {
			state.map.setCenter(latLng, { __allowClusterRestore: true });
		} else if (typeof state.map.panTo === "function") {
			state.map.panTo(latLng);
		}
	};
	move();
	if (typeof requestAnimationFrame === "function") requestAnimationFrame(move);
	setTimeout(move, 80);
	setTimeout(move, 240);
	return true;
}

async function openListSharedDetailFromItem(item)
{
	if (!item) return;
	const normalizedId = normalizeItemId(item.id);
	if (!normalizedId) return;

	closeEducationFacilityDetailForPropertyInteraction();
	if (typeof closeRoadviewPanelForPropertyInteraction === "function") {
		await closeRoadviewPanelForPropertyInteraction();
	} else if (typeof hideRoadview === "function") {
		await hideRoadview();
	}
	document.body.classList.remove(
		"detail-page-panel-open",
		"direct-detail-list-mode",
		"recent-shared-detail-mode",
		"map-panels-collapsed",
		"map-detail-panel-active"
	);
	document.body.classList.add("shared-detail-mode", "list-shared-detail-mode");
	document.body.classList.remove("sidebar-list-collapsed");
	state.isListOpen = true;
	state.selectionMode = "single";
	state.selectedClusterKey = null;
	state.selectedMarkerId = normalizedId;
	state.selectedMarkerIds = new Set([normalizedId]);
	clearListLock();
	highlightCard(normalizedId);
	updateMarkerSelection(normalizedId, [normalizedId]);

	if (detailScroll) detailScroll.scrollTop = 0;
	allowDetailOpenFromListClick = true;
	let detailOpenError;
	try {
		await openDetailPanel(item, {
			syncUrl: false,
			forceOpen: true,
			overlayPage: false,
			sharedMode: true
		});
		document.body.classList.add("list-shared-detail-mode");
		document.body.classList.remove("sidebar-list-collapsed");
		if (sidebar) sidebar.classList.add("expanded");
		state.isListOpen = true;
		updateSidebarWidth();
		if (typeof syncMapFilterbarDetailHidden === "function") syncMapFilterbarDetailHidden();
		if (typeof scheduleMapFilterScrollSync === "function") scheduleMapFilterScrollSync();
		if (typeof window.realjejuSyncTopbarFilterSafeLeft === "function") {
			window.realjejuSyncTopbarFilterSafeLeft();
		}
		if (typeof refreshMapLayout === "function") {
			refreshMapLayout();
			setTimeout(refreshMapLayout, 120);
		}
	} catch (error) {
		detailOpenError = error;
		console.error("목록 상세 패널 열기 실패:", error);
	} finally {
		allowDetailOpenFromListClick = false;
	}

	syncDetailUrl(item.id);
	if (detailScroll) detailScroll.scrollTop = 0;
	await focusProperty(item.id);
	await focusRecentViewedListingOnMap(currentDetailItem || item, item.id);
	setTimeout(() => {
		document.body.classList.add("list-shared-detail-mode");
		document.body.classList.remove("sidebar-list-collapsed");
		highlightCard(normalizedId);
		refreshClusterBadges();
		if (typeof window.realjejuSyncTopbarFilterSafeLeft === "function") {
			window.realjejuSyncTopbarFilterSafeLeft();
		}
	}, 0);

	if (detailOpenError) throw detailOpenError;
}

function getDetailUrlById(id)
{
	const normalizedId = normalizeItemId(id);
	const url = new URL(window.location.href);
	if (normalizedId) {
		url.searchParams.set(DETAIL_QUERY_KEY, normalizedId);
	} else {
		url.searchParams.delete(DETAIL_QUERY_KEY);
	}
	return url;
}

function syncDetailUrl(id, { replace = false } = {})
{
	const url = getDetailUrlById(id);
	const nextUrl = `${url.pathname}${url.search}${url.hash}`;
	const currentUrl = `${window.location.pathname}${window.location.search}${window.location.hash}`;
	if (nextUrl === currentUrl) return;
	const method = replace ? "replaceState" : "pushState";
	window.history[method]({}, "", nextUrl);
}

function clearDetailUrl(options = {})
{
	syncDetailUrl("", options);
}

function setSharedDetailMode(enabled)
{
	document.body.classList.toggle("shared-detail-mode", !!enabled);
	if (!enabled) {
		document.body.classList.remove("list-shared-detail-mode", "recent-shared-detail-mode");
	}
	if (enabled) {
		sidebar.classList.add("expanded");
		const panel = document.getElementById('sidebarDetailPanel');
		if (panel) {
			panel.style.display = 'block';
			panel.style.opacity = '';
			panel.style.pointerEvents = '';
			panel.style.visibility = '';
		}
	}
	updateSidebarWidth();
	refreshMapLayout();
}

function shouldUseSharedDetailMode()
{
	return false;
}

function normalizeItemId(value)
{
	if (value == null) return "";
	return String(value).trim();
}

let viewMap = {};
let favoriteCountMap = {};
let inquiryCountMap = {};
let sidebarAgentEngagementSeq = 0;
let detailEngagementCountSeq = 0;
let engagementCountRpcDisabled = true;
const mapListingOwnerCache = {
	profilesByUserId: new Map(),
	agenciesById: new Map(),
	agenciesByUserId: new Map(),
	agenciesByOfficeName: new Map()
};
const mapListingOwnerDataInflight = new Map();

function clearRealjejuSessionCaches()
{
	try {
		brokerOfficeRowsCache.clear();
		brokerOfficeRowsInflight.clear();
		mapListingOwnerCache.profilesByUserId.clear();
		mapListingOwnerCache.agenciesById.clear();
		mapListingOwnerCache.agenciesByUserId.clear();
		mapListingOwnerCache.agenciesByOfficeName.clear();
		mapListingOwnerDataInflight.clear();
	} catch (err) {}
}

const recentViewIncrementMap = new Map();
const detailEngagementFetchedAtMap = new Map();
const VIEW_INCREMENT_DEDUPE_MS = 2000;
const DETAIL_ENGAGEMENT_CACHE_MS = 30000;
const DETAIL_INQUIRY_COUNT_ENABLED = false;
const VIEW_COUNT_RPC_ENABLED = true;
let viewCountRpcDisabled = !VIEW_COUNT_RPC_ENABLED;
let mapListingsLoadPromise = null;
let mapListingsLastLoadedAt = 0;
const MAP_LISTINGS_BOOTSTRAP_CACHE_MS = 2500;
const MAP_LISTING_SUMMARY_SELECT = [
	"id",
	"user_id",
	"agency_id",
	"listing_no",
	"status",
	"property_type",
	"property_type_label",
	"deal_types",
	"title",
	"public_address",
	"address1",
	"hide_detail_jibun",
	"lat",
	"lng",
	"updated_at",
	"created_at",
	"photos",
	"payload"
].join(",");
const MAP_LISTING_MARKER_FALLBACK_SELECT = [
	"id",
	"user_id",
	"agency_id",
	"listing_no",
	"status",
	"property_type",
	"property_type_label",
	"deal_types",
	"title",
	"public_address",
	"address1",
	"hide_detail_jibun",
	"lat",
	"lng",
	"updated_at",
	"created_at",
	"payload"
].join(",");
const LEFT_LIST_PAGE_SIZE = 30;

function preferCachedAgency(current, next)
{
	if (!current) return next;
	if (!next) return current;
	if (current.status !== "active" && next.status === "active") return next;
	if (current.status === "active" && next.status !== "active") return current;
	const currentTime = Date.parse(current.updated_at || current.created_at || "") || 0;
	const nextTime = Date.parse(next.updated_at || next.created_at || "") || 0;
	return nextTime >= currentTime ? next : current;
}

function cacheMapListingProfile(profile)
{
	if (!profile || typeof profile !== "object") return null;
	const key = getViewCountKey(profile.id);
	if (!key) return null;
	mapListingOwnerCache.profilesByUserId.set(key, profile);
	return profile;
}

function cacheMapListingAgency(agency)
{
	if (!agency || typeof agency !== "object") return null;
	const idKey = getViewCountKey(agency.id);
	const userKey = getViewCountKey(agency.user_id);
	const officeKey = String(agency.office_name || "").trim();
	if (idKey) {
		const next = preferCachedAgency(mapListingOwnerCache.agenciesById.get(idKey), agency);
		mapListingOwnerCache.agenciesById.set(idKey, next);
	}
	if (userKey) {
		const next = preferCachedAgency(mapListingOwnerCache.agenciesByUserId.get(userKey), agency);
		mapListingOwnerCache.agenciesByUserId.set(userKey, next);
	}
	if (officeKey) {
		const next = preferCachedAgency(mapListingOwnerCache.agenciesByOfficeName.get(officeKey), agency);
		mapListingOwnerCache.agenciesByOfficeName.set(officeKey, next);
	}
	return agency;
}

function getViewCountKey(value)
{
	return String(value || "").trim();
}

function getItemViewKey(item)
{
	if (!item || typeof item !== "object") return "";
	return getViewCountKey(item.id || item.listingNo || "");
}

function getListingViewKey(item)
{
	if (!item || typeof item !== "object") return "";
	const payload = item.payload && typeof item.payload === "object" ? item.payload : {};
	return getViewCountKey(item.listingNo || item.listing_no || payload.listing_no || payload.listingNo || item.id || "");
}

function getViewCountText(viewKey)
{
	const count = Number(viewMap[getViewCountKey(viewKey)] || 0);
	return `조회 ${Number.isFinite(count) ? count : 0}`;
}

function formatDetailSummaryDate(value)
{
	const raw = String(value || "").trim();
	if (!raw) return "-";
	const dateOnlyMatch = raw.match(/^(\d{4})-(\d{2})-(\d{2})$/);
	if (dateOnlyMatch) return `${dateOnlyMatch[1]}-${dateOnlyMatch[2]}-${dateOnlyMatch[3]}`;
	const date = new Date(raw);
	if (Number.isNaN(date.getTime())) return "-";
	try {
		const parts = new Intl.DateTimeFormat("en-US", {
			timeZone: "Asia/Seoul",
			year: "numeric",
			month: "2-digit",
			day: "2-digit"
		}).formatToParts(date).reduce((acc, part) => {
			acc[part.type] = part.value;
			return acc;
		}, {});
		if (parts.year && parts.month && parts.day) return `${parts.year}-${parts.month}-${parts.day}`;
	} catch (_) {}
	const yyyy = date.getFullYear();
	const mm = String(date.getMonth() + 1).padStart(2, "0");
	const dd = String(date.getDate()).padStart(2, "0");
	return `${yyyy}-${mm}-${dd}`;
}

function getDetailCountValue(item, keys)
{
	for (const key of keys) {
		const value = item && item[key];
		const numberValue = Number(value);
		if (Number.isFinite(numberValue)) return numberValue;
	}
	return 0;
}

function getDetailViewCount(item)
{
	const key = getListingViewKey(item);
	const mappedCount = Number(viewMap[getViewCountKey(key)]);
	if (Number.isFinite(mappedCount)) return mappedCount;
	return getDetailCountValue(item, ["viewCount", "view_count", "views", "readCount", "read_count"]);
}

function getDetailFavoriteCount(item)
{
	const key = getItemViewKey(item);
	const mappedCount = Number(favoriteCountMap[getViewCountKey(key)]);
	if (Number.isFinite(mappedCount)) return mappedCount;
	return getDetailCountValue(item, ["favoriteCount", "favorite_count", "wishCount", "wish_count"]);
}

function getDetailInquiryCount(item)
{
	const key = getItemViewKey(item);
	const mappedCount = Number(inquiryCountMap[getViewCountKey(key)]);
	if (Number.isFinite(mappedCount)) return mappedCount;
	return getDetailCountValue(item, ["inquiryCount", "inquiry_count", "contactCount", "contact_count"]);
}

function getDetailSummaryMetaText(item)
{
	const dateText = formatDetailSummaryDate(item?.dateLabel || item?.date || item?.updated_at || item?.created_at);
	const inquiryCount = getDetailInquiryCount(item);
	const favoriteCount = getDetailFavoriteCount(item);
	const viewCount = getDetailViewCount(item);
	return `등록일 ${dateText} · 문의 ${inquiryCount} · 관심 ${favoriteCount} · 조회 ${viewCount}`;
}

function renderDetailSummaryMeta(item)
{
	const detailSummaryAddress = document.getElementById("detailSummaryAddress");
	if (!detailSummaryAddress) return;
	detailSummaryAddress.textContent = getDetailSummaryMetaText(item);
}

function updateViewCountElements(viewKey, count)
{
	const key = getViewCountKey(viewKey);
	if (!key) return;
	document.querySelectorAll(`.card-date[data-view-key="${key}"]`).forEach(el => {
		el.textContent = `조회 ${Number.isFinite(Number(count)) ? Number(count) : 0}`;
	});
	if (currentDetailItem && getListingViewKey(currentDetailItem) === key) {
		renderDetailSummaryMeta(currentDetailItem);
	}
}

function shouldUseListViewCounts()
{
	return !viewCountRpcDisabled && !!(state && state.isListOpen && !document.body.classList.contains("sidebar-list-collapsed"));
}

function isMissingRpcError(error)
{
	const message = String(error && (error.message || error.details || "") || "");
	return error && (error.code === "PGRST202" || message.includes("Could not find the function"));
}

function disableViewCountRpc(error)
{
	if (!isMissingRpcError(error)) return false;
	viewCountRpcDisabled = true;
	return true;
}

async function fetchViewCounts(items)
{
	if (!shouldUseListViewCounts()) return {};
	const ids = [...new Set((items || []).map(item => getListingViewKey(item)).filter(Boolean))];
	if (!ids.length) return {};
	try {
		await loadSupabaseScript();
		const client = getMapListingsSupabaseClient();
		if (!client) return {};
		const { data, error } = await client
			.from("listing_views")
			.select("listing_no, views")
			.in("listing_no", ids);
		if (error) throw error;
		const next = {};
		(Array.isArray(data) ? data : []).forEach(row => {
			const key = getViewCountKey(row && row.listing_no);
			const views = Number(row && row.views);
			if (key && Number.isFinite(views)) next[key] = views;
		});
		return next;
	} catch (err) {
		if (disableViewCountRpc(err)) return {};
		console.warn("조회수 불러오기 실패:", err);
		return {};
	}
}

async function refreshCardViewCounts(items)
{
	if (!shouldUseListViewCounts()) return;
	const renderSeq = ++state.viewRenderSeq;
	const fetched = await fetchViewCounts(items);
	if (renderSeq !== state.viewRenderSeq) return;
	viewMap = { ...viewMap, ...fetched };
	Object.entries(fetched).forEach(([viewKey, count]) => {
		updateViewCountElements(viewKey, count);
	});
}

async function incrementViewCount(viewKey)
{
	if (viewCountRpcDisabled) return null;
	const key = getViewCountKey(viewKey);
	if (!key) return null;
	const now = Date.now();
	const lastIncrementedAt = Number(recentViewIncrementMap.get(key) || 0);
	if (now - lastIncrementedAt < VIEW_INCREMENT_DEDUPE_MS) {
		const cachedCount = Number(viewMap[key]);
		return Number.isFinite(cachedCount) ? cachedCount : null;
	}
	recentViewIncrementMap.set(key, now);
	try {
		await loadSupabaseScript();
		const client = getMapListingsSupabaseClient();
		if (!client || typeof client.rpc !== "function") return null;
		const { data, error } = await client.rpc("increment_listing_view", {
			p_listing_no: key
		});
		if (error) throw error;
		const row = Array.isArray(data) ? data[0] : data;
		const nextCount = Number(row && typeof row === "object" ? row.views : data);
		if (!Number.isFinite(nextCount)) return null;
		viewMap[key] = nextCount;
		updateViewCountElements(key, nextCount);
		return nextCount;
	} catch (err) {
		recentViewIncrementMap.delete(key);
		if (disableViewCountRpc(err)) return null;
		console.warn("조회수 증가 실패:", err);
		return null;
	}
}

function isMissingColumnError(error, columnName)
{
	const message = String(error && (error.message || error.details || "") || "");
	return message.includes(columnName) || message.includes(`'${columnName}'`) || message.includes(`"${columnName}"`);
}

async function refreshDetailEngagementCounts(item)
{
	const key = getItemViewKey(item);
	const viewKey = getListingViewKey(item) || key;
	if (!key && !viewKey) return;
	const hasCachedCounts = [viewMap[viewKey], favoriteCountMap[key], inquiryCountMap[key]]
		.some(value => Number.isFinite(Number(value)));
	const fetchedAt = Number(detailEngagementFetchedAtMap.get(key || viewKey) || 0);
	if (hasCachedCounts && Date.now() - fetchedAt < DETAIL_ENGAGEMENT_CACHE_MS) {
		if (currentDetailItem && getItemViewKey(currentDetailItem) === key) renderDetailSummaryMeta(currentDetailItem);
		return;
	}
	const seq = ++detailEngagementCountSeq;
	try {
		await loadSupabaseScript();
		const client = getMapListingsSupabaseClient();
		if (!client) return;

		if (!engagementCountRpcDisabled && typeof client.rpc === "function") {
			try {
				const { data, error } = await client.rpc("get_property_engagement_counts", {
					p_listing_ids: [key]
				});
				if (error) throw error;
				const row = Array.isArray(data) ? data.find(item => getViewCountKey(item && item.listing_id) === key) : null;
				if (row) {
					const views = Number(row.views);
					const favorites = Number(row.favorites);
					const inquiries = Number(row.inquiries);
					if (Number.isFinite(views)) viewMap[viewKey] = views;
					if (Number.isFinite(favorites)) favoriteCountMap[key] = favorites;
					if (Number.isFinite(inquiries)) inquiryCountMap[key] = inquiries;
					detailEngagementFetchedAtMap.set(key || viewKey, Date.now());
					if (seq === detailEngagementCountSeq && currentDetailItem && getItemViewKey(currentDetailItem) === key) {
						renderDetailSummaryMeta(currentDetailItem);
					}
					return;
				}
			} catch (engagementError) {
				if (isMissingRpcError(engagementError)) {
					engagementCountRpcDisabled = true;
				} else {
					console.warn("상세 서버 집계 불러오기 실패:", engagementError);
				}
			}
		}

		if (!viewCountRpcDisabled && viewKey) {
			try {
				const { data, error } = await client
					.from("listing_views")
					.select("listing_no, views")
					.eq("listing_no", viewKey)
					.maybeSingle();
				if (error) throw error;
				const count = Number(data && data.views);
				if (Number.isFinite(count)) viewMap[viewKey] = count;
			} catch (viewError) {
				if (!disableViewCountRpc(viewError)) console.warn("상세 조회수 불러오기 실패:", viewError);
			}
		}

		if (DETAIL_INQUIRY_COUNT_ENABLED) {
			try {
				const { data, error } = await client
					.from("support_inquiries")
					.select("listing_id")
					.eq("listing_id", key);
				if (error) throw error;
				inquiryCountMap[key] = Array.isArray(data) ? data.length : 0;
			} catch (inquiryError) {
				if (isMissingColumnError(inquiryError, "listing_id")) {
					inquiryCountMap[key] = 0;
				} else {
					console.warn("상세 문의수 불러오기 실패:", inquiryError);
				}
			}
		}

		if (seq === detailEngagementCountSeq && currentDetailItem && getItemViewKey(currentDetailItem) === key) {
			detailEngagementFetchedAtMap.set(key || viewKey, Date.now());
			renderDetailSummaryMeta(currentDetailItem);
		}
	} catch (err) {
		console.warn("상세 집계 불러오기 실패:", err);
	}
}

