function ensureFacilityMapVisibleLevel()
{
	if (!state.map || typeof state.map.getLevel !== "function" || typeof state.map.setLevel !== "function") return false;
	const currentLevel = Number(state.map.getLevel());
	if (!Number.isFinite(currentLevel) || currentLevel <= FACILITY_MAP_VISIBLE_LEVEL) return false;
	state.map.setLevel(FACILITY_MAP_VISIBLE_LEVEL, { animate: { duration: 300 }, __allowClusterRestore: true });
	return true;
}

function getFacilityOverlayZIndex(layer)
{
	return state.topFacilityOverlayLayer === layer ? FACILITY_OVERLAY_Z_INDEX_TOP : FACILITY_OVERLAY_Z_INDEX_BASE;
}

function syncFacilityOverlayZIndexes()
{
	(state.brokerOfficeOverlays || []).forEach((overlay) => {
		if (overlay && typeof overlay.setZIndex === "function") overlay.setZIndex(getFacilityOverlayZIndex("broker"));
	});
	(state.educationFacilityOverlays || []).forEach((overlay) => {
		if (overlay && typeof overlay.setZIndex === "function") overlay.setZIndex(getFacilityOverlayZIndex("education"));
	});
	(state.publicParkingOverlays || []).forEach((overlay) => {
		if (overlay && typeof overlay.setZIndex === "function") overlay.setZIndex(getFacilityOverlayZIndex("convenience"));
	});
}

function bringFacilityOverlayLayerToFront(layer)
{
	if (!layer) return;
	state.topFacilityOverlayLayer = layer;
	syncFacilityOverlayZIndexes();
}

function getFacilityMapLevel()
{
	if (!state.map || typeof state.map.getLevel !== "function") return null;
	const level = Number(state.map.getLevel());
	return Number.isFinite(level) ? level : null;
}

function getExpandedMapBounds(paddingRatio = FACILITY_BOUNDS_PADDING_RATIO)
{
	if (!state.map || typeof state.map.getBounds !== "function") return null;
	const bounds = state.map.getBounds();
	if (!bounds || typeof bounds.getSouthWest !== "function" || typeof bounds.getNorthEast !== "function") return null;
	const sw = bounds.getSouthWest();
	const ne = bounds.getNorthEast();
	const swLat = Number(sw && sw.getLat && sw.getLat());
	const swLng = Number(sw && sw.getLng && sw.getLng());
	const neLat = Number(ne && ne.getLat && ne.getLat());
	const neLng = Number(ne && ne.getLng && ne.getLng());
	if (![swLat, swLng, neLat, neLng].every(Number.isFinite)) return null;
	const latPadding = Math.max(Math.abs(neLat - swLat) * paddingRatio, 0.002);
	const lngPadding = Math.max(Math.abs(neLng - swLng) * paddingRatio, 0.002);
	return {
		swLat: Math.min(swLat, neLat) - latPadding,
		neLat: Math.max(swLat, neLat) + latPadding,
		swLng: Math.min(swLng, neLng) - lngPadding,
		neLng: Math.max(swLng, neLng) + lngPadding
	};
}

function isLatLngInsideBounds(latValue, lngValue, bounds)
{
	if (!bounds) return true;
	const lat = Number(latValue);
	const lng = Number(lngValue);
	if (!Number.isFinite(lat) || !Number.isFinite(lng)) return false;
	return lat >= bounds.swLat && lat <= bounds.neLat && lng >= bounds.swLng && lng <= bounds.neLng;
}

function getFacilityProjectionPoint(latValue, lngValue)
{
	if (!state.map || typeof state.map.getProjection !== "function" || !window.kakao || !kakao.maps || !kakao.maps.LatLng) return null;
	const lat = Number(latValue);
	const lng = Number(lngValue);
	if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
	try {
		const projection = state.map.getProjection();
		const point = projection && typeof projection.pointFromCoords === "function"
			? projection.pointFromCoords(new kakao.maps.LatLng(lat, lng))
			: null;
		const x = Number(point && point.x);
		const y = Number(point && point.y);
		return Number.isFinite(x) && Number.isFinite(y) ? { x, y } : null;
	} catch (e) {
		return null;
	}
}

function getBrokerMapCurrentUser()
{
	return (window.realjejuCurrentAuthUser || (typeof currentRealjejuAuthUser !== "undefined" ? currentRealjejuAuthUser : null) || null);
}

function isBrokerMapApprovedOffice(office)
{
	if (!office || typeof office !== "object") return false;
	if (office.deleted_at) return false;
	const status = typeof getBrokerOfficeRowStatus === "function"
		? getBrokerOfficeRowStatus(office)
		: String(office.status || "").trim().toLowerCase();
	return status === "active";
}

function isBrokerMapOfficeOwnedByUser(office, user)
{
	if (!office || !user) return false;
	const userId = normalizeItemId(user.id || user.user_id);
	const userEmail = String(user.email || "").trim().toLowerCase();
	const officeUserId = normalizeItemId(office.user_id || office.userId || office.owner_user_id);
	const officeEmail = String(office.email || office.owner_email || office.user_email || "").trim().toLowerCase();
	return !!(
		(userId && officeUserId && userId === officeUserId)
		|| (userEmail && officeEmail && userEmail === officeEmail)
	);
}

function getBrokerMapCurrentOffice()
{
	const office = window.realjejuCurrentBrokerOffice && typeof window.realjejuCurrentBrokerOffice === "object"
		? window.realjejuCurrentBrokerOffice
		: null;
	return isBrokerMapApprovedOffice(office) ? office : null;
}

function canUseBrokerOwnListingMapFilters()
{
	const user = getBrokerMapCurrentUser();
	const office = getBrokerMapCurrentOffice();
	return !!(user && user.id && office && isBrokerMapOfficeOwnedByUser(office, user));
}

function getBrokerSpecialtyListingOfficeName(item, payload, registrant)
{
	const candidates = [
		item?.agentOffice,
		payload && payload.office_name,
		registrant && registrant.office_name
	];
	return candidates.map(value => String(value || "").trim()).find(value => value && !/^(중개사\s*매물|공인중개사|개인\s*매물|개인\s*매물\s*·\s*직거래)$/.test(value)) || "";
}

function getBrokerListingIdentity(item)
{
	const payload = item && item.payload && typeof item.payload === "object" ? item.payload : {};
	const registrant = payload.registrant && typeof payload.registrant === "object" ? payload.registrant : {};
	const officeName = getBrokerSpecialtyListingOfficeName(item, payload, registrant);
	return {
		userId: normalizeItemId(item?.userId || item?.user_id || payload.user_id || registrant.user_id || registrant.agency_user_id),
		agencyId: normalizeItemId(item?.agencyId || item?.agency_id || payload.agency_id || registrant.agency_id),
		officeName: normalizeAgentOfficeKey(officeName)
	};
}

function getBrokerOfficeIdentityFromCurrentOffice()
{
	const office = getBrokerMapCurrentOffice();
	return {
		agencyId: normalizeItemId(office && office.id),
		userId: normalizeItemId(office && office.user_id),
		officeName: normalizeAgentOfficeKey(office && office.office_name)
	};
}

function matchesBrokerListingMapScope(item)
{
	const scope = String(state.brokerListingMapScope || "all");
	if (scope === "all") return true;
	if (!canUseBrokerOwnListingMapFilters()) return true;
	const user = getBrokerMapCurrentUser();
	const officeIdentity = getBrokerOfficeIdentityFromCurrentOffice();
	const itemIdentity = getBrokerListingIdentity(item);
	if (scope === "mine") {
		const userId = normalizeItemId(user && user.id);
		return !!(userId && itemIdentity.userId && itemIdentity.userId === userId);
	}
	if (scope === "office") {
		if (officeIdentity.agencyId && itemIdentity.agencyId) return officeIdentity.agencyId === itemIdentity.agencyId;
		if (officeIdentity.userId && itemIdentity.userId) return officeIdentity.userId === itemIdentity.userId;
		if (officeIdentity.officeName && itemIdentity.officeName) return officeIdentity.officeName === itemIdentity.officeName;
		return false;
	}
	return true;
}

function getBrokerSpecialtyTypeKey(item)
{
	const keys = getBrokerSpecialtyTypeKeys(item);
	return keys[0] || "";
}

function getBrokerSpecialtyTypeKeys(item)
{
	const text = String([
		item?.type,
		item?.typeFilter,
		item?.property_type,
		item?.property_type_label,
		item?.payload && item.payload.property_type,
		item?.payload && item.payload.property_type_label
	].filter(Boolean).join(" ")).replace(/\s+/g, "").toLowerCase();
	if (!text) return [];
	const keys = [];
	const addKey = (key) => {
		if (key && !keys.includes(key)) keys.push(key);
	};
	if (/오피스텔|officetel/.test(text)) {
		addKey("officetel");
		addKey("studio");
	}
	if (/생활형숙박시설|생활숙박시설|생활숙박|living[_-]?accommodation/.test(text)) addKey("studio");
	if (/원룸|투룸|쓰리룸|다가구|다세대|빌라|연립|도시형생활주택|room|villa|multi[_-]?family|multi[_-]?family[_-]?house|one[_-]?room|two[_-]?room/.test(text)) addKey("studio");
	if (/토지|임야|전|답|과수원|목장용지|대지|land|forest|field|lot/.test(text)) addKey("land");
	if (/상가|사무실|상업|근린|점포|건물|빌딩|상가주택|commercial|retail|office|store|building/.test(text)) addKey("commercial");
	if (/아파트|apartment|apt/.test(text)) addKey("apartment");
	return keys;
}

function normalizeBrokerSpecialtyOfficeKey(value)
{
	return normalizeAgentOfficeKey(value)
		.replace(/\(주\)|㈜|주식회사|유한회사|합자회사|합명회사/g, "")
		.replace(/공인중개사사무소|공인중개사무소|공인중개사|부동산중개법인|부동산중개|중개법인|중개사무소|사무소|부동산|법인/g, "")
		.replace(/[^0-9a-z가-힣]/gi, "")
		.trim();
}

function brokerSpecialtyOfficeNamesMatch(left, right)
{
	const exactLeft = normalizeAgentOfficeKey(left);
	const exactRight = normalizeAgentOfficeKey(right);
	if (exactLeft && exactRight && exactLeft === exactRight) return true;
	const compactLeft = normalizeBrokerSpecialtyOfficeKey(left);
	const compactRight = normalizeBrokerSpecialtyOfficeKey(right);
	if (!compactLeft || !compactRight) return false;
	if (compactLeft === compactRight) return true;
	const minLength = Math.min(compactLeft.length, compactRight.length);
	return minLength >= 3 && (compactLeft.includes(compactRight) || compactRight.includes(compactLeft));
}

function getBrokerSpecialtyStatsLookupKeys(office)
{
	const keys = [];
	const addKey = (key) => {
		if (key && !keys.includes(key)) keys.push(key);
	};
	const agencyId = normalizeItemId(office && (office.agencyId || office.agency_id));
	const userId = normalizeItemId(office && (office.userId || office.user_id));
	const officeName = office && (office.officeName || office.office_name || office.rawOfficeName);
	const officeNameKey = normalizeBrokerSpecialtyOfficeKey(officeName);
	if (agencyId) addKey("agency:" + agencyId);
	if (officeNameKey) addKey("office:" + officeNameKey);
	if (userId) addKey("user:" + userId);
	return keys;
}

function normalizeBrokerSpecialtyStatsRow(row)
{
	if (!row || typeof row !== "object") return null;
	const counts = {};
	const ratios = {};
	const specialtyFlags = {};
	BROKER_SPECIALTY_STAT_KEYS.forEach((key) => {
		counts[key] = Math.max(0, Number(row[key + "_count"]) || 0);
		ratios[key] = Math.max(0, Number(row[key + "_ratio"]) || 0);
		specialtyFlags[key] = !!row["is_" + key + "_specialty"];
	});
	return {
		statKey: String(row.stat_key || "").trim(),
		agencyId: normalizeItemId(row.agency_id),
		userId: normalizeItemId(row.user_id),
		officeName: String(row.office_name || "").trim(),
		officeNameKey: String(row.office_name_key || "").trim() || normalizeBrokerSpecialtyOfficeKey(row.office_name),
		total: Math.max(0, Number(row.total_count) || 0),
		counts,
		ratios,
		specialtyFlags,
		refreshedAt: String(row.refreshed_at || "").trim(),
		source: "db"
	};
}

function cacheBrokerSpecialtyStatsRows(rows)
{
	const normalizedRows = (Array.isArray(rows) ? rows : []).map(normalizeBrokerSpecialtyStatsRow).filter(Boolean);
	const map = new Map();
	const put = (key, stat) => {
		if (key && stat && !map.has(key)) map.set(key, stat);
	};
	normalizedRows.forEach((stat) => {
		put(stat.statKey, stat);
		if (stat.agencyId) put("agency:" + stat.agencyId, stat);
		if (stat.userId) put("user:" + stat.userId, stat);
		if (stat.officeNameKey) put("office:" + stat.officeNameKey, stat);
	});
	state.brokerSpecialtyStatsRows = normalizedRows;
	state.brokerSpecialtyStatsMap = map;
	state.brokerSpecialtyStatsLoadedAt = Date.now();
	return normalizedRows;
}

async function loadBrokerSpecialtyStats(options = {})
{
	const force = !!options.force;
	const now = Date.now();
	if (!force && state.brokerSpecialtyStatsUnavailable) return state.brokerSpecialtyStatsRows || [];
	if (!force
		&& Array.isArray(state.brokerSpecialtyStatsRows)
		&& now - Number(state.brokerSpecialtyStatsLoadedAt || 0) < BROKER_SPECIALTY_STATS_CACHE_MS) {
		return state.brokerSpecialtyStatsRows;
	}
	if (!force && state.brokerSpecialtyStatsLoadPromise) return state.brokerSpecialtyStatsLoadPromise;
	const client = getRealjejuSupabaseClient();
	if (!client) return state.brokerSpecialtyStatsRows || [];
	const promise = (async () => {
		try {
			const { data, error } = await client
				.from("broker_specialty_stats")
				.select(BROKER_SPECIALTY_STATS_SELECT)
				.order("total_count", { ascending: false });
			if (error) {
				state.brokerSpecialtyStatsUnavailable = true;
				console.warn("중개사 전문 통계 조회 실패:", error);
				return state.brokerSpecialtyStatsRows || [];
			}
			state.brokerSpecialtyStatsUnavailable = false;
			return cacheBrokerSpecialtyStatsRows(data);
		} catch (error) {
			state.brokerSpecialtyStatsUnavailable = true;
			console.warn("중개사 전문 통계 조회 오류:", error);
			return state.brokerSpecialtyStatsRows || [];
		} finally {
			state.brokerSpecialtyStatsLoadPromise = null;
		}
	})();
	state.brokerSpecialtyStatsLoadPromise = promise;
	return promise;
}

function getBrokerOfficeSpecialtyStatsFromCache(office)
{
	const map = state.brokerSpecialtyStatsMap instanceof Map ? state.brokerSpecialtyStatsMap : new Map();
	for (const key of getBrokerSpecialtyStatsLookupKeys(office)) {
		const stat = map.get(key);
		if (stat) return stat;
	}
	const officeName = office && (office.officeName || office.office_name || office.rawOfficeName);
	if (!officeName || !Array.isArray(state.brokerSpecialtyStatsRows)) return null;
	return state.brokerSpecialtyStatsRows.find(stat => brokerSpecialtyOfficeNamesMatch(officeName, stat.officeName || stat.officeNameKey)) || null;
}

function brokerOfficeMatchesListingForSpecialty(office, item)
{
	if (!office || !item) return false;
	const itemIdentity = getBrokerListingIdentity(item);
	const officeAgencyId = normalizeItemId(office.agencyId || office.agency_id);
	const officeUserId = normalizeItemId(office.userId || office.user_id);
	const officeName = office.officeName || office.office_name;
	return !!(
		(officeAgencyId && itemIdentity.agencyId && officeAgencyId === itemIdentity.agencyId)
		|| (officeUserId && itemIdentity.userId && officeUserId === itemIdentity.userId)
		|| (officeName && itemIdentity.officeName && brokerSpecialtyOfficeNamesMatch(officeName, itemIdentity.officeName))
	);
}

function getBrokerOfficeSpecialtyStats(office)
{
	const cachedStats = getBrokerOfficeSpecialtyStatsFromCache(office);
	if (cachedStats) return cachedStats;
	const sourceItems = Array.isArray(state.all) ? state.all : [];
	const counts = {};
	let total = 0;
	sourceItems.forEach((item) => {
		if (!brokerOfficeMatchesListingForSpecialty(office, item)) return;
		total += 1;
		getBrokerSpecialtyTypeKeys(item).forEach((key) => {
			if (key) counts[key] = (counts[key] || 0) + 1;
		});
	});
	return { total, counts };
}

function brokerOfficeMatchesSelectedMapFilter(office)
{
	const filterKey = String(state.brokerOfficeMapFilter || "none");
	if (filterKey === "none") return false;
	if (filterKey === "all") return true;
	const stats = getBrokerOfficeSpecialtyStats(office);
	if (stats.total < BROKER_SPECIALTY_MIN_LISTINGS) return false;
	const count = Number(stats.counts && stats.counts[filterKey] || 0);
	const savedRatio = Number(stats.ratios && stats.ratios[filterKey]);
	const ratio = Number.isFinite(savedRatio) && savedRatio > 0 ? savedRatio : count / stats.total;
	const savedFlag = !!(stats.specialtyFlags && stats.specialtyFlags[filterKey]);
	return count > 0 && (savedFlag || ratio >= BROKER_SPECIALTY_RATIO);
}

function scheduleFacilityViewportRender(delay = FACILITY_VIEWPORT_DEBOUNCE_MS)
{
	if (state.facilityViewportRenderTimer) {
		clearTimeout(state.facilityViewportRenderTimer);
		state.facilityViewportRenderTimer = null;
	}
	state.facilityViewportRenderTimer = setTimeout(() => {
		state.facilityViewportRenderTimer = null;
		renderVisibleFacilityOverlaysForViewport();
	}, delay);
}

async function renderVisibleFacilityOverlaysForViewport()
{
	if (isLifeSafetyOverlayVisible) await renderLifeSafetyOverlay();
	if (state.isEducationFacilitiesVisible) await syncEducationFacilityOverlaysForMapLevel();
	if (state.isPublicParkingVisible) await renderPublicParkingOverlays();
	if (state.isBrokerOfficesVisible) await renderBrokerOfficeOverlays();
}

const leftListDetailItemCache = new Map();
const leftListAreaDisplayRawCache = new Map();

let recommendIds = [];
let recommendAgents = [];

const REMOTE_BASE = "https://jeju-map.vercel.app/";

function toRemotePath(path)
{
	if (!path || typeof path !== "string") return path || "";
	if (/^https?:\/\//i.test(path)) return path;
	return new URL(path.replace(/^\.\//, ""), REMOTE_BASE).toString();
}

