function isFilterSetExactlyValues(set, values)
{
	if (!(set instanceof Set) || !Array.isArray(values) || set.size !== values.length) return false;
	return values.every(value => set.has(value));
}
function isDefaultDealFilterSelection()
{
	return !(selectedDeal instanceof Set) || selectedDeal.size === 0;
}
function isDefaultTypeFilterSelection()
{
	return isFilterSetExactlyValues(selectedType, DEFAULT_TYPE_FILTER_VALUES);
}
function matchesDealFilterValue(itemDeal, selectedDealValue)
{
	const deal = String(itemDeal || "").trim();
	const selected = String(selectedDealValue || "").trim();
	if (!deal || !selected) return false;
	if (deal === selected) return true;
	return selected === "월세" && (deal === "년세" || deal === "연세");
}
function matchesSelectedDealFilter(itemDeal, dealValues)
{
	if (!(dealValues instanceof Set) || dealValues.size === 0) return false;
	const deals = (Array.isArray(itemDeal) ? itemDeal : [itemDeal])
		.map((deal) => {
			const label = typeof getMapDealLabel === "function" ? getMapDealLabel(deal) : deal;
			return String(label || deal || "").trim();
		})
		.filter(Boolean);
	return Array.from(dealValues).some(value => deals.some(deal => matchesDealFilterValue(deal, value)));
}
function ensureTypeFilterHasSelection()
{
	if (!(selectedType instanceof Set)) selectedType = createDefaultTypeFilterSet();
}

function normalizeBrokerOfficeRegNo(value)
{
	const text = String(value || "").trim();
	if (/^\d{5}-\d{4}-\d{5}$/.test(text)) return text;
	const digits = text.replace(/\D/g, "");
	if (!/^\d{14}$/.test(digits)) return text;
	return `${digits.slice(0, 5)}-${digits.slice(5, 9)}-${digits.slice(9, 14)}`;
}

function getAllTopPropertyTypeFilterValues()
{
	const values = new Set();
	document.querySelectorAll("#typeButtons input, [data-all-filter-type]").forEach((input) => {
		if (!input) return;
		const value = String(input.dataset.value || input.dataset.allFilterType || input.value || "").trim();
		if (!value || value === "전체" || value === "all") return;
		values.add(value);
	});
	if (!values.size) {
		[...DEFAULT_TYPE_FILTER_VALUES, ...ALL_FILTER_RESET_TYPE_VALUES].forEach((value) => values.add(value));
	}
	return values;
}

function selectAllTopPropertyTypeFilters(options = {})
{
	selectedType = getAllTopPropertyTypeFilterValues();
	document.querySelectorAll("#typeButtons input, [data-all-filter-type]").forEach((input) => {
		if (!input) return;
		const value = String(input.dataset.value || input.dataset.allFilterType || input.value || "").trim();
		if (!value || value === "전체" || value === "all") return;
		input.checked = selectedType.has(value);
	});
	if (typeof window !== "undefined" && typeof window.realjejuSyncTypeFilterUI === "function") {
		window.realjejuSyncTypeFilterUI();
	}
	if (typeof syncLeftAllButtonToMapFilters === "function") syncLeftAllButtonToMapFilters();
	if (options.apply !== false && typeof applyFilter === "function") applyFilter();
}
