function syncMapFilterbarDetailHidden()
{
	const panel = document.getElementById("sidebarDetailPanel");
	const panelInlineHidden = !!(panel && (
		panel.style.display === "none"
		|| panel.style.visibility === "hidden"
		|| panel.style.opacity === "0"
	));
	const isRecentShared = document.body.classList.contains("recent-shared-detail-mode")
		|| document.body.classList.contains("list-shared-detail-mode");
	const detailClassActive = (document.body.classList.contains("detail-page-panel-open")
		|| document.body.classList.contains("shared-detail-mode"))
		&& !isRecentShared;
	const detailPanelVisible = !!(sidebar && sidebar.classList.contains("expanded") && panel && !panelInlineHidden);
	const shouldHide = detailClassActive || (detailPanelVisible && !isRecentShared);
	document.body.classList.toggle("map-filterbar-detail-hidden", shouldHide);
	keepTopbarAddressSearchVisible();
	if (shouldHide && typeof requestAnimationFrame === "function") {
		requestAnimationFrame(keepTopbarAddressSearchVisible);
		setTimeout(keepTopbarAddressSearchVisible, 80);
	}
	if (!shouldHide && typeof scheduleMapFilterScrollSync === "function") scheduleMapFilterScrollSync();
}

