const MAP_TOOL_POPOVER_Z_INDEX_BACK = 2147483600;
const MAP_TOOL_POPOVER_Z_INDEX_FRONT = 2147483647;

function syncMapToolPopoverZOrder(activePanel)
{
	[educationFacilityFilterPanel, convenienceFacilityFilterPanel, developmentFacilityFilterPanel, brokerOfficeFilterPanel, mapTypePopover].forEach((panel) => {
		if (!panel || !panel.style) return;
		panel.style.zIndex = panel === activePanel ? String(MAP_TOOL_POPOVER_Z_INDEX_FRONT) : String(MAP_TOOL_POPOVER_Z_INDEX_BACK);
	});
}

function positionMapTypePopover()
{
	if (!mapTypePopover || !mapTypeMenuBtn || !mapTypePopover.classList.contains("open")) return;
	const rect = mapTypeMenuBtn.getBoundingClientRect();
	const mapToolGroup = mapTypeMenuBtn.closest ? mapTypeMenuBtn.closest(".map-map-tool-group") : null;
	const groupRect = mapToolGroup ? mapToolGroup.getBoundingClientRect() : null;
	const popoverRect = mapTypePopover.getBoundingClientRect();
	const targetHeight = groupRect && Number.isFinite(groupRect.height) ? groupRect.height : popoverRect.height;
	const left = Math.max(8, rect.left - popoverRect.width - 8);
	const top = Math.min(Math.max(8, groupRect ? groupRect.top : rect.top), window.innerHeight - targetHeight - 8);
	mapTypePopover.style.position = "fixed";
	mapTypePopover.style.left = left + "px";
	mapTypePopover.style.top = top + "px";
	mapTypePopover.style.height = targetHeight + "px";
	mapTypePopover.style.right = "auto";
}

function updateMapTypeButtons()
{
	if (mapTypeRoadBtn) mapTypeRoadBtn.classList.toggle("active", currentMapTypeMode === "roadmap");
	if (mapTypeSatelliteBtn) mapTypeSatelliteBtn.classList.toggle("active", currentMapTypeMode === "satellite");
	if (mapTypeTerrainBtn) mapTypeTerrainBtn.classList.toggle("active", currentMapTypeMode === "terrain");
	if (mapTypeCadastralBtn) {
		mapTypeCadastralBtn.classList.toggle("active", isMapCadastralOverlayVisible);
		mapTypeCadastralBtn.setAttribute("aria-pressed", isMapCadastralOverlayVisible ? "true" : "false");
	}
	if (mapTypeMenuBtn) {
		mapTypeMenuBtn.classList.toggle("active", !!(mapTypePopover && mapTypePopover.classList.contains("open")));
		mapTypeMenuBtn.setAttribute("aria-expanded", mapTypePopover && mapTypePopover.classList.contains("open") ? "true" : "false");
	}
	if (mapRoadviewBtn) {
		mapRoadviewBtn.classList.toggle("active", isMapRoadviewOverlayVisible);
		mapRoadviewBtn.setAttribute("aria-pressed", isMapRoadviewOverlayVisible ? "true" : "false");
	}
}

function syncMapCadastralOverlay()
{
	if (!state.map || !window.kakao || !kakao.maps || !kakao.maps.MapTypeId.USE_DISTRICT) return;
	try {
		state.map.removeOverlayMapTypeId(kakao.maps.MapTypeId.USE_DISTRICT);
		if (isMapCadastralOverlayVisible) state.map.addOverlayMapTypeId(kakao.maps.MapTypeId.USE_DISTRICT);
	} catch (e) {}
}

function toggleMapCadastralOverlay()
{
	isMapCadastralOverlayVisible = !isMapCadastralOverlayVisible;
	syncMapCadastralOverlay();
	updateMapTypeButtons();
}

function setMapTypeMode(mode)
{
	if (!state.map || !window.kakao || !kakao.maps) return;

	currentMapTypeMode = mode;

	try {
		state.map.removeOverlayMapTypeId(kakao.maps.MapTypeId.TERRAIN);
	} catch (e) {}

	if (mode === "satellite") {
		state.map.setMapTypeId(kakao.maps.MapTypeId.SKYVIEW);
	} else if (mode === "terrain") {
		state.map.setMapTypeId(kakao.maps.MapTypeId.ROADMAP);
		if (kakao.maps.MapTypeId.TERRAIN) state.map.addOverlayMapTypeId(kakao.maps.MapTypeId.TERRAIN);
	} else {
		state.map.setMapTypeId(kakao.maps.MapTypeId.ROADMAP);
		currentMapTypeMode = "roadmap";
	}

	syncMapCadastralOverlay();
	updateMapTypeButtons();
}


