function setMapRoadviewOverlayVisible(visible, options = {})
{
	const shouldShow = !!visible;
	if (!state.map || !window.kakao || !kakao.maps) return;
	removeMapRoadviewOverlay();

	isMapRoadviewOverlayVisible = shouldShow;
	if (document.body) {
		document.body.classList.toggle("map-roadview-overlay-open", isMapRoadviewOverlayVisible);
	}
	syncRoadviewTopbarVisibility();
	if (isMapRoadviewOverlayVisible) {
		if (typeof closeMapFilterDropdownsExcept === "function") closeMapFilterDropdownsExcept(null);
		if (typeof closeAllFilterHelp === "function") closeAllFilterHelp();
		if (distanceMeasureActive) setDistanceMeasureActive(false, { clear: true });
		addMapRoadviewOverlayForCurrentLevel();
	} else {
		clearRoadviewPickOverlay();
	}
	syncRoadviewTopbarVisibility();
	if (typeof state.map.setDisableDoubleClickZoom === "function") {
		state.map.setDisableDoubleClickZoom(isMapRoadviewOverlayVisible);
	}
	updateMapTypeButtons();
}

