window.realjejuOpenPresaleMapMode = openPresaleMapMode;
window.realjejuClosePresaleMapMode = closePresaleMapMode;

function getRecommendationPool(items)
{
	const list = Array.isArray(items) ? items : [];
	if (!recommendIds.length) return [];

	const idSet = new Set(recommendIds.map(normalizeItemId));
	return list.filter(item => item && idSet.has(normalizeItemId(item.id)));
}

function getRecommendationCandidate(items)
{
	const pool = getRecommendationPool(items);
	if (!pool.length) return null;

	if (state.selectedMarkerId != null) {
		const selected = pool.find(item => normalizeItemId(item.id) === normalizeItemId(state.selectedMarkerId));
		if (selected) return selected;
	}

	if (pool.length === 1) return pool[0];

	const previousId = state.recommendItem ? normalizeItemId(state.recommendItem.id) : null;
	const candidates = pool.filter(item => normalizeItemId(item.id) !== previousId);
	const source = candidates.length ? candidates : pool;
	const randomIndex = Math.floor(Math.random() * source.length);
	return source[randomIndex];
}

function normalizeRecommendAgent(agent)
{
	if (!agent || typeof agent !== "object") return null;
	const normalizedPhone = String(agent.phone || "").trim();
	return {
		...agent,
		id: normalizeItemId(agent.id),
		image: toRemotePath(agent.image || ""),
		phone: normalizedPhone,
		office: agent.office || "",
		name: agent.name || "",
		desc: agent.desc || "",
		address: agent.address || "",
		regNo: agent.regNo || "",
		link: agent.link || ""
	};
}

function getRecommendationAgentCandidate()
{
	if (!Array.isArray(recommendAgents) || !recommendAgents.length) return null;
	if (recommendAgents.length === 1) return recommendAgents[0];

	const previousId = state.recommendAgent ? normalizeItemId(state.recommendAgent.id) : null;
	const candidates = recommendAgents.filter(agent => normalizeItemId(agent.id) !== previousId);
	const source = candidates.length ? candidates : recommendAgents;
	const randomIndex = Math.floor(Math.random() * source.length);
	return source[randomIndex];
}

function renderRecommendAgentCard(agent)
{
	if (!mapAgentCard) return;
	mapAgentCard.style.display = "none";
	mapAgentCard.setAttribute("aria-hidden", "true");
	state.recommendAgent = null;
}

function refreshRecommendAgentCard()
{
	if (!mapAgentCard) return;
	if (state.isRecommendAgentDismissed) {
		renderRecommendAgentCard(null);
		return;
	}

	const hasCurrent = state.recommendAgent
	&& recommendAgents.some(agent => normalizeItemId(agent.id) === normalizeItemId(state.recommendAgent.id));

	if (!hasCurrent) {
		state.recommendAgent = getRecommendationAgentCandidate();
	}

	renderRecommendAgentCard(state.recommendAgent);
}

function renderRecommendationCard(item)
{
	if (!mapRecommendCard) return;

	if (!item || state.isRecommendCardDismissed) {
		mapRecommendCard.style.display = "none";
		mapRecommendCard.onclick = null;
		mapRecommendCard.setAttribute("aria-hidden", "true");
		return;
	}

	state.recommendItem = item;
	mapRecommendCard.style.display = "block";
	mapRecommendCard.setAttribute("aria-hidden", "false");

	if (mapRecommendThumb) {
		mapRecommendThumb.style.backgroundImage = `url('${escapeHtml(item.image || "")}')`;
	}
	if (mapRecommendType) {
		mapRecommendType.textContent = getCardTypeBadgeLabel(item.type || "-");
	}
	if (mapRecommendDeal) {
		mapRecommendDeal.textContent = item.dealType || "매매";
	}
	if (mapRecommendPrice) {
		mapRecommendPrice.textContent = item.price || "-";
	}
	if (mapRecommendTitleText) {
		mapRecommendTitleText.textContent = sanitizePublicListingText(item.title || "추천 매물", item);
	}
	if (mapRecommendAddress) {
		mapRecommendAddress.textContent = getPublicListingDisplayAddress(item) || "-";
	}

	mapRecommendCard.onclick = async (e) => {
		if (e.target.closest(".map-recommend-close")) return;
		if (e.target.closest(".map-recommend-footer")) return;
		if (e.target.closest("label, input")) return;
		if (e.target.closest("a, button")) return;

		const normalizedId = normalizeItemId(item.id);

			closeEducationFacilityDetailForPropertyInteraction();
			if (typeof closeRoadviewPanelForPropertyInteraction === "function") {
				await closeRoadviewPanelForPropertyInteraction();
			} else if (typeof hideRoadview === "function") {
				await hideRoadview();
			}
			state.selectionMode = "single";
		state.selectedClusterKey = null;
		state.selectedMarkerId = normalizedId;
		clearListLock();
		highlightCard(normalizedId);
		updateMarkerSelection(normalizedId, [normalizedId]);

		if (detailScroll) detailScroll.scrollTop = 0;
		allowDetailOpenFromListClick = true;
		try {
			await openDetailPanel(item, { syncUrl: false });
		} finally {
			allowDetailOpenFromListClick = false;
		}

		syncDetailUrl(item.id);

		if (detailScroll) detailScroll.scrollTop = 0;
		await focusProperty(item.id);

		setTimeout(() => {
			highlightCard(normalizedId);
			refreshClusterBadges();
		}, 0);
	};
}

function refreshRecommendationCard(items)
{
	if (!mapRecommendCard) return;
	if (state.isRecommendCardDismissed) {
		renderRecommendationCard(null);
		return;
	}

	const pool = getRecommendationPool(items);
	const poolKey = pool.map(item => normalizeItemId(item.id)).sort((a, b) => a.localeCompare(b)).join(",");

	if (!pool.length) {
		state.recommendItem = null;
		state.lastRecommendPoolKey = "";
		renderRecommendationCard(null);
		return;
	}

	const keepCurrent = state.lastRecommendPoolKey === poolKey
	&& state.recommendItem
	&& pool.some(item => normalizeItemId(item.id) === normalizeItemId(state.recommendItem.id));

	if (!keepCurrent) {
		state.recommendItem = getRecommendationCandidate(pool);
		state.lastRecommendPoolKey = poolKey;
	}

	renderRecommendationCard(state.recommendItem);
}

function refreshViewportList(options = {})
{
	const agentItems = getAgentFilteredListItems();
	if (agentItems) {
		if (getLeftListSourceKey(agentItems) !== state.leftListSourceKey) {
			resetLeftListPagination(agentItems);
		}
		if (!state.leftListItems.length && agentItems.length) {
			propertyList.innerHTML = "";
			loadMoreLeftListItems({ sourceItems: agentItems });
		} else {
			renderList(state.leftListItems);
			setPagedListInfo(agentItems.length, state.leftListItems.length);
		}
		const agentLabel = state.agentListFilter?.label || "공인중개사";
		setResultInfo(`${agentLabel} 매물 ${agentItems.length}건`);
		setListInfo(state.leftListItems.length < agentItems.length ? `${agentItems.length}개 중 ${state.leftListItems.length}개` : `총 ${agentItems.length}개 매물`);
		refreshRecommendAgentCard();
		refreshRecommendationCard(state.filtered);
		return agentItems;
	}

	const lockedItems = getLockedListItems();
	if (lockedItems) {
		const shouldKeepLockedItems = (state.keepLockedListOnMapClick && state.isListOpen) || sidebar.classList.contains("expanded") || isLockedSelectionStillVisible();
		if (shouldKeepLockedItems) {
			const sortedLockedItems = sortItems(lockedItems);
			if (getLeftListSourceKey(sortedLockedItems) !== state.leftListSourceKey) {
				resetLeftListPagination(sortedLockedItems);
			}
			if (!state.leftListItems.length && sortedLockedItems.length) {
				propertyList.innerHTML = "";
				loadMoreLeftListItems({ sourceItems: sortedLockedItems });
			} else {
				renderList(state.leftListItems);
			}
			setResultInfo(`선택 매물 ${sortedLockedItems.length}건`);
			setListInfo(state.leftListItems.length < sortedLockedItems.length ? `${sortedLockedItems.length}개 중 ${state.leftListItems.length}개` : `총 ${sortedLockedItems.length}개 매물`);
			refreshRecommendAgentCard();
			refreshRecommendationCard(state.filtered);
			return sortedLockedItems;
		}

		clearListLock();
		state.selectedClusterKey = null;
		state.selectedMarkerId = null;
		state.selectionMode = null;
		updateMarkerSelection(null);

		setTimeout(() => {
			refreshClusterBadges();
		}, 0);
	}

	const viewportItems = sortItems(getViewportFilteredItems(state.filtered));
	if (getLeftListSourceKey(viewportItems) !== state.leftListSourceKey) {
		resetLeftListPagination(viewportItems);
	}

	if (state.initialRandomListActive !== false && isInitialAllListMode() && !sidebar.classList.contains("expanded") && !state.selectionMode) {
		propertyList.innerHTML = "";
		setResultInfo(`총 ${state.filtered.length}건`);
		setListInfo(`총 ${state.filtered.length}개 매물`);
		refreshRecommendAgentCard();
		refreshRecommendationCard(state.filtered);
		return [];
	}

	const shouldPreserveList = sidebar.classList.contains("expanded")
	&& state.selectionMode === "single"
	&& state.selectedMarkerId != null
	&& viewportItems.length === 0
	&& Array.isArray(state.lastViewportListIds)
	&& state.lastViewportListIds.length > 0;

	if (shouldPreserveList) {
		const preservedIdSet = new Set(state.lastViewportListIds.map(normalizeItemId));
		const preservedItems = sortItems((state.filtered || []).filter(item => preservedIdSet.has(normalizeItemId(item.id))));
		if (preservedItems.length) {
			renderList(preservedItems);
			setResultInfo(`총 ${preservedItems.length}건`);
			setListInfo(`총 ${preservedItems.length}개 매물`);
			refreshRecommendAgentCard();
			refreshRecommendationCard(state.filtered);
			return preservedItems;
		}
	}

	if (!state.leftListItems.length && viewportItems.length) {
		propertyList.innerHTML = "";
		loadMoreLeftListItems({ sourceItems: viewportItems });
	} else {
		renderList(state.leftListItems);
		setPagedListInfo(viewportItems.length, state.leftListItems.length);
		if (state.leftListItems.length) {
			state.lastViewportListIds = state.leftListItems.map(item => normalizeItemId(item.id));
		}
	}
	refreshRecommendAgentCard();
	refreshRecommendationCard(state.filtered);
	return viewportItems;
}

function updateSidebarWidth()
{
	const rootStyle = document.documentElement.style;
	const listWidth = getComputedStyle(document.documentElement).getPropertyValue("--sidebar-list-width").trim() || "360px";
	const nextWidth = state.isListOpen ? listWidth : "0px";
	rootStyle.setProperty("--sidebar-current-width", nextWidth);
	document.body.classList.toggle("sidebar-list-collapsed", !state.isListOpen);
	if (typeof syncMapFilterVisiblePanelEdge === "function") syncMapFilterVisiblePanelEdge();
	updateMapPanelToggleState();
	if (typeof scheduleMapFilterScrollSyncBurst === "function") {
		scheduleMapFilterScrollSyncBurst();
	} else if (typeof scheduleMapFilterScrollSync === "function") {
		scheduleMapFilterScrollSync();
	}
}

function openSidebarList()
{
	state.isListOpen = true;
	updateSidebarWidth();
	refreshMapLayout();
	if (typeof scheduleMapFilterScrollSyncBurst === "function") scheduleMapFilterScrollSyncBurst();
}

function closeSidebarList()
{
	clearAgentListFilter();
	clearListLock();
	state.selectedClusterKey = null;
	state.selectedMarkerId = null;
	state.selectedMarkerIds = new Set();
	state.selectionMode = null;
	updateMarkerSelection(null, []);
	refreshClusterBadges();
	state.isListOpen = false;
	updateSidebarWidth();
	const detailPanel = document.getElementById("sidebarDetailPanel");
	const detailPanelVisible = !!(sidebar && sidebar.classList.contains("expanded") && detailPanel && detailPanel.style.display !== "none" && detailPanel.style.visibility !== "hidden" && detailPanel.style.opacity !== "0");
	if (detailPanelVisible || document.body.classList.contains("detail-page-panel-open") || document.body.classList.contains("shared-detail-mode")) {
		closeDetailPanel();
	} else {
		syncMapFilterbarDetailHidden();
		if (typeof scheduleMapFilterScrollSync === "function") scheduleMapFilterScrollSync();
	}
	refreshMapLayout();
}

function collapseSidebarListForMapOverlayPanelSwitch()
{
	const listIsOpen = !!(state && state.isListOpen) || !document.body.classList.contains("sidebar-list-collapsed");
	if (!listIsOpen) return;
	clearAgentListFilter();
	clearListLock();
	state.selectedClusterKey = null;
	state.selectedMarkerId = null;
	state.selectedMarkerIds = new Set();
	state.selectionMode = null;
	updateMarkerSelection(null, []);
	refreshClusterBadges();
	state.isListOpen = false;
	updateSidebarWidth();
	if (typeof syncMapFilterbarDetailHidden === "function") syncMapFilterbarDetailHidden();
	if (typeof refreshMapLayout === "function") refreshMapLayout();
}

function moveMapToDefaultCenter()
{
	if (!state.map || !window.kakao || !kakao.maps) return;
	const defaultLatLng = new kakao.maps.LatLng(DEFAULT_MAP_CENTER.lat, DEFAULT_MAP_CENTER.lng);
	state.map.setCenter(defaultLatLng);
	state.map.setLevel(DEFAULT_MAP_CENTER.level, { animate: false });
}

function applyInitialMapCenter()
{
	if (!state.map || !window.kakao || !kakao.maps) return Promise.resolve(false);
	moveMapToDefaultCenter();
	return Promise.resolve(false);
}

function refreshMapLayout()
{
	if (!state || !state.map) return;
	const run = () => {
		try {
			const lockedCenter = typeof state.map.getCenter === "function" ? state.map.getCenter() : null;
			if (state.map && typeof state.map.relayout === "function") {
				state.map.relayout();
			}
			if (lockedCenter && typeof state.map.setCenter === "function") {
				state.map.setCenter(lockedCenter, { __allowClusterRestore: true });
			}
		} catch (error) {
			console.warn("지도 레이아웃 갱신 실패:", error);
		}
	};

	run();
	if (typeof requestAnimationFrame === "function") {
		requestAnimationFrame(run);
		requestAnimationFrame(() => requestAnimationFrame(run));
	}
	setTimeout(run, 80);
	setTimeout(run, 240);
}

function rememberCollapsedMapPanelForHome()
{
	if (document.body.classList.contains("map-panels-collapsed")) {
		restoreMapPanelsCollapsedOnHome = true;
	}
}

function forgetCollapsedMapPanelForHome()
{
	restoreMapPanelsCollapsedOnHome = false;
}

function isRealjejuWorkspacePageOpen()
{
	return Object.values(REALJEJU_WORKSPACE_ROUTE_CONFIG).some((route) => document.body.classList.contains(route.bodyClass));
}

// [CORE] 공통 워크스페이스 라우팅 설정.
// - key: 논리 페이지 식별자, bodyClass: 화면 표시용 바디 클래스, panelIds: 토글할 패널 리스트.
const REALJEJU_WORKSPACE_ROUTE_CONFIG = {
	notice: {
		bodyClass: "notice-page-open",
		panelIds: ["noticePagePanel"]
	},
	mySuite: {
		bodyClass: "my-suite-page-open",
		panelIds: ["mySuitePanel"]
	},
	admin: {
		bodyClass: "admin-page-open",
		panelIds: ["adminPagePanel"]
	},
	brokerHome: {
		bodyClass: "broker-home-page-open",
		panelIds: ["brokerHomePanel"]
	},
	propertyRegister: {
		bodyClass: "property-register-page-open",
		panelIds: ["propertyRegisterPage"]
	},
	payment: {
		bodyClass: "payment-page-open",
		panelIds: ["paymentPagePanel"]
	},
	myInfo: {
		bodyClass: "myinfo-page-open",
		panelIds: ["myInfoPagePanel"]
	},
	profileEdit: {
		bodyClass: "profile-edit-page-open",
		panelIds: ["profileEditPagePanel"]
	},
	brokerOfficeInfo: {
		bodyClass: "broker-office-info-page-open",
		panelIds: ["brokerOfficeInfoPagePanel"]
	},
	brokerOfficeEdit: {
		bodyClass: "broker-office-edit-page-open",
		panelIds: ["brokerOfficeEditPagePanel"]
	}
};

const REALJEJU_WORKSPACE_BODY_CLASS_TO_KEY = Object.fromEntries(
	Object.entries(REALJEJU_WORKSPACE_ROUTE_CONFIG).map(([routeKey, route]) => [route.bodyClass, routeKey])
);

// [CORE] 라우트 키 정규화 (key 또는 bodyClass 입력을 모두 흡수).
function normalizeRealjejuWorkspaceRouteKey(routeKey)
{
	if (!routeKey) return "";
	if (REALJEJU_WORKSPACE_ROUTE_CONFIG[routeKey]) return routeKey;
	return REALJEJU_WORKSPACE_BODY_CLASS_TO_KEY[String(routeKey)] || "";
}

// [CORE] 라우트 이동 시 기존 워크스페이스 페이지를 일괄 종료(닫기 + aria-hidden 처리).
function closeRealjejuWorkspacePages(excludeRouteKey)
{
	const normalizedExclude = normalizeRealjejuWorkspaceRouteKey(excludeRouteKey);
	const excludePanelIds = new Set((REALJEJU_WORKSPACE_ROUTE_CONFIG[normalizedExclude] || {}).panelIds || []);

	Object.entries(REALJEJU_WORKSPACE_ROUTE_CONFIG).forEach(([routeKey, route]) => {
		document.body.classList.remove(route.bodyClass);
		(route.panelIds || []).forEach((panelId) => {
			if (excludeRouteKey && excludePanelIds.has(panelId)) return;
			const panel = document.getElementById(panelId);
			if (panel) panel.setAttribute("aria-hidden", "true");
		});
	});
}

// [CORE] 단일 워크스페이스 페이지 종료 후 상태 정리.
function closeRealjejuWorkspacePage(routeKey)
{
	const normalizedRoute = normalizeRealjejuWorkspaceRouteKey(routeKey);
	if (!normalizedRoute) return null;
	const route = REALJEJU_WORKSPACE_ROUTE_CONFIG[normalizedRoute];
	document.body.classList.remove(route.bodyClass);
	(route.panelIds || []).forEach((panelId) => {
		const panel = document.getElementById(panelId);
		if (!panel) return;
		panel.setAttribute("aria-hidden", "true");
	});
	return route;
}

// [CORE] 워크스페이스 페이지 열기 단일 진입점.
// - 중복 패널 개방, 바디 클래스 충돌, 포커스/접근성 상태를 한 곳에서 통제.
function openRealjejuWorkspacePage(routeKey, options = {})
{
	const normalizedRoute = normalizeRealjejuWorkspaceRouteKey(routeKey);
	if (!normalizedRoute) return null;

	const route = REALJEJU_WORKSPACE_ROUTE_CONFIG[normalizedRoute];
	const targetPanelId = options.panelId || route.panelIds[0];
	if (!targetPanelId) return null;

	closeRealjejuWorkspacePages(normalizedRoute);

	if (options.preserveSidebar !== true) {
		document.body.classList.add("sidebar-list-collapsed");
		if (typeof state !== "undefined" && state) state.isListOpen = false;
		if (sidebar) sidebar.classList.remove("expanded");
	}

	document.body.classList.add(route.bodyClass);
	(route.panelIds || []).forEach((panelId) => {
		const panel = document.getElementById(panelId);
		if (!panel) return;
		panel.setAttribute("aria-hidden", panelId === targetPanelId ? "false" : "true");
	});

	const panel = document.getElementById(targetPanelId);
	if (panel && options.scrollTop) panel.scrollTop = 0;
	return {
		...route,
		routeKey: normalizedRoute,
		panel: panel || null,
		targetPanelId
	};
}

function restoreCollapsedMapPanelOnHome()
{
	if (!restoreMapPanelsCollapsedOnHome || isRealjejuWorkspacePageOpen()) return;
	restoreMapPanelsCollapsedOnHome = false;
	if (sidebar) sidebar.classList.add("expanded");
	document.body.classList.remove("detail-page-panel-open");
	document.body.classList.add("map-panels-collapsed");
	const detailPanel = document.getElementById("sidebarDetailPanel");
	if (detailPanel) {
		detailPanel.style.display = "";
		detailPanel.style.opacity = "0";
		detailPanel.style.visibility = "hidden";
		detailPanel.style.pointerEvents = "none";
	}
	updateMapPanelToggleState();
	refreshMapLayout();
	setTimeout(refreshMapLayout, 260);
}

function updateMapPanelToggleState()
{
	if (!mapPanelToggle || !sidebar) {
		syncMapPropertyToggleButton();
		return;
	}
	if (document.body.classList.contains("recent-shared-detail-mode")
		|| document.body.classList.contains("list-shared-detail-mode")) {
		mapPanelToggle.hidden = true;
		mapPanelToggle.setAttribute("aria-hidden", "true");
		mapPanelToggle.removeAttribute("aria-expanded");
		syncMapPropertyToggleButton();
		syncMapFilterbarDetailHidden();
		return;
	}
	mapPanelToggle.removeAttribute("aria-hidden");
	const pagePanelOpen = isRealjejuWorkspacePageOpen();
	if (pagePanelOpen) {
		forgetCollapsedMapPanelForHome();
		document.body.classList.remove("map-detail-panel-active", "map-panels-collapsed");
		mapPanelToggle.hidden = true;
		syncMapPropertyToggleButton();
		syncMapFilterbarDetailHidden();
		return;
	}
	const collapsed = document.body.classList.contains("map-panels-collapsed");
	const detailActive = sidebar.classList.contains("expanded") && !document.body.classList.contains("detail-page-panel-open");
	document.body.classList.toggle("map-detail-panel-active", detailActive);

	mapPanelToggle.hidden = !(detailActive || collapsed);
	mapPanelToggle.setAttribute("aria-expanded", collapsed ? "false" : "true");
	mapPanelToggle.setAttribute("aria-label", collapsed ? "패널 펼치기" : "패널 접기");
	mapPanelToggle.title = collapsed ? "패널 펼치기" : "패널 접기";
	syncMapPropertyToggleButton();
	syncMapFilterbarDetailHidden();
}

function setMapPropertyMarkersVisible(visible)
{
	const shouldShow = !!visible;
	state.isPropertyMarkersVisible = shouldShow;
	document.body.classList.toggle("map-properties-hidden", !shouldShow);
	if (!shouldShow) {
		state.selectedClusterKey = null;
		state.selectedMarkerId = null;
		state.selectedMarkerIds = new Set();
		state.selectionMode = null;
		clearMapObjects();
		updateMarkerSelection(null);
	} else if (state.filtered && state.filtered.length) {
		renderMarkers(state.filtered, { preserveViewport: true });
	}
	syncMapPropertyToggleButton();
}

function toggleMapPropertyPanels()
{
	setMapPropertyMarkersVisible(state.isPropertyMarkersVisible === false);
}

window.toggleMapPropertyPanels = toggleMapPropertyPanels;
window.setMapPropertyMarkersVisible = setMapPropertyMarkersVisible;
window.setMapPanelsCollapsed = setMapPanelsCollapsed;

function setMapPanelsCollapsed(collapsed)
{
	const shouldCollapse = !!collapsed;
	restoreMapPanelsCollapsedOnHome = shouldCollapse;
	if (!shouldCollapse) {
		state.isListOpen = true;
		document.body.classList.remove("sidebar-list-collapsed");
	}
	if (!shouldCollapse && sidebar) {
		sidebar.classList.add("expanded");
		document.body.classList.remove("detail-page-panel-open");
	}
	document.body.classList.toggle("map-panels-collapsed", shouldCollapse);
	const detailPanel = document.getElementById("sidebarDetailPanel");
	if (detailPanel) {
		if (!shouldCollapse) detailPanel.style.display = "";
		detailPanel.style.opacity = shouldCollapse ? "0" : "";
		detailPanel.style.visibility = shouldCollapse ? "hidden" : "";
		detailPanel.style.pointerEvents = shouldCollapse ? "none" : "";
	}
	if (!shouldCollapse && propertyList) {
		if (state.leftListItems.length) {
			syncLeftListItemsFromCache();
			renderList(state.leftListItems);
		} else {
			refreshViewportList();
		}
	}
	updateMapPanelToggleState();
	refreshMapLayout();
	setTimeout(refreshMapLayout, 260);
}

function escapeHtml(str)
{
	return String(str ?? "")
	.replace(/&/g, "&amp;")
	.replace(/</g, "&lt;")
	.replace(/>/g, "&gt;")
	.replace(/"/g, "&quot;")
	.replace(/'/g, "&#39;");
}

function renderExternalListingSourceLink(rawUrl)
{
	const url = String(rawUrl || "").trim();
	if (!url) return "";
	const href = /^https?:\/\//i.test(url) ? url : `https://${url.replace(/^\/+/, "")}`;
	const label = /(?:www\.)?jejuall\.com\/CProperty\//i.test(url)
		? "오일장"
		: (/\.biz\.jejukcr\.com\//i.test(url) ? "교차로" : "");
	if (label) {
		return `<a href="${escapeHtml(href)}" class="detail-desc-source-link" target="_blank" rel="noopener noreferrer"><strong>${label}</strong><span>[바로가기]</span></a>`;
	}
	if (/^https?:\/\//i.test(url)) {
		return `<a href="${escapeHtml(href)}" class="detail-desc-url-link" target="_blank" rel="noopener noreferrer">${escapeHtml(url)}</a>`;
	}
	return escapeHtml(rawUrl);
}

function formatDetailDescriptionLineHtml(line)
{
	const text = String(line || "");
	const urlRegex = /(https?:\/\/[^\s<>"']+|(?:www\.)?jejuall\.com\/CProperty\/[^\s<>"']*|[A-Za-z0-9.-]+\.biz\.jejukcr\.com\/[^\s<>"']*)/gi;
	let html = "";
	let lastIndex = 0;
	let match = null;
	while ((match = urlRegex.exec(text)) !== null) {
		const rawMatch = match[0] || "";
		const url = rawMatch.replace(/[),.;:]+$/g, "");
		const suffix = rawMatch.slice(url.length);
		html += escapeHtml(text.slice(lastIndex, match.index));
		html += renderExternalListingSourceLink(url);
		html += escapeHtml(suffix);
		lastIndex = match.index + rawMatch.length;
	}
	html += escapeHtml(text.slice(lastIndex));
	return html;
}

function formatDetailDescriptionHtml(text)
{
	return String(text || "")
	.replace(/^(?:[ \t]*\r?\n)+/, "")
	.replace(/(?:\r?\n[ \t]*)+$/, "")
	.split(/\r?\n/)
	.map((line) => {
		const safeLine = formatDetailDescriptionLineHtml(line);
		return /^\s*✅/.test(line) ? `<span class="detail-desc-check-heading">${safeLine}</span>` : safeLine;
	})
	.join("<br>");
}

let daumPostcodeLoadPromise = null;
let supabaseScriptLoadPromise = null;

function loadDaumPostcodeScript()
{
	if (window.daum && window.daum.Postcode) {
		return Promise.resolve(window.daum.Postcode);
	}

	if (daumPostcodeLoadPromise) {
		return daumPostcodeLoadPromise;
	}

	daumPostcodeLoadPromise = new Promise((resolve, reject) => {
		const existingScript = document.querySelector('script[data-realjeju-postcode="true"]');
		if (existingScript) {
			existingScript.addEventListener("load", () => {
				if (window.daum && window.daum.Postcode) {
					resolve(window.daum.Postcode);
					return;
				}
				reject(new Error("주소 검색 스크립트가 준비되지 않았습니다."));
			}, { once: true });
			existingScript.addEventListener("error", () => {
				reject(new Error("주소 검색 스크립트를 불러오지 못했습니다."));
			}, { once: true });
			return;
		}

		const script = document.createElement("script");
		script.src = "https://t1.daumcdn.net/mapjsapi/bundle/postcode/prod/postcode.v2.js";
		script.async = true;
		script.dataset.realjejuPostcode = "true";
		script.addEventListener("load", () => {
			if (window.daum && window.daum.Postcode) {
				resolve(window.daum.Postcode);
				return;
			}
			reject(new Error("주소 검색 스크립트가 준비되지 않았습니다."));
		}, { once: true });
		script.addEventListener("error", () => {
			reject(new Error("주소 검색 스크립트를 불러오지 못했습니다."));
		}, { once: true });
		document.head.appendChild(script);
	});

	return daumPostcodeLoadPromise;
}

function loadExternalStylesheet(href, key)
{
	if (!href || document.querySelector(`link[data-realjeju-style="${key}"]`)) return;
	const link = document.createElement("link");
	link.rel = "stylesheet";
	link.href = href;
	link.dataset.realjejuStyle = key;
	document.head.appendChild(link);
}

function loadNonBlockingExternalAssets()
{
	loadExternalStylesheet("https://cdn.jsdelivr.net/gh/orioncactus/pretendard/dist/web/static/pretendard.css", "pretendard");
	loadExternalStylesheet("https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css", "fontawesome");
}

function scheduleNonBlockingExternalAssets()
{
	if (document.readyState === "complete") {
		loadNonBlockingExternalAssets();
		return;
	}
	window.addEventListener("load", loadNonBlockingExternalAssets, { once: true });
}

function loadSupabaseScript()
{
	if (window.supabase && typeof window.supabase.createClient === "function") {
		return Promise.resolve(window.supabase);
	}

	if (supabaseScriptLoadPromise) {
		return supabaseScriptLoadPromise;
	}

	supabaseScriptLoadPromise = new Promise((resolve, reject) => {
		const existingScript = document.querySelector('script[data-realjeju-supabase="true"]');
		if (existingScript) {
			existingScript.addEventListener("load", () => {
				if (window.supabase && typeof window.supabase.createClient === "function") {
					resolve(window.supabase);
					return;
				}
				reject(new Error("Supabase 스크립트가 준비되지 않았습니다."));
			}, { once: true });
			existingScript.addEventListener("error", () => {
				reject(new Error("Supabase 스크립트를 불러오지 못했습니다."));
			}, { once: true });
			return;
		}

		const script = document.createElement("script");
		script.src = "https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2";
		script.async = true;
		script.dataset.realjejuSupabase = "true";
		script.addEventListener("load", () => {
			if (window.supabase && typeof window.supabase.createClient === "function") {
				resolve(window.supabase);
				return;
			}
			reject(new Error("Supabase 스크립트가 준비되지 않았습니다."));
		}, { once: true });
		script.addEventListener("error", () => {
			reject(new Error("Supabase 스크립트를 불러오지 못했습니다."));
		}, { once: true });
		document.head.appendChild(script);
	});

	return supabaseScriptLoadPromise;
}

function scheduleSupabaseScriptLoad()
{
	const run = () => {
		loadSupabaseScript()
		.then(() => {
			if (typeof window.realjejuInitAccountUI === "function") {
				window.realjejuInitAccountUI();
			}
		})
		.catch(err => {
			console.warn("Supabase 스크립트 로드 실패:", err);
		});
	};

	if (document.readyState === "complete") {
		run();
		return;
	}
	window.addEventListener("load", run, { once: true });
}


function normalizeImageArray(item)
{
	if (Array.isArray(item.images) && item.images.length) {
		return item.images.filter(Boolean);
	}
	if (item.image) return [item.image];
	return [];
}

const FEATURE_ALIAS_MAP = {
	"주차 가능": ["주차 가능", "주차가능", "주차", "parking"],
	"반려동물": ["반려동물", "반려동물 가능", "애완동물 가능"],
	"도시가스": ["도시가스", "lng"],
	"복층형": ["복층형", "복층", "duplex"],
	"베란다": ["베란다", "발코니", "balcony", "테라스", "veranda"],
	"엘리베이터": ["엘리베이터", "승강기", "elevator", "lift"],
	"풀옵션": ["풀옵션", "풀 옵션", "full option", "옵션 완비", "가전 가구 완비"],
	"즉시입주": ["즉시입주", "즉시 입주", "바로 입주", "즉시 가능"],
	"협의입주": ["협의입주", "협의 입주", "입주 협의", "입주협의", "협의 가능"],
	"오션뷰": ["오션뷰", "오션 뷰", "바다뷰", "바다전망", "바다조망", "ocean view", "sea view"]
};

function normalizeFeatureToken(value)
{
	return String(value || "")
	.trim()
	.toLowerCase()
	.replace(/\s+/g, " ");
}

function normalizeFeatureList(features)
{
	const rawList = Array.isArray(features) ? features : [];
	const normalized = new Set();
	rawList.forEach(feature => {
		const token = normalizeFeatureToken(feature);
		if (!token) return;
		normalized.add(token);
	});

	Object.entries(FEATURE_ALIAS_MAP).forEach(([label, aliases]) => {
		const aliasTokens = [label, ...(aliases || [])].map(normalizeFeatureToken).filter(Boolean);
		if (aliasTokens.some(token => normalized.has(token))) {
			aliasTokens.forEach(token => normalized.add(token));
			normalized.add(normalizeFeatureToken(label));
		}
	});

	return [...normalized];
}

function hasFeatureLabel(item, label)
{
	const aliasTokens = [label, ...((FEATURE_ALIAS_MAP[label] || []))]
	.map(normalizeFeatureToken)
	.filter(Boolean);
	const featureTokens = Array.isArray(item?.featuresNormalized)
	? item.featuresNormalized
	: normalizeFeatureList(item?.features);
	const tokenSet = new Set(featureTokens);

	return aliasTokens.some(token => tokenSet.has(token));
}

function normalizeProperty(item, index)
{
	const normalizedFeatures = normalizeFeatureList(item.features);
	return {
		id: item.id ?? index + 1,
		userId: item.userId ?? item.user_id ?? "",
		agencyId: item.agencyId ?? item.agency_id ?? "",
		title: item.title ?? "제목 없음",
		listingNo: normalizePropertyListingNoCandidate(item.listingNo),
		dealType: item.dealFilter ?? item.dealType ?? "매매",
		dealTypes: Array.isArray(item.dealTypes) ? item.dealTypes : (Array.isArray(item.deal_types) ? item.deal_types : []),
		type: item.typeFilter ?? item.type ?? "",
		features: Array.isArray(item.features) ? item.features : [],
		featuresNormalized: normalizedFeatures,
		price: item.price ?? "-",
		markerPrice: item.markerPrice ?? "",
		filterPriceManwon: item.filterPriceManwon ?? null,
		area: item.area ?? "-",
		address: item.address ?? "-",
		fullAddress: item.fullAddress ?? item.address1 ?? "",
		addressIsShortened: !!(item.addressIsShortened ?? item.hideDetailAddress ?? item.hide_detail_jibun),
		region: item.region ?? "",
		desc: item.desc ?? "",
		lat: Number(item.lat),
		lng: Number(item.lng),
		image: item.image ?? "",
		images: normalizeImageArray(item),
		link: item.link ?? "#",
		agent_folder: item.agent_folder ?? "",
		agentName: item.agentName ?? "",
		agentTitle: item.agentTitle ?? "",
		agentOffice: item.agentOffice ?? "",
		agentAddress: item.agentAddress ?? "",
		agentRegNo: item.agentRegNo ?? "",
		agentImage: item.agentImage ?? "",
		buildingName: item.buildingName ?? item.complexName ?? "",
		phone1: item.phone1 ?? "",
		phone2: item.phone2 ?? "",
		linkKakaotalk: item.linkKakaotalk ?? item.kakao_url ?? item.kakaoUrl ?? item.kakao ?? item.kakao_open_chat ?? item.kakao_open_chat_url ?? item.open_chat_url ?? "",
		linkCrossroad: item.linkCrossroad ?? "",
		date: item.date ?? "",
		dateLabel: item.dateLabel ?? "",
		desc_folder: item.desc_folder ?? "",
		image_folder: item.image_folder ?? "",
		infoRows: Array.isArray(item.infoRows) ? item.infoRows : [],
		sections: Array.isArray(item.sections) ? item.sections : [],
		payload: item.payload && typeof item.payload === "object" ? item.payload : null,
		locationDisplayType: item.locationDisplayType ?? item.location_display_type ?? "marker",
		locationBounds: item.locationBounds ?? item.location_bounds ?? null,
		dealMethod: item.dealMethod ?? item.listingMethod ?? "",
		brokerStatus: item.brokerStatus ?? "",
		floors: item.floors && typeof item.floors === "object" ? item.floors : {},
		maintenance: item.maintenance && typeof item.maintenance === "object" ? item.maintenance : {}
	};
}


function parseAreaNumbers(areaText)
{
	const text = String(areaText || "")
		.replace(/&sup2;|&#178;|&#xB2;/gi, "²")
		.replace(/<\s*sup\s*>\s*2\s*<\s*\/\s*sup\s*>/gi, "2")
		.replace(/<[^>]*>/g, " ")
		.trim();
	return [...text.matchAll(/([\d,.]+)\s*(m²|㎡|m\s*2|평)/gi)].map(match => {
		const value = Number(String(match[1]).replace(/,/g, ""));
		if (!Number.isFinite(value)) return null;
		return String(match[2]).toLowerCase() === "평" ? value * 3.3058 : value;
	}).filter(v => v !== null);
}

function isApartmentType(typeText)
{
	const text = String(typeText || "").trim();
	return /아파트|빌라|연립|투룸/.test(text);
}

function isHotelType(typeText)
{
	const text = String(typeText || "").trim().toLowerCase();
	return text === "hotel" || text === "호텔";
}

	function isPensionType(typeText)
	{
		const text = String(typeText || "").trim().toLowerCase();
		return text === "pension" || text === "펜션";
	}

	function isLivingAccommodationType(typeText)
	{
		const text = String(typeText || "").trim().toLowerCase();
		return text === "living_accommodation"
			|| text === "생활형숙박시설"
			|| text === "생활숙박시설"
			|| text === "생활형숙박"
			|| text === "레지던스";
	}

	function isHotelPensionType(typeText)
	{
		return isHotelType(typeText) || isPensionType(typeText);
	}

function isDetachedHouseType(typeText)
{
	const text = String(typeText || "").trim();
	return ["단독", "단독주택"].includes(text);
}

function isMultiFamilyHouseType(typeText)
{
	const text = String(typeText || "").trim();
	return ["다가구", "다가구주택"].includes(text);
}

function isLandSubtypeType(typeText)
{
	const text = String(typeText || "").trim();
	return ["전", "대", "답", "과수원", "목장용지"].includes(text);
}

function getCardTypeBadgeLabel(typeText)
{
	const text = String(typeText || "").trim();
	if (isLandSubtypeType(text)) return "토지";
	return text || "-";
}

function getListCardLandTypeValue(item)
{
	const rawType = String(item && (item.type || item.typeFilter || "") || "").trim();
	const subtypeValues = new Set(["전", "대", "답", "과수원", "목장용지", "임야"]);
	if (subtypeValues.has(rawType)) return rawType;
	if (typeof getItemLandTypeTokens === "function") {
		const tokens = Array.from(getItemLandTypeTokens(item));
		if (tokens.length) return tokens[0];
	}
	return "";
}

function getListCardTypeBadgeLabel(item)
{
	const rawType = String(item && (item.type || item.typeFilter || "") || "").trim();
	const baseLabel = getCardTypeBadgeLabel(rawType || "-");
	const landType = getListCardLandTypeValue(item);
	const isLandType = baseLabel === "토지"
		|| rawType === "토지"
		|| rawType === "토지ㆍ임야"
		|| rawType === "임야"
		|| isLandSubtypeType(rawType);
	if (isLandType && landType) return `토지(${landType})`;
	if (rawType === "임야") return "토지(임야)";
	return baseLabel;
}

function getDisplayTypeLabel(typeText)
{
	const text = String(typeText || "").trim();
	if (["전", "대", "답", "과수원", "목장용지", "임야", "토지", "토지ㆍ임야"].includes(text)) return getLandTypeDetailLabel(text);
	if (["다가구", "다가구주택"].includes(text)) return "다가구주택";
	if (["단독", "단독주택"].includes(text)) return "단독주택";
	if (text === "연립") return "빌라";
	if (isLivingAccommodationType(text)) return "생활형숙박시설";
	if (isHotelType(text)) return "호텔";
	if (isPensionType(text)) return "펜션";
	return text || "-";
}

function getSummaryTypeBadgeLabel(typeText)
{
	const label = getDisplayTypeLabel(typeText);
	return label.startsWith("토지(") ? "토지" : label;
}

function isCommercialType(typeText)
{
	const text = String(typeText || "").trim();
	return ["상가", "상가건물", "사무실", "공장", "상가ㆍ사무실"].includes(text);
}

function parseAreaValueWithUnit(valueText, unitText = "")
{
	const value = Number(String(valueText ?? "").replace(/,/g, ""));
	if (!Number.isFinite(value)) return null;
	return /평/.test(String(unitText || "")) ? value * 3.3058 : value;
}

function getAreaUnitFromMatchedText(text)
{
	const matched = String(text || "").match(/(㎡|m²|m\s*2|평)/i);
	return matched ? matched[1] : "";
}

function parseDetachedHouseAreas(areaText)
{
	const raw = String(areaText || "-").trim();
	const landMatch = raw.match(/대지\s*(?:면적)?\s*([\d,.]+)\s*(㎡|m²|m\s*2|평)?/i);
	const totalMatch = raw.match(/연\s*(?:면적)?\s*([\d,.]+)\s*(㎡|m²|m\s*2|평)?/i);

	const land = landMatch ? parseAreaValueWithUnit(landMatch[1], landMatch[2] || getAreaUnitFromMatchedText(landMatch[0])) : null;
	const total = totalMatch ? parseAreaValueWithUnit(totalMatch[1], totalMatch[2] || getAreaUnitFromMatchedText(totalMatch[0])) : null;

	return { raw, land, total };
}

function parseApartmentAreas(areaText)
{
	const raw = String(areaText || "-").trim();
	const labelMatch = raw.match(/(공급|계약)(?:면적)?\s*[\d,.]+(?:\s*(?:㎡|m²|m\s*2|평))?/i);
	const areaLabel = labelMatch && labelMatch[1] === "계약" ? "계약" : "공급";
	const supplyMatch = raw.match(/(?:공급|계약)(?:면적)?\s*([\d,.]+)\s*(㎡|m²|m\s*2|평)?/i);
	const privateMatch = raw.match(/전용(?:면적)?\s*([\d,.]+)\s*(㎡|m²|m\s*2|평)?/i);

	let supply = supplyMatch ? parseAreaValueWithUnit(supplyMatch[1], supplyMatch[2] || getAreaUnitFromMatchedText(supplyMatch[0])) : null;
	let privateArea = privateMatch ? parseAreaValueWithUnit(privateMatch[1], privateMatch[2] || getAreaUnitFromMatchedText(privateMatch[0])) : null;

	if (!Number.isFinite(supply) || !Number.isFinite(privateArea)) {
		const values = parseAreaNumbers(raw);
		if (!Number.isFinite(supply) && values.length >= 1) supply = values[0];
		if (!Number.isFinite(privateArea) && values.length >= 2) privateArea = values[1];
	}

	return { raw, supply, private: privateArea, areaLabel };
}

function formatDetachedHouseAreaDisplay(areaText, unit = "m2")
{
	const { raw, total } = parseDetachedHouseAreas(areaText);

	if (Number.isFinite(total)) {
		return `${formatSingleAreaValue(total, unit)}`;
	}

	return escapeHtml(raw);
}

function formatDetachedHouseCardAreaDisplay(areaText, unit)
{
	const { raw, land, total } = parseDetachedHouseAreas(areaText);

	if (Number.isFinite(land) && Number.isFinite(total)) {
		return `대지${formatSingleAreaValue(land, unit)}ㆍ연${formatSingleAreaValue(total, unit)}`;
	}

	return escapeHtml(raw);
}

function formatSingleAreaValue(value, unit)
{
	if (!Number.isFinite(value)) return "-";
	if (unit === "py") {
		return `${(value / 3.3058).toLocaleString("ko-KR", { maximumFractionDigits: 1 })}평`;
	}
	return `${value.toLocaleString("ko-KR", { maximumFractionDigits: 2 })}㎡`;
}

const AREA_FILTER_MAX_M2 = 165;
const AREA_FILTER_MAX_PY = AREA_FILTER_MAX_M2 / 3.3058;
const AREA_FILTER_LAND_MAX_M2 = AREA_FILTER_MAX_M2 * 10;
const AREA_FILTER_LAND_MAX_PY = 500;
const AREA_FILTER_UNBOUNDED_MAX_M2 = 999999;
const AREA_FILTER_MAX_EDGE_EPSILON_M2 = 0.1;

function getAreaFilterMaxM2()
{
	return selectedAreaLandOnly ? AREA_FILTER_LAND_MAX_M2 : AREA_FILTER_MAX_M2;
}

function isAreaFilterMaxUnbounded(value = selectedAreaMaxM2)
{
	return Number.isFinite(value)
		&& (value >= AREA_FILTER_UNBOUNDED_MAX_M2 || value >= getAreaFilterMaxM2() - AREA_FILTER_MAX_EDGE_EPSILON_M2);
}

function areaFilterToM2(value, unit = selectedAreaUnit)
{
	const number = Number(value);
	if (!Number.isFinite(number)) return null;
	return unit === "py" ? number * 3.3058 : number;
}

function areaFilterFromM2(value, unit = selectedAreaUnit)
{
	const number = Number(value);
	if (!Number.isFinite(number)) return null;
	return unit === "py" ? number / 3.3058 : number;
}

function getAreaFilterUnitMax(unit = selectedAreaUnit)
{
	if (selectedAreaLandOnly) return unit === "py" ? AREA_FILTER_LAND_MAX_PY : AREA_FILTER_LAND_MAX_M2;
	return unit === "py" ? AREA_FILTER_MAX_PY : AREA_FILTER_MAX_M2;
}

function getAreaFilterModeKey()
{
	return selectedAreaLandOnly ? "land" : "exclusive";
}

function saveCurrentAreaFilterRange(mode = getAreaFilterModeKey())
{
	const key = mode === "land" ? "land" : "exclusive";
	selectedAreaRangeByMode[key] = {
		minM2: Number.isFinite(selectedAreaMinM2) ? selectedAreaMinM2 : null,
		maxM2: selectedAreaMaxTouched && Number.isFinite(selectedAreaMaxM2) ? selectedAreaMaxM2 : AREA_FILTER_UNBOUNDED_MAX_M2,
		maxTouched: !!selectedAreaMaxTouched
	};
}

function loadAreaFilterRange(mode = getAreaFilterModeKey())
{
	const key = mode === "land" ? "land" : "exclusive";
	const range = selectedAreaRangeByMode[key] || {};
	selectedAreaMinM2 = Number.isFinite(range.minM2) ? range.minM2 : null;
	selectedAreaMaxTouched = !!range.maxTouched;
	selectedAreaMaxM2 = selectedAreaMaxTouched && Number.isFinite(range.maxM2) ? range.maxM2 : AREA_FILTER_UNBOUNDED_MAX_M2;
}

function switchAreaFilterMode(mode)
{
	const nextMode = mode === "land" ? "land" : "exclusive";
	const currentMode = getAreaFilterModeKey();
	saveCurrentAreaFilterRange(currentMode);
	selectedAreaLandOnly = nextMode === "land";
	selectedAreaExclusiveOnly = nextMode !== "land";
	loadAreaFilterRange(nextMode);
}

function resetAreaFilterRanges()
{
	selectedAreaRangeByMode.exclusive = { minM2: null, maxM2: AREA_FILTER_UNBOUNDED_MAX_M2, maxTouched: false };
	selectedAreaRangeByMode.land = { minM2: null, maxM2: AREA_FILTER_UNBOUNDED_MAX_M2, maxTouched: false };
	selectedAreaExclusiveOnly = true;
	selectedAreaLandOnly = false;
	loadAreaFilterRange("exclusive");
}

function formatAreaFilterNumber(value, unit = selectedAreaUnit)
{
	const number = Number(value);
	if (!Number.isFinite(number)) return "";
	return Math.round(number).toLocaleString("ko-KR");
}

function formatAreaFilterLabelFromM2(value, unit = selectedAreaUnit)
{
	const converted = areaFilterFromM2(value, unit);
	if (!Number.isFinite(converted)) return "";
	return `${formatAreaFilterNumber(converted, unit)}${unit === "py" ? "평" : "㎡"}`;
}

function getAreaFilterRangeLabel(fallback = "면적")
{
	const hasMin = Number.isFinite(selectedAreaMinM2);
	const hasMax = selectedAreaMaxTouched && Number.isFinite(selectedAreaMaxM2) && !isAreaFilterMaxUnbounded();
	if (!hasMin && !hasMax) return fallback;
	const prefix = selectedAreaExclusiveOnly && !selectedAreaLandOnly ? "전용 " : "";
	if (hasMin && hasMax) {
		return `${prefix}${formatAreaFilterLabelFromM2(selectedAreaMinM2)}~${formatAreaFilterLabelFromM2(selectedAreaMaxM2)}`;
	}
	if (hasMin) return `${prefix}${formatAreaFilterLabelFromM2(selectedAreaMinM2)} 이상`;
	return `${prefix}${formatAreaFilterLabelFromM2(selectedAreaMaxM2)} 이하`;
}

function getFiniteAreaNumber(value)
{
	const number = Number(String(value ?? "").replace(/,/g, ""));
	return Number.isFinite(number) && number > 0 ? number : null;
}

function getFirstFiniteAreaNumber(values)
{
	for (const value of values) {
		const number = getFiniteAreaNumber(value);
		if (Number.isFinite(number)) return number;
	}
	return null;
}

function pushFiniteAreaNumber(target, value, unit = "m2")
{
	const number = getFiniteAreaNumber(value);
	if (!Number.isFinite(number)) return;
	target.push(unit === "py" ? number * 3.3058 : number);
}

function pushAreaTextValues(target, value)
{
	parseAreaNumbers(value).forEach((area) => pushFiniteAreaNumber(target, area));
}

function collectAreaTextCandidates(value, target)
{
	if (value === null || value === undefined) return;
	if (typeof value === "string" || typeof value === "number") {
		target.push(String(value));
		return;
	}
	if (Array.isArray(value)) {
		value.forEach((entry) => collectAreaTextCandidates(entry, target));
		return;
	}
	if (typeof value !== "object") return;
	["label", "name", "title", "value", "text", "display", "description", "area", "areaText", "m2_text", "py_text", "m2Text", "pyText"].forEach((key) => {
		if (Object.prototype.hasOwnProperty.call(value, key)) collectAreaTextCandidates(value[key], target);
	});
}

function isAreaFilterLandItem(item)
{
	const payload = item?.payload && typeof item.payload === "object" ? item.payload : {};
	const typeText = [
		item?.type,
		item?.propertyType,
		item?.category,
		payload?.type,
		payload?.property_type,
		payload?.category
	].map(value => String(value || "")).join(" ");
	return /\bland\b|토지|임야|대지|과수원|목장용지|(?:^|\s)(?:전|답)(?:\s|$)/i.test(typeText);
}

function getItemAreaFilterValuesM2(item, exclusiveOnly = selectedAreaExclusiveOnly)
{
	if (selectedAreaLandOnly && !isAreaFilterLandItem(item)) return [];
	const values = [];
	const payload = item?.payload && typeof item.payload === "object" ? item.payload : {};
	const areas = payload.areas && typeof payload.areas === "object" ? payload.areas : {};
	const textCandidates = [];

	[
		item?.area,
		item?.areaText,
		item?.displayArea,
		item?.cardArea,
		item?.description,
		item?.desc,
		item?.summary,
		item?.title,
		item?.type,
		item?.payload?.description,
		item?.payload?.desc,
		item?.payload?.title
	].forEach((entry) => collectAreaTextCandidates(entry, textCandidates));
	collectAreaTextCandidates(item?.infoRows, textCandidates);
	collectAreaTextCandidates(item?.sections, textCandidates);
	collectAreaTextCandidates(areas?.area_items, textCandidates);
	collectAreaTextCandidates(payload?.form_state?.areaItems, textCandidates);
	textCandidates.forEach((text) => pushAreaTextValues(values, text));

	const structuredKeys = selectedAreaLandOnly
		? ["land"]
		: exclusiveOnly
		? ["exclusive"]
		: ["supply", "total", "building", "land", "exclusive"];
	structuredKeys.forEach((key) => {
		pushFiniteAreaNumber(values, areas[`${key}_m2`], "m2");
		pushFiniteAreaNumber(values, areas[`${key}_py`], "py");
	});

	const areaItems = [
		...(Array.isArray(areas?.area_items) ? areas.area_items : []),
		...(Array.isArray(payload?.form_state?.areaItems) ? payload.form_state.areaItems : [])
	];
	areaItems.forEach((entry) => {
		if (!entry || typeof entry !== "object") return;
		if (selectedAreaLandOnly && getAreaKeyFromLabel(entry.label) !== "land" && String(entry.key || "") !== "land") return;
		if (!selectedAreaLandOnly && exclusiveOnly && getAreaKeyFromLabel(entry.label) !== "exclusive" && String(entry.key || "") !== "exclusive") return;
		["m2", "m2_value", "value_m2", "area_m2"].forEach((key) => pushFiniteAreaNumber(values, entry[key], "m2"));
		["py", "py_value", "value_py", "area_py"].forEach((key) => pushFiniteAreaNumber(values, entry[key], "py"));
	});

	return [...new Set(values.map((value) => Math.round(value * 10000) / 10000))]
		.filter((value) => Number.isFinite(value) && value > 0);
}

function getItemAreaFilterValueM2(item, exclusiveOnly = selectedAreaExclusiveOnly)
{
	if (selectedAreaLandOnly && !isAreaFilterLandItem(item)) return null;
	const payload = item?.payload && typeof item.payload === "object" ? item.payload : {};
	const areas = payload.areas && typeof payload.areas === "object" ? payload.areas : {};
	const rawArea = item?.area || "";
	const parsedApartment = parseApartmentAreas(rawArea);
	const parsedDetached = parseDetachedHouseAreas(rawArea);
	const cardAreaValue = getFirstFiniteAreaNumber(parseAreaNumbers(rawArea));
	const anyStoredAreaValue = getFirstFiniteAreaNumber([
		areas.supply_m2,
		areas.total_m2,
		areas.building_m2,
		areas.land_m2,
		areas.exclusive_m2,
		Number.isFinite(getFiniteAreaNumber(areas.supply_py)) ? getFiniteAreaNumber(areas.supply_py) * 3.3058 : null,
		Number.isFinite(getFiniteAreaNumber(areas.total_py)) ? getFiniteAreaNumber(areas.total_py) * 3.3058 : null,
		Number.isFinite(getFiniteAreaNumber(areas.building_py)) ? getFiniteAreaNumber(areas.building_py) * 3.3058 : null,
		Number.isFinite(getFiniteAreaNumber(areas.land_py)) ? getFiniteAreaNumber(areas.land_py) * 3.3058 : null,
		Number.isFinite(getFiniteAreaNumber(areas.exclusive_py)) ? getFiniteAreaNumber(areas.exclusive_py) * 3.3058 : null
	]);

	const exclusiveValue = getFirstFiniteAreaNumber([
		areas.exclusive_m2,
		Number.isFinite(getFiniteAreaNumber(areas.exclusive_py)) ? getFiniteAreaNumber(areas.exclusive_py) * 3.3058 : null,
		parsedApartment.private,
		findCardLabeledAreaValue(rawArea, [/전용\s*(?:면적)?\s*([\d,.]+)\s*(?:㎡|평)?/])
	]);
	const landValue = getFirstFiniteAreaNumber([
		areas.land_m2,
		Number.isFinite(getFiniteAreaNumber(areas.land_py)) ? getFiniteAreaNumber(areas.land_py) * 3.3058 : null,
		parsedDetached.land,
		cardAreaValue
	]);

	if (selectedAreaLandOnly) return Number.isFinite(landValue) ? landValue : null;
	if (exclusiveOnly && Number.isFinite(exclusiveValue)) return exclusiveValue;
	if (!exclusiveOnly) {
		if (Number.isFinite(cardAreaValue)) return cardAreaValue;
		if (Number.isFinite(anyStoredAreaValue)) return anyStoredAreaValue;
	}

	const representativeValue = getFirstFiniteAreaNumber([
		cardAreaValue,
		anyStoredAreaValue,
		areas.supply_m2,
		areas.total_m2,
		areas.building_m2,
		areas.land_m2,
		Number.isFinite(getFiniteAreaNumber(areas.supply_py)) ? getFiniteAreaNumber(areas.supply_py) * 3.3058 : null,
		Number.isFinite(parsedApartment.supply) ? parsedApartment.supply : null,
		Number.isFinite(parsedDetached.total) ? parsedDetached.total : null,
		Number.isFinite(parsedDetached.land) ? parsedDetached.land : null,
		getPrimaryAreaForUnitPrice(rawArea, item?.type || "")
	]);

	return Number.isFinite(representativeValue) ? representativeValue : exclusiveValue;
}

function matchesAreaFilter(item)
{
	const hasMaxFilter = selectedAreaMaxTouched && Number.isFinite(selectedAreaMaxM2) && !isAreaFilterMaxUnbounded();
	if (!Number.isFinite(selectedAreaMinM2) && !hasMaxFilter) {
		return selectedAreaLandOnly ? isAreaFilterLandItem(item) : true;
	}
	if (selectedAreaLandOnly && !isAreaFilterLandItem(item)) return false;
	const representativeValue = getItemAreaFilterValueM2(item, selectedAreaExclusiveOnly);
	const values = Number.isFinite(representativeValue)
		? [representativeValue]
		: getItemAreaFilterValuesM2(item, selectedAreaExclusiveOnly);
	return values.some((value) => {
		if (!Number.isFinite(value)) return false;
		if (Number.isFinite(selectedAreaMinM2) && value < selectedAreaMinM2) return false;
		if (hasMaxFilter && value > selectedAreaMaxM2) return false;
		return true;
	});
}

function normalizeLandTypeFilterValue(value)
{
	return String(value || "")
		.replace(/\([^)]*\)/g, "")
		.replace(/\s+/g, "")
		.trim();
}

function addLandTypeCandidateToken(tokens, value, options = {})
{
	const normalized = normalizeLandTypeFilterValue(value);
	if (!normalized) return;
	if (LAND_TYPE_FILTER_VALUE_SET.has(normalized)) {
		tokens.add(normalized);
		return;
	}
	if (options.exactOnly) return;
	LAND_TYPE_FILTER_VALUES.forEach(typeValue => {
		if (typeValue.length <= 1) return;
		if (normalized.includes(typeValue)) tokens.add(typeValue);
	});
}

function getItemLandTypeTokens(item)
{
	const tokens = new Set();
	const payload = item?.payload && typeof item.payload === "object" ? item.payload : {};
	const areas = payload.areas && typeof payload.areas === "object" ? payload.areas : {};
	const land = payload.land && typeof payload.land === "object" ? payload.land : {};
	const formState = payload.form_state && typeof payload.form_state === "object" ? payload.form_state : {};
	const formInputs = formState.inputs && typeof formState.inputs === "object" ? formState.inputs : {};
	const directCandidates = [
		item?.landType,
		item?.land_type,
		item?.landTypeLabel,
		item?.land_type_label,
		areas.land_type,
		areas.landType,
		land.land_type,
		land.landType,
		payload.land_type,
		payload.landType,
		payload.land_type_label,
		payload.landTypeLabel,
		formInputs.land_type,
		formInputs.landType,
		formInputs.landTypeSelect
	];
	directCandidates.forEach(value => addLandTypeCandidateToken(tokens, value));
	[
		item?.type,
		item?.typeFilter,
		item?.propertyType,
		item?.property_type,
		payload.type,
		payload.property_type,
		payload.propertyType
	].forEach(value => addLandTypeCandidateToken(tokens, value, { exactOnly: true }));
	return tokens;
}

function matchesLandTypeFilter(item, selectedValues)
{
	if (!(selectedValues instanceof Set) || selectedValues.size === 0) return true;
	const tokens = getItemLandTypeTokens(item);
	if (!tokens.size) return false;
	return Array.from(selectedValues).some(value => tokens.has(normalizeLandTypeFilterValue(value)));
}

function normalizeLandUseZoneFilterValue(value)
{
	return String(value || "")
		.replace(/\s+/g, "")
		.trim();
}

function addLandUseZoneCandidateToken(tokens, value)
{
	const normalized = normalizeLandUseZoneFilterValue(value);
	if (!normalized) return;
	const exactValue = LAND_USE_ZONE_FILTER_NORMALIZED_TO_VALUE.get(normalized);
	if (exactValue) {
		tokens.add(exactValue);
		return;
	}
	LAND_USE_ZONE_FILTER_VALUES.forEach(zoneValue => {
		const zoneNormalized = normalizeLandUseZoneFilterValue(zoneValue);
		if (zoneNormalized && normalized.includes(zoneNormalized)) tokens.add(zoneValue);
	});
}

function getItemLandUseZoneTokens(item)
{
	const tokens = new Set();
	const payload = item?.payload && typeof item.payload === "object" ? item.payload : {};
	const areas = payload.areas && typeof payload.areas === "object" ? payload.areas : {};
	const land = payload.land && typeof payload.land === "object" ? payload.land : {};
	const formState = payload.form_state && typeof payload.form_state === "object" ? payload.form_state : {};
	const formInputs = formState.inputs && typeof formState.inputs === "object" ? formState.inputs : {};
	[
		item?.landUseZone,
		item?.land_use_zone,
		item?.landUseZoneLabel,
		item?.land_use_zone_label,
		areas.land_use_zone,
		areas.landUseZone,
		land.land_use_zone,
		land.landUseZone,
		payload.land_use_zone,
		payload.landUseZone,
		payload.land_use_zone_label,
		payload.landUseZoneLabel,
		formInputs.land_use_zone,
		formInputs.landUseZone,
		formInputs.landUseZoneSelect
	].forEach(value => addLandUseZoneCandidateToken(tokens, value));
	return tokens;
}

function matchesLandUseZoneFilter(item, selectedValues)
{
	if (!(selectedValues instanceof Set) || selectedValues.size === 0) return true;
	const tokens = getItemLandUseZoneTokens(item);
	if (!tokens.size) return false;
	return Array.from(selectedValues).some(value => tokens.has(value));
}

const APPROVAL_YEAR_FILTER_MAX_AGE = 25;
const FILTER_RANGE_THUMB_GAP_PX = 29;

function parseApprovalDateValue(value)
{
	const raw = String(value || "").trim();
	if (!raw) return null;
	const match = raw.match(/^(\d{4})(?:[-./년\s]*(\d{1,2})?)?(?:[-./월\s]*(\d{1,2})?)?/);
	if (match) {
		const year = Number(match[1]);
		const month = match[2] ? Number(match[2]) : 1;
		const day = match[3] ? Number(match[3]) : 1;
		if (Number.isFinite(year) && year >= 1900) {
			const date = new Date(year, Math.max(0, month - 1), Math.max(1, day));
			return Number.isNaN(date.getTime()) ? null : date;
		}
	}
	const date = new Date(raw);
	return Number.isNaN(date.getTime()) ? null : date;
}

function getApprovalAgeYearsFromDate(date, now = new Date())
{
	if (!(date instanceof Date) || Number.isNaN(date.getTime())) return null;
	const today = now instanceof Date && !Number.isNaN(now.getTime()) ? now : new Date();
	let age = today.getFullYear() - date.getFullYear();
	const beforeAnniversary = today.getMonth() < date.getMonth()
		|| (today.getMonth() === date.getMonth() && today.getDate() < date.getDate());
	if (beforeAnniversary) age -= 1;
	return Math.max(0, age);
}

function getItemApprovalDateValue(item)
{
	const payload = item?.payload && typeof item.payload === "object" ? item.payload : {};
	const building = payload.building && typeof payload.building === "object" ? payload.building : {};
	const formInputs = payload.form_state && payload.form_state.inputs && typeof payload.form_state.inputs === "object"
		? payload.form_state.inputs
		: {};
	return [
		building.approval_date,
		building.approvalDate,
		building.approvalDateInput,
		payload.approval_date,
		payload.approvalDate,
		payload.propertyApprovalDate,
		payload.propertyApprovalDateInput,
		formInputs.propertyApprovalDateInput,
		formInputs.approvalDate,
		formInputs.approval_date,
		item?.approval_date,
		item?.approvalDate,
		item?.propertyApprovalDate
	].map(value => String(value || "").trim()).find(Boolean) || "";
}

function getItemApprovalAgeYears(item)
{
	const dateValue = getItemApprovalDateValue(item);
	return getApprovalAgeYearsFromDate(parseApprovalDateValue(dateValue));
}

function matchesApprovalYearFilter(item)
{
	if (!Number.isFinite(selectedApprovalYearMinAge) && !Number.isFinite(selectedApprovalYearMaxAge)) return true;
	const age = getItemApprovalAgeYears(item);
	if (!Number.isFinite(age)) return false;
	if (Number.isFinite(selectedApprovalYearMinAge) && age < selectedApprovalYearMinAge) return false;
	if (Number.isFinite(selectedApprovalYearMaxAge) && age > selectedApprovalYearMaxAge) return false;
	return true;
}

function formatCardAreaPair(label, firstText, privateText)
{
	const safeLabel = escapeHtml(label || "공급");
	const safeFirst = escapeHtml(firstText || "-");
	const safePrivate = escapeHtml(privateText || "-");
	return `<span class="area-label">${safeLabel}</span><span class="area-value">${safeFirst}</span><span class="area-separator">ㆍ</span><span class="area-label">전용</span><span class="area-value">${safePrivate}</span>`;
}

function findCardLabeledAreaValue(raw, patterns)
{
	for (const pattern of patterns) {
		const match = String(raw || "").match(pattern);
		if (!match) continue;
		const value = parseAreaValueWithUnit(match[1], match[2] || getAreaUnitFromMatchedText(match[0]));
		if (Number.isFinite(value)) return value;
	}
	return null;
}

function formatRepresentativeCardAreaByUnit(areaText, unit)
{
	const raw = String(areaText || "-").trim();
	const exclusiveValue = findCardLabeledAreaValue(raw, [
		/전용\s*(?:면적)?\s*([\d,.]+)\s*(?:㎡|평)?/
	]);
	if (Number.isFinite(exclusiveValue)) return formatSingleAreaValue(exclusiveValue, unit);

	const values = parseAreaNumbers(raw);
	if (values.length === 1) return formatSingleAreaValue(values[0], unit);

	const totalValue = findCardLabeledAreaValue(raw, [
		/연\s*면적\s*([\d,.]+)\s*(?:㎡|평)?/,
		/연면적\s*([\d,.]+)\s*(?:㎡|평)?/,
		/\(연\)\s*([\d,.]+)\s*(?:㎡|평)?/,
		/연\s*([\d,.]+)\s*(?:㎡|평)?/
	]);
	if (Number.isFinite(totalValue)) return formatSingleAreaValue(totalValue, unit);

	return values.length ? formatSingleAreaValue(values[0], unit) : escapeHtml(raw);
}

function formatAreaByUnit(areaText, unit, typeText = "")
{
	const raw = String(areaText || "-").trim();
	const values = parseAreaNumbers(raw);

	if (isDetachedHouseType(typeText)) {
		return formatDetachedHouseAreaDisplay(raw, unit);
	}

	if (isApartmentType(typeText) && values.length >= 2) {
		const privateArea = formatSingleAreaValue(values[1], unit);
		return privateArea;
	}

	if (values.length >= 1) {
		return formatSingleAreaValue(values[0], unit);
	}

	return escapeHtml(raw);
}

function getPrimaryAreaForUnitPrice(areaText, typeText = "")
{
	const raw = String(areaText || "-").trim();

	if (isDetachedHouseType(typeText)) {
		const { total } = parseDetachedHouseAreas(raw);
		return Number.isFinite(total) ? total : null;
	}

	if (isApartmentType(typeText) || isHotelPensionType(typeText)) {
		const { private: privateArea } = parseApartmentAreas(raw);
		return Number.isFinite(privateArea) ? privateArea : null;
	}

	const values = parseAreaNumbers(raw);
	return values.length >= 1 && Number.isFinite(values[0]) ? values[0] : null;
}

function parsePriceTextToWon(priceText)
{
	const raw = String(priceText || "").replace(/\s+/g, "");
	if (!raw || raw === "-") return null;

	let totalWon = 0;

	const eokMatch = raw.match(/([\d,.]+)억/);
	if (eokMatch) {
		totalWon += Number(String(eokMatch[1]).replace(/,/g, "")) * 100000000;
	}

	const manwonMatch = raw.match(/억([\d,]+)/) || (!eokMatch ? raw.match(/^([\d,]+)$/) : null);
	if (manwonMatch) {
		totalWon += Number(String(manwonMatch[1]).replace(/,/g, "")) * 10000;
	}

	if (!eokMatch && /만원/.test(raw)) {
		const onlyManwon = raw.match(/([\d,]+)만원/);
		if (onlyManwon) {
			totalWon += Number(String(onlyManwon[1]).replace(/,/g, "")) * 10000;
		}
	}

	return Number.isFinite(totalWon) && totalWon > 0 ? totalWon : null;
}

function formatUnitPriceLine(detailItem)
{
	const totalWon = parsePriceTextToWon(detailItem?.price || "");
	const areaM2 = getPrimaryAreaForUnitPrice(detailItem?.area || "", detailItem?.type || "");

	if (!Number.isFinite(totalWon) || !Number.isFinite(areaM2) || areaM2 <= 0) return "";

	const manwonPerM2 = Math.round((totalWon / areaM2) / 10000);
	const manwonPerPyeong = Math.round(((totalWon / areaM2) * 3.3058) / 10000);

	if (globalAreaUnit === "py") {
		return `단위 가격 ${manwonPerPyeong.toLocaleString('ko-KR')}만원/평`;
	}

	return `단위 가격 ${manwonPerM2.toLocaleString('ko-KR')}만원/㎡`;
}

function formatCardAreaByUnit(areaText, unit, typeText = "")
{
	return formatRepresentativeCardAreaByUnit(areaText, unit);

	const rawAreaText = String(areaText || "-").trim();
	const landTotalAreas = parseDetachedHouseAreas(rawAreaText);
	const labeledApartmentAreas = parseApartmentAreas(rawAreaText);
	const primaryAreaLabel = labeledApartmentAreas.areaLabel || (/오피스텔|호텔|펜션/.test(typeText) ? "계약" : "공급");

	if (!/계약|전용/.test(rawAreaText) && Number.isFinite(landTotalAreas.land) && Number.isFinite(landTotalAreas.total)) {
		return `대지${formatSingleAreaValue(landTotalAreas.land, unit)}ㆍ연${formatSingleAreaValue(landTotalAreas.total, unit)}`;
	}

	if (/공급|계약|전용/.test(rawAreaText) && Number.isFinite(labeledApartmentAreas.supply) && Number.isFinite(labeledApartmentAreas.private)) {
		const privateText = formatSingleAreaValue(labeledApartmentAreas.private, unit);
		const supplyText = formatSingleAreaValue(labeledApartmentAreas.supply, unit);
		return formatCardAreaPair(primaryAreaLabel, supplyText, privateText);
	}

	if (isDetachedHouseType(typeText)) {
		return formatDetachedHouseCardAreaDisplay(areaText, unit);
	}

	if (isHotelPensionType(typeText)) {
		const parsed = parseApartmentAreas(areaText || "-");
		const privateText = Number.isFinite(parsed.private) ? formatSingleAreaValue(parsed.private, unit) : "-";
		const supplyText = Number.isFinite(parsed.supply) ? formatSingleAreaValue(parsed.supply, unit) : "-";
		return formatCardAreaPair("계약", supplyText, privateText);
	}

	if (/상가|상가건물|사무실|공장/.test(typeText)) {
		const raw = String(areaText || "-").trim();

		if (/계약|전용/.test(raw)) {
			const parsed = parseApartmentAreas(raw);
			const privateText = Number.isFinite(parsed.private) ? formatSingleAreaValue(parsed.private, unit) : "-";
			const supplyText = Number.isFinite(parsed.supply) ? formatSingleAreaValue(parsed.supply, unit) : "-";
			return formatCardAreaPair(parsed.areaLabel || "계약", supplyText, privateText);
		}

		const totalMatch =
		raw.match(/연면적\s*([\d,.]+)㎡/) ||
		raw.match(/연면적\s*([\d,.]+)평/) ||
		raw.match(/\(연\)\s*([\d,.]+)㎡/) ||
		raw.match(/\(연\)\s*([\d,.]+)평/) ||
		raw.match(/연\s*([\d,.]+)㎡/) ||
		raw.match(/연\s*([\d,.]+)평/);

		const landMatch =
		raw.match(/대지면적\s*([\d,.]+)㎡/) ||
		raw.match(/대지면적\s*([\d,.]+)평/) ||
		raw.match(/대지 면적\s*([\d,.]+)㎡/) ||
		raw.match(/대지 면적\s*([\d,.]+)평/) ||
		raw.match(/\(대지\)\s*([\d,.]+)㎡/) ||
		raw.match(/\(대지\)\s*([\d,.]+)평/) ||
		raw.match(/대지\s*([\d,.]+)㎡/) ||
		raw.match(/대지\s*([\d,.]+)평/);

		const totalValue = totalMatch ? Number(String(totalMatch[1]).replace(/,/g, "")) : null;
		const landValue = landMatch ? Number(String(landMatch[1]).replace(/,/g, "")) : null;

		const totalText = Number.isFinite(totalValue) ? formatSingleAreaValue(totalValue, unit) : null;
		const landText = Number.isFinite(landValue) ? formatSingleAreaValue(landValue, unit) : null;

		if (landText && totalText) {
			return `대지${landText}ㆍ연${totalText}`;
		}
		if (totalText) {
			return `연${totalText}`;
		}
		if (landText) {
			return `대지${landText}`;
		}
		return formatAreaByUnit(areaText, unit, typeText);
	}

	if (/콘도/.test(typeText)) {
		const raw = String(areaText || "-").trim();

		const buildMatch =
		raw.match(/건축면적\s*([\d,.]+)㎡/) ||
		raw.match(/건축면적\s*([\d,.]+)평/) ||
		raw.match(/\(건축\)\s*([\d,.]+)㎡/) ||
		raw.match(/\(건축\)\s*([\d,.]+)평/) ||
		raw.match(/건축\s*([\d,.]+)㎡/) ||
		raw.match(/건축\s*([\d,.]+)평/);

		const totalMatch =
		raw.match(/연면적\s*([\d,.]+)㎡/) ||
		raw.match(/연면적\s*([\d,.]+)평/) ||
		raw.match(/\(연\)\s*([\d,.]+)㎡/) ||
		raw.match(/\(연\)\s*([\d,.]+)평/) ||
		raw.match(/연\s*([\d,.]+)㎡/) ||
		raw.match(/연\s*([\d,.]+)평/);

		const buildValue = buildMatch ? Number(String(buildMatch[1]).replace(/,/g, "")) : null;
		const totalValue = totalMatch ? Number(String(totalMatch[1]).replace(/,/g, "")) : null;

		const buildText = Number.isFinite(buildValue) ? formatSingleAreaValue(buildValue, unit) : null;
		const totalText = Number.isFinite(totalValue) ? formatSingleAreaValue(totalValue, unit) : null;

		if (buildText && totalText) {
			return `건축${buildText}ㆍ연${totalText}`;
		}
		if (buildText) {
			return `건축${buildText}`;
		}
		if (totalText) {
			return `연${totalText}`;
		}
		return formatAreaByUnit(areaText, unit, typeText);
	}

	if (/오피스텔/.test(typeText)) {
		const parsed = parseApartmentAreas(areaText || "-");
		const privateText = Number.isFinite(parsed.private) ? formatSingleAreaValue(parsed.private, unit) : "-";
		const supplyText = Number.isFinite(parsed.supply) ? formatSingleAreaValue(parsed.supply, unit) : "-";
		return formatCardAreaPair("계약", supplyText, privateText);
	}

	if (/원룸|투룸/.test(typeText)) {
		const parsed = parseApartmentAreas(areaText || "-");
		const privateText = Number.isFinite(parsed.private) ? formatSingleAreaValue(parsed.private, unit) : "-";
		const supplyText = Number.isFinite(parsed.supply) ? formatSingleAreaValue(parsed.supply, unit) : "-";
		return formatCardAreaPair(parsed.areaLabel || "공급", supplyText, privateText);
	}

	if (isApartmentType(typeText)) {
		const parsed = parseApartmentAreas(areaText || "-");
		const privateText = Number.isFinite(parsed.private) ? formatSingleAreaValue(parsed.private, unit) : "-";
		const supplyText = Number.isFinite(parsed.supply) ? formatSingleAreaValue(parsed.supply, unit) : "-";
		return formatCardAreaPair(parsed.areaLabel || "공급", supplyText, privateText);
	}

	if (/토지|임야|과수원|목장용지|대지|전|대|답/.test(typeText)) {
		const value = formatAreaByUnit(areaText, unit, typeText);
		const landType = String(typeText || "").trim();

		if (["전", "대", "답", "과수원", "목장용지", "임야"].includes(landType)) {
			return `${value}ㆍ${landType}`;
		}

		return value;
	}
	return formatAreaByUnit(areaText, unit, typeText);
}

function getLandTypeDetailLabel(typeText)
{
	const text = String(typeText || "").trim();
	if (text === "임야") return "임야";
	if (text === "목장용지") return "토지(목장)";
	if (["전", "대", "답", "과수원"].includes(text)) return `토지(${text})`;
	if (["토지", "토지ㆍ임야"].includes(text)) return "토지";
	return text || "-";
}

function setDetailAreaValueHTML(valueText)
{
	if (!detailAreaValue) return;
	const raw = String(valueText || "-").trim();
	const matched = raw.match(/^(\d[\d,]*(?:\.\d+)?)([^0-9].*)$/);

	if (matched) {
		const [, num, rest] = matched;
		detailAreaValue.innerHTML = `<span class="area-num">${num}</span><span class="area-rest">${rest}</span>`;
	} else {
		detailAreaValue.textContent = raw;
	}
}

syncSummaryBadgeRow();

function syncDetailAreaDisplay(detailItem)
{
	if (!detailItem || !detailAreaValue || !detailAreaLabel) return;

	const unit = detailAreaValue.dataset.areaUnit || "m2";
	const typeText = detailItem.type || "";

	if (detailAreaWrap) {
		detailAreaWrap.classList.remove("land-two-line");
	}

	const rawAreaText = String(detailItem.area || "-").trim();
	const landTotalAreas = parseDetachedHouseAreas(rawAreaText);
	const pairedAreas = parseApartmentAreas(rawAreaText);

	if (/공급|계약|전용/.test(rawAreaText) && Number.isFinite(pairedAreas.supply) && Number.isFinite(pairedAreas.private)) {
		const showSupply = detailAreaMode === "supply";
		const targetValue = showSupply ? pairedAreas.supply : pairedAreas.private;

		detailAreaLabel.textContent = showSupply ? `면적(${pairedAreas.areaLabel || "공급"})` : "면적(전용)";
		setDetailAreaValueHTML(formatSingleAreaValue(targetValue, unit));

		if (detailAreaTypeToggleBtn) {
			detailAreaTypeToggleBtn.style.display = "inline-flex";
		}
		return;
	}

	if (!/계약|전용/.test(rawAreaText) && Number.isFinite(landTotalAreas.land) && Number.isFinite(landTotalAreas.total)) {
		const targetValue = detailAreaMode === "land" ? landTotalAreas.land : landTotalAreas.total;

		detailAreaLabel.textContent = detailAreaMode === "land" ? "면적(대지)" : "면적(연)";
		setDetailAreaValueHTML(formatSingleAreaValue(targetValue, unit));

		if (detailAreaTypeToggleBtn) {
			detailAreaTypeToggleBtn.style.display = "inline-flex";
		}
		return;
	}

	if (isDetachedHouseType(typeText)) {
		const parsed = parseDetachedHouseAreas(detailItem.area || "-");
		const targetValue = detailAreaMode === "land" ? parsed.land : parsed.total;

		detailAreaLabel.textContent = detailAreaMode === "land" ? "면적(대지)" : "면적(연)";
		setDetailAreaValueHTML(Number.isFinite(targetValue) ? formatSingleAreaValue(targetValue, unit) : "-");

		if (detailAreaTypeToggleBtn) {
			detailAreaTypeToggleBtn.style.display = "inline-flex";
		}
		return;
	}

	if (isHotelPensionType(typeText)) {
		const parsed = parseApartmentAreas(detailItem.area || "-");
		const showSupply = detailAreaMode === "supply";
		const targetValue = showSupply ? parsed.supply : parsed.private;

		detailAreaLabel.textContent = showSupply ? `면적(${parsed.areaLabel || "계약"})` : "면적(전용)";
		setDetailAreaValueHTML(Number.isFinite(targetValue) ? formatSingleAreaValue(targetValue, unit) : "-");

		if (detailAreaTypeToggleBtn) {
			detailAreaTypeToggleBtn.style.display = "inline-flex";
		}
		return;
	}

	if (isCommercialType(typeText)) {
		const raw = String(detailItem.area || "-").trim();

		if (/계약|전용/.test(raw)) {
			const parsed = parseApartmentAreas(raw);
			const showSupply = detailAreaMode === "supply";
			const targetValue = showSupply ? parsed.supply : parsed.private;

			detailAreaLabel.textContent = showSupply ? `면적(${parsed.areaLabel || "계약"})` : "면적(전용)";
			setDetailAreaValueHTML(Number.isFinite(targetValue) ? formatSingleAreaValue(targetValue, unit) : "-");

			if (detailAreaTypeToggleBtn) {
				detailAreaTypeToggleBtn.style.display = "inline-flex";
			}
			return;
		}

		const parsed = parseDetachedHouseAreas(raw);
		const targetValue = detailAreaMode === "land" ? parsed.land : parsed.total;

		detailAreaLabel.textContent = detailAreaMode === "land" ? "면적(대지)" : "면적(연)";
		setDetailAreaValueHTML(Number.isFinite(targetValue) ? formatSingleAreaValue(targetValue, unit) : "-");

		if (detailAreaTypeToggleBtn) {
			detailAreaTypeToggleBtn.style.display = "inline-flex";
		}
		return;
	}

	if (/콘도/.test(typeText)) {
		const raw = String(detailItem.area || "-").trim();

		const buildMatch =
		raw.match(/건축면적\s*([\d,.]+)㎡/) ||
		raw.match(/건축면적\s*([\d,.]+)평/) ||
		raw.match(/\(건축\)\s*([\d,.]+)㎡/) ||
		raw.match(/\(건축\)\s*([\d,.]+)평/) ||
		raw.match(/건축\s*([\d,.]+)㎡/) ||
		raw.match(/건축\s*([\d,.]+)평/);

		const totalMatch =
		raw.match(/연면적\s*([\d,.]+)㎡/) ||
		raw.match(/연면적\s*([\d,.]+)평/) ||
		raw.match(/\(연\)\s*([\d,.]+)㎡/) ||
		raw.match(/\(연\)\s*([\d,.]+)평/) ||
		raw.match(/연\s*([\d,.]+)㎡/) ||
		raw.match(/연\s*([\d,.]+)평/);

		const buildValue = buildMatch ? Number(String(buildMatch[1]).replace(/,/g, "")) : null;
		const totalValue = totalMatch ? Number(String(totalMatch[1]).replace(/,/g, "")) : null;
		const showBuild = detailAreaMode === "build";
		const targetValue = showBuild ? buildValue : totalValue;

		detailAreaLabel.textContent = showBuild ? "면적(건축)" : "면적(연)";
		setDetailAreaValueHTML(Number.isFinite(targetValue) ? formatSingleAreaValue(targetValue, unit) : "-");

		if (detailAreaTypeToggleBtn) {
			detailAreaTypeToggleBtn.style.display = "inline-flex";
		}
		return;
	}

	if (/오피스텔/.test(typeText)) {
		const parsed = parseApartmentAreas(detailItem.area || "-");
		const showSupply = detailAreaMode === "supply";
		const targetValue = showSupply ? parsed.supply : parsed.private;

		detailAreaLabel.textContent = showSupply ? `면적(${parsed.areaLabel || "계약"})` : "면적(전용)";
		setDetailAreaValueHTML(Number.isFinite(targetValue) ? formatSingleAreaValue(targetValue, unit) : "-");

		if (detailAreaTypeToggleBtn) {
			detailAreaTypeToggleBtn.style.display = "inline-flex";
		}
		return;
	}

	if (isApartmentType(typeText) || /원룸|투룸/.test(typeText)) {
		const parsed = parseApartmentAreas(detailItem.area || "-");
		const showSupply = detailAreaMode === "supply";
		const targetValue = showSupply ? parsed.supply : parsed.private;

		detailAreaLabel.textContent = showSupply ? `면적(${parsed.areaLabel || "공급"})` : "면적(전용)";
		setDetailAreaValueHTML(Number.isFinite(targetValue) ? formatSingleAreaValue(targetValue, unit) : "-");

		if (detailAreaTypeToggleBtn) {
			detailAreaTypeToggleBtn.style.display = "inline-flex";
		}
		return;
	}

	if (/토지|임야|과수원/.test(typeText)) {
		detailAreaLabel.textContent = "면적";
		setDetailAreaValueHTML(formatAreaByUnit(detailItem.area || "-", unit, typeText));

		if (detailAreaWrap) {
			detailAreaWrap.classList.add("land-two-line");
		}

		if (detailAreaTypeToggleBtn) {
			detailAreaTypeToggleBtn.style.display = "none";
		}
		return;
	}

	detailAreaLabel.textContent = "면적";
	setDetailAreaValueHTML(formatAreaByUnit(detailItem.area || "-", unit, typeText));

	if (detailAreaTypeToggleBtn) {
		detailAreaTypeToggleBtn.style.display = "none";
	}

	if (detailAreaToggleBtn) {
		detailAreaToggleBtn.style.display = "none";
		detailAreaToggleBtn.style.display = "none";
	}
}

