async function renderBrokerOfficeOverlays(options = {})
{
	if (!state.map || !window.kakao || !kakao.maps) return;
	let rows = await fetchBrokerOfficeMapRows({ force: !!options.force });
	if (!rows.length) {
		clearBrokerOfficeOverlays();
		console.warn("표시할 중개사무소 위치 데이터가 없습니다. broker_office_locations 데이터를 확인하세요.");
		return;
	}
	if (rows.some(office => !normalizeJejuLatLngPair(office.lat, office.lng))) {
		rows = await backfillBrokerOfficeLatLngRows(rows);
		state.brokerOfficeRows = rows;
	}
	await loadBrokerSpecialtyStats({ force: !!options.force });
	rows = rows.filter(brokerOfficeMatchesSelectedMapFilter);
	if (!rows.length) {
		clearBrokerOfficeOverlays();
		return;
	}
	const mapBounds = getExpandedMapBounds();
	const visibleRows = rows.map((office) => {
		const normalized = normalizeJejuLatLngPair(office.lat, office.lng);
		return normalized ? { ...office, ...normalized } : null;
	}).filter(office => office && isLatLngInsideBounds(office.lat, office.lng, mapBounds));
	if (!visibleRows.length) {
		clearBrokerOfficeOverlays();
		if (!rows.some(office => normalizeJejuLatLngPair(office.lat, office.lng))) {
			console.warn("중개사무소 위치를 표시할 DB 좌표가 없습니다. broker_office_locations lat/lng 값을 확인하세요.", rows.map(office => ({
				officeName: office.officeName,
				address: office.address,
				agencyId: office.agencyId,
				userId: office.userId,
				lat: office.lat,
				lng: office.lng
			})));
		}
		return;
	}

	const entries = spreadBrokerOfficeOverlaysByAddress(visibleRows).slice(0, 120).map((office) => ({
		key: getBrokerOfficeOverlayKey(office),
		zIndex: getFacilityOverlayZIndex("broker"),
		position: normalizeJejuLatLngPair(office.lat, office.lng),
		createOverlay: () => createBrokerOfficeOverlay(office)
	}));
	applyBrokerOfficeOverlayEntries(entries);
	syncFacilityOverlayZIndexes();
}

async function toggleBrokerOfficeMapLayer()
{
	state.isBrokerOfficesVisible = !state.isBrokerOfficesVisible;
	if (!state.isBrokerOfficesVisible) {
		state.brokerOfficeMapFilter = "none";
		clearBrokerOfficeOverlays();
		updateBrokerOfficeToolActiveState();
		return;
	}
	if (!state.brokerOfficeMapFilter || state.brokerOfficeMapFilter === "none") state.brokerOfficeMapFilter = "all";
	bringFacilityOverlayLayerToFront("broker");
	await renderBrokerOfficeOverlays();
	syncFacilityOverlayZIndexes();
	updateBrokerOfficeToolActiveState();
}

