	const isConfiguring = isBrokerOfficeFilterPanelOpen();
	mapBrokerToolBtn.classList.toggle("configuring", isConfiguring);
	mapBrokerToolBtn.classList.toggle("active", !isConfiguring && hasActiveBrokerOfficeMapSelection());
