function renderMarkers(data, options = {})
{
	clearMapObjects();
	if (state.isPropertyMarkersVisible === false) return;

	const preserveViewport = !!options.preserveViewport;
	const markerItems = preserveViewport ? getViewportFilteredItems(data) : (data || []);
	if (!markerItems.length) return;

	const bounds = new kakao.maps.LatLngBounds();
	const markerList = [];

	markerItems.forEach(item => {
		const position = new kakao.maps.LatLng(item.lat, item.lng);

		const marker = new kakao.maps.Marker({
			position,
			image: createMarkerImage(item, normalizeItemId(state.selectedMarkerId) === normalizeItemId(item.id), "1"),
			clickable: true
		});

		marker.__property = item;

	kakao.maps.event.addListener(marker, "click", async function () {
			closeEducationFacilityDetailForPropertyInteraction();
			if (typeof closeRoadviewPanelForPropertyInteraction === "function") {
				await closeRoadviewPanelForPropertyInteraction();
			} else if (typeof hideRoadview === "function") {
				await hideRoadview();
			}
			allowDetailOpenFromListClick = false;
			currentDetailItem = null;
			hardCloseDetailPanel();
			clearAgentListFilter();
			state.leftListDetailMode = "";

			state.selectedClusterKey = null;
			state.selectedMarkerId = null;
			state.selectedMarkerIds = new Set();
			state.selectionMode = "badge-list";
			lockListToItems([item], { keepOnMapClick: true });

			highlightCard(item.id);
			updateMarkerSelection(item.id, [item.id]);

			setTimeout(() => {
				hardCloseDetailPanel();
				openSidebarList();
				resetLeftListPagination([item]);
				propertyList.innerHTML = "";
				loadMoreLeftListItems({ sourceItems: [item] });
				setResultInfo("선택 매물 1건");
				setListInfo("총 1개 매물");
				refreshClusterBadges();
			}, 0);
		});

		markerList.push(marker);
		state.markers.push(marker);
		bounds.extend(position);
	});

	state.clusterer.addMarkers(markerList);

	setTimeout(() => {
		refreshClusterBadges();
	}, 0);

	return;
}

async function openDetailFromUrl({ replaceHistory = true } = {})
{
	const rawSearch = String(window.location.search || "");
	const hasExplicitDetailQuery = /(?:^\?|&)id=/.test(rawSearch);
	const params = new URLSearchParams(rawSearch);
	const targetId = hasExplicitDetailQuery ? normalizeItemId(params.get(DETAIL_QUERY_KEY)) : "";

	if (!hasExplicitDetailQuery || !targetId) {
		setSharedDetailMode(false);
		document.body.classList.remove("direct-detail-list-mode");
		return false;
	}

	setSharedDetailMode(false);

	let item = (state.all || []).find(v => normalizeItemId(v.id) === targetId);
	if (!item) {
		const seedItem = { id: targetId };
		const dbItem = await resolveDetailDataFromDatabase(seedItem);
		if (dbItem && dbItem !== seedItem && normalizeItemId(dbItem.id) === targetId) {
			item = dbItem;
		}
	}
	if (!item) {
		setSharedDetailMode(false);
		document.body.classList.remove("direct-detail-list-mode");
		return false;
	}

	const normalizedTargetId = normalizeItemId(item.id || targetId);
	if (normalizedTargetId) {
		const mergeIntoList = (list) => {
			const source = Array.isArray(list) ? [...list] : [];
			const index = source.findIndex(candidate => normalizeItemId(candidate && candidate.id) === normalizedTargetId);
			if (index >= 0) {
				source[index] = { ...source[index], ...item };
				return source;
			}
			return [item, ...source];
		};
		state.all = mergeIntoList(state.all);
		state.filtered = mergeIntoList(state.filtered);
	}

	closeEducationFacilityDetailForPropertyInteraction();
	if (typeof closeRoadviewPanelForPropertyInteraction === "function") {
		await closeRoadviewPanelForPropertyInteraction();
	} else if (typeof hideRoadview === "function") {
		await hideRoadview();
	}
	document.body.classList.add("direct-detail-list-mode");
	document.body.classList.remove("sidebar-list-collapsed");
	state.selectionMode = "single";
	state.selectedClusterKey = null;
	state.selectedMarkerId = targetId;
	state.selectedMarkerIds = new Set([targetId]);
	lockListToItems([item]);
	openSidebarList();
	resetLeftListPagination([item]);
	propertyList.innerHTML = "";
	await loadMoreLeftListItems({ sourceItems: [item] });
	setResultInfo("선택 매물 1건");
	setListInfo("총 1개 매물");
	highlightCard(targetId);
	updateMarkerSelection(targetId, [targetId]);

	if (detailScroll) detailScroll.scrollTop = 0;
	await openDetailPanel(item, { syncUrl: false, forceOpen: true, overlayPage: false });
	document.body.classList.add("direct-detail-list-mode");
	document.body.classList.remove("sidebar-list-collapsed");
	state.isListOpen = true;
	if (sidebar) sidebar.classList.add("expanded");
	updateSidebarWidth();
	if (typeof syncMapFilterbarDetailHidden === "function") syncMapFilterbarDetailHidden();
	if (typeof scheduleMapFilterScrollSync === "function") scheduleMapFilterScrollSync();
	if (typeof refreshMapLayout === "function") {
		refreshMapLayout();
		setTimeout(refreshMapLayout, 120);
	}

	if (replaceHistory) {
		syncDetailUrl(item.id, { replace: true });
	}

	if (detailScroll) detailScroll.scrollTop = 0;
	await focusProperty(item.id);

	setTimeout(() => {
		document.body.classList.add("direct-detail-list-mode");
		document.body.classList.remove("sidebar-list-collapsed");
		state.isListOpen = true;
		updateSidebarWidth();
		if (typeof syncMapFilterbarDetailHidden === "function") syncMapFilterbarDetailHidden();
		if (typeof scheduleMapFilterScrollSync === "function") scheduleMapFilterScrollSync();
		highlightCard(targetId);
		refreshClusterBadges();
	}, 0);

	return true;
}

async function focusProperty(id)
{
	const normalizedId = normalizeItemId(id);
	const findById = (list) => Array.isArray(list)
		? list.find(v => normalizeItemId(v && v.id) === normalizedId)
		: null;
	const item = findById(state.filtered)
		|| findById(state.all)
		|| findById(state.leftListItems)
		|| (currentDetailItem && normalizeItemId(currentDetailItem.id) === normalizedId ? currentDetailItem : null);
	if (!state.map) return;

	closeEducationFacilityDetailForPropertyInteraction();
	if (typeof closeRoadviewPanelForPropertyInteraction === "function") {
		await closeRoadviewPanelForPropertyInteraction();
	} else if (typeof hideRoadview === "function") {
		await hideRoadview();
	}

	state.selectionMode = "single";
	state.selectedClusterKey = null;
	updateMarkerSelection(id, [normalizedId]);

	highlightCard(id);
	if (item) await focusRecentViewedListingOnMap(item, normalizedId);

	setTimeout(() => {
		refreshClusterBadges();
	}, 0);
}

async function moveMapToProperty(item)
{
	if (!item || !state.map || !window.kakao || !kakao.maps) return;
	const lat = Number(item.lat);
	const lng = Number(item.lng);
	if (!Number.isFinite(lat) || !Number.isFinite(lng)) return;

	closeEducationFacilityDetailForPropertyInteraction();
	if (typeof closeRoadviewPanelForPropertyInteraction === "function") {
		await closeRoadviewPanelForPropertyInteraction();
	} else if (typeof hideRoadview === "function") {
		await hideRoadview();
	}
	const position = new kakao.maps.LatLng(lat, lng);
	state.map.panTo(position);
}

