	function openShareMenu(payload = null, anchorEl = detailShareBtn)
	{
		if (!detailShareMenu || !detailShareBtn) return;
		activeDetailSharePayload = payload && typeof payload === "object" ? payload : null;
		if (detailShareMenu.parentElement !== document.body) {
			document.body.appendChild(detailShareMenu);
		}
		detailShareMenu.style.display = "flex";
		detailShareMenu.classList.add("open");
		detailShareMenu.setAttribute("aria-hidden", "false");
		detailShareMenu.style.position = "fixed";
		const anchor = anchorEl && typeof anchorEl.getBoundingClientRect === "function" ? anchorEl : detailShareBtn;
		const rect = anchor.getBoundingClientRect();
		const menuWidth = 260;
		const gap = 12;
		const left = Math.max(12, Math.min(window.innerWidth - menuWidth - 12, rect.right - menuWidth));
		const top = Math.max(12, Math.min(window.innerHeight - 170, rect.bottom + gap));
		detailShareMenu.style.top = `${Math.round(top)}px`;
		detailShareMenu.style.left = `${Math.round(left)}px`;
		detailShareMenu.style.right = "auto";
		detailShareMenu.style.visibility = "visible";
	}

	function closeShareMenu()
	{
		if (!detailShareMenu) return;
		activeDetailSharePayload = null;
		detailShareMenu.classList.remove("open");
		detailShareMenu.style.display = "none";
		detailShareMenu.style.visibility = "hidden";
		detailShareMenu.setAttribute("aria-hidden", "true");
	}

	window.closeDetailShareMenu = function (event) {
		if (event) {
			event.preventDefault();
			event.stopPropagation();
		}
		closeShareMenu();
	};

	window.openDetailShareMenuForPayload = function (payload, anchorEl) {
		openShareMenu(payload, anchorEl);
	};

	function toggleShareMenu()
	{
		if (!detailShareMenu) return;
		const isOpen = detailShareMenu.style.display === "flex" || detailShareMenu.classList.contains("open");
		if (isOpen) {
			closeShareMenu();
		} else {
			openShareMenu(null, detailShareBtn);
		}
	}

	if (detailShareBtn) {
		detailShareBtn.addEventListener("click", (e) => {
			e.preventDefault();
			e.stopPropagation();
			toggleShareMenu();
		});
	}

