		const accountMenuItem = e.target.closest(".global-account-menu-item[data-account-action]");
		const sideAccountMenu = document.getElementById("realjejuSideAccountMenu");
		const isGlobalAccountMenuItem = accountMenuItem && globalAccountDropdown && globalAccountDropdown.contains(accountMenuItem);
