	function buildAdminApplicationProfileMap(rows)
	{
		const map = new Map();
		(Array.isArray(rows) ? rows : []).forEach((row) => {
			const id = String(row && row.id || "").trim();
			if (!id) return;
			map.set(id, row);
		});
		return map;
	}

	function buildAdminApplicationProfileEmailMap(rows)
	{
		const map = new Map();
		(Array.isArray(rows) ? rows : []).forEach((row) => {
			const email = String(row && row.email || "").trim().toLowerCase();
			if (!email) return;
			map.set(email, row);
		});
		return map;
	}

	async function fetchAdminUserRowsByIds(client, userIds)
	{
		if (!client) return [];
		const idSet = new Set(Array.isArray(userIds) ? userIds : []);
		const ids = Array.from(idSet).map((id) => String(id || "").trim()).filter(Boolean);
		if (!ids.length) return [];
		const rows = [];
		for (let i = 0; i < ids.length; i += 100) {
			const chunk = ids.slice(i, i + 100);
			const { data, error } = await client
				.from("profiles")
				.select("id, name, email, role, role_request, status, profile_image")
				.in("id", chunk);
			if (error) {
				console.warn("관리자 신청 조회 프로필 행 조회 실패:", error);
				continue;
			}
			(Array.isArray(data) ? data : []).forEach((row) => {
				const id = String(row && row.id || "").trim();
				if (id) rows.push(row);
			});
		}
		return rows;
	}

	async function fetchAdminUserRowsByEmails(client, emails)
	{
		if (!client) return [];
		const emailSet = new Set(Array.isArray(emails) ? emails : []);
		const values = Array.from(emailSet).map((email) => String(email || "").trim().toLowerCase()).filter(Boolean);
		if (!values.length) return [];
		const rows = [];
		for (let i = 0; i < values.length; i += 100) {
			const chunk = values.slice(i, i + 100);
			const { data, error } = await client
				.from("profiles")
				.select("id, name, email, role, role_request, status, profile_image")
				.in("email", chunk);
			if (error) {
				console.warn("관리자 신청 조회 프로필 이메일 조회 실패:", error);
				continue;
			}
			(Array.isArray(data) ? data : []).forEach((row) => {
				const email = String(row && row.email || "").trim();
				if (email) rows.push(row);
			});
		}
		return rows;
	}

	async function fetchAdminUserRowsForApplicationProfiles(client, candidateUserIds, options = {})
	{
		if (Array.isArray(adminUserRowsCache) && adminUserRowsCache.length) return adminUserRowsCache;
		if (!client) return [];
		const useRpc = options.useRpc !== false;
		const candidateIds = Array.isArray(candidateUserIds)
			? Array.from(new Set(candidateUserIds.map((id) => String(id || "").trim()).filter(Boolean)))
			: [];

		if (candidateIds.length) {
			const directRows = await fetchAdminUserRowsByIds(client, candidateIds);
			if (directRows.length) {
				if (!Array.isArray(adminUserRowsCache)) adminUserRowsCache = directRows;
				return directRows;
			}
		}

		if (!useRpc) return [];

		const { data, error } = await client.rpc("get_admin_users");
		if (error) {
			console.warn("관리자 중개사무소 신청 회원관리 프로필 조회 실패:", error);
			const fallbackRows = await fetchAdminUserRowsByIds(client, candidateIds);
			if (!adminUserRowsCache && fallbackRows.length) adminUserRowsCache = fallbackRows;
			return fallbackRows;
		}
		const rows = Array.isArray(data) ? data : [];
		if (!Array.isArray(adminUserRowsCache) && rows.length) adminUserRowsCache = rows;
		return rows;
	}

	async function enrichAdminApplicationsWithProfiles(client, rows, options = {})
	{
		const list = Array.isArray(rows) ? rows : [];
		if (!client || !list.length) return list;
		const userIds = Array.from(new Set(list
			.map((row) => String(row && row.user_id || "").trim())
			.filter(Boolean)));
		const emails = Array.from(new Set(list
			.map((row) => String(row && row.email || "").trim().toLowerCase())
			.filter(Boolean)));
		if (!userIds.length && !emails.length) return list;
		const profileRows = [
			...(userIds.length ? await fetchAdminUserRowsForApplicationProfiles(client, userIds, options) : []),
			...(emails.length ? await fetchAdminUserRowsByEmails(client, emails) : [])
		];
		const profilesById = buildAdminApplicationProfileMap(profileRows);
		const profilesByEmail = buildAdminApplicationProfileEmailMap(profileRows);
		const shouldLookupMissingProfilePhoto = options.skipProfilePhotoLookup !== true;
		if (!shouldLookupMissingProfilePhoto) return list.map((row) => {
			const userId = String(row && row.user_id || "").trim();
			const email = String(row && row.email || "").trim().toLowerCase();
			const profile = (userId ? profilesById.get(userId) : null) || (email ? profilesByEmail.get(email) : null);
			if (!profile) return row;
			return {
				...row,
				profile_name: row.profile_name || profile.name || "",
				profile_image: row.profile_image || profile.profile_image || "",
				profile_photo: row.profile_photo || profile.profile_photo || "",
				avatar_url: row.avatar_url || profile.avatar_url || ""
			};
		});

		for (let i = 0; i < userIds.length; i += 100) {
			const chunk = userIds.slice(i, i + 100).filter((id) => {
				const profile = profilesById.get(id);
				return !profile || !getAdminApplicationProfileImage(profile);
			});
			if (!chunk.length) continue;
			const { data, error } = await client
				.from("profiles")
				.select("id, name, profile_image")
				.in("id", chunk);
			if (error) {
				console.warn("관리자 중개사무소 신청 프로필 사진 조회 실패:", error);
				continue;
			}
			(Array.isArray(data) ? data : []).forEach((profile) => {
				const id = String(profile && profile.id || "").trim();
				if (id) profilesById.set(id, profile);
			});
		}
		if (!profilesById.size && !profilesByEmail.size) return list;
		return list.map((row) => {
			const userId = String(row && row.user_id || "").trim();
			const email = String(row && row.email || "").trim().toLowerCase();
			const profile = (userId ? profilesById.get(userId) : null) || (email ? profilesByEmail.get(email) : null);
			if (!profile) return row;
			return {
				...row,
				profile_name: row.profile_name || profile.name || "",
				profile_image: row.profile_image || profile.profile_image || "",
				profile_photo: row.profile_photo || profile.profile_photo || "",
				avatar_url: row.avatar_url || profile.avatar_url || ""
			};
		});
	}

